function loadEntries(): Map<string, GeminiCacheStateEntry> {
    if (entries) return entries
    entries = new Map()
    const now = Date.now()
    let needsPersist = false
    try {
        const raw = globalThis.localStorage?.getItem(STORAGE_KEY)
        if (raw) {
            const parsed: unknown = JSON.parse(raw)
            if (isPlainObject(parsed)) {
                for (const [key, value] of Object.entries(parsed)) {
                    if (!isValidEntry(value) || value.expiresAt <= now) {
                        needsPersist = true
                        continue
                    }
                    entries.set(key, value)
                    // The consecutive-invalidation guard is in-memory only and
                    // resets on reload by design (see the session-guards block) —
                    // nothing about it is restored here.
                }
                if (entries.size > GEMINI_CACHE_SESSION_STATE_LIMIT) {
                    trimOldest(entries, GEMINI_CACHE_SESSION_STATE_LIMIT)
                    needsPersist = true
                }
            }
        }
    } catch {
        // unreadable / corrupt mirror → start empty
    }
    // Loading after a server restart used to skip expired records only in memory, leaving their KV
    // mirror to grow forever until some unrelated cache write happened. Compact immediately.
    if (needsPersist) persistEntries()
    return entries
}
