/* BG-PRESERVE:START gemini-cache-prune-expired */
// Prune every expired entry on each participating turn. The server process can stay alive across
// many chats; deleting only the requested key would let old chat/preset entries grow forever.
export function getGeminiCacheEntry(key: string, now: number = Date.now()): GeminiCacheStateEntry | undefined {
    const store = loadEntries()
    let pruned = false
    for (const [storedKey, entry] of store) {
        if (entry.expiresAt <= now) {
            store.delete(storedKey)
            pruned = true
        }
    }
    if (pruned) persistEntries()
    return store.get(key)
}
/* BG-PRESERVE:END */

