export function isGeminiCacheSessionDisabled(key: string, credentialFp?: string): boolean {
    if (!disabledSessions.has(key)) return false
    const disabledFor = disabledSessions.get(key)
    return disabledFor === null || credentialFp === undefined || disabledFor === credentialFp
}

// Disables caching for the rest of this chat session. Two callers: the
// dynamic-prompt guard (GEMINI_CACHE_INVALIDATION_LIMIT consecutive prefix
// mismatches) and a 403 on cache creation (the project/key cannot use
// cachedContents at all). Both are futile to keep retrying.
export function disableGeminiCacheSession(
    key: string,
    reason = 'unrecoverable cache state',
    credentialFp: string | null = null,
): void {
    const existing = disabledSessions.get(key)
    if (disabledSessions.has(key) && (existing === null || existing === credentialFp)) return
    disabledSessions.delete(key)
    disabledSessions.set(key, credentialFp)
    trimOldest(disabledSessions, GEMINI_CACHE_SESSION_STATE_LIMIT)
    console.warn(`[gemini-cache] context caching disabled for this chat session — ${reason} (${key}).`)
}

function trimOldest<T>(collection: Map<string, T> | Set<string>, limit: number): void {
    while (collection.size > limit) {
        const oldest = collection.keys().next().value
        if (oldest === undefined) return
        collection.delete(oldest)
    }
}
