            if (isTerminalPhase(s.phase)) continue
            keep.add(s.id)
            // Rebase the server-clock startedAt onto the client clock via the server-reported
            // elapsedMs (the toast shows clientNow - startedAt; a lagging client clock would read
            // 0.0s otherwise). Falls back to the raw startedAt if elapsedMs is absent.
            // S3: rebase ONCE on first ingest, then keep startedAt stable — recomputing
            // Date.now()-elapsedMs every poll drifts startedAt per poll → the banner's elapsed jitters.
            const prev = next.get(s.id)
            const started = (prev && prev.relayed)
                ? prev.startedAt
                : (typeof s.elapsedMs === 'number' && s.elapsedMs >= 0 ? Date.now() - s.elapsedMs : s.startedAt)
            next.set(s.id, {
                id: s.id,
                chatId: s.chatId,
                kind: s.kind,
                label: s.label,
                phase: s.phase,
                thinkingTokens: s.thinkingTokens ?? 0,
                responseTokens: s.responseTokens ?? 0,
                tokPerSec: s.tokPerSec ?? 0,
                startedAt: started,
                lastChunkAt: started,
                endedAt: s.endedAt,
                retryAttempt: s.retryAttempt,
                badges: Array.isArray(s.badges) ? s.badges : [],
                error: s.error,
                thinkingText: '', responseText: '', textDirty: false, tokenSamples: [],
                relayed: true,
            })
        }
        // Drop relayed entries the server no longer reports (consumed/cleared upstream).
        for (const [id, e] of next) if (e.relayed && !keep.has(id)) next.delete(id)
        return next
    })
}
