units.content:
// BG-PRESERVE module — preserve & restore streaming LLM responses lost when the
// app is backgrounded on mobile (iOS Safari freezes/evicts the page mid-stream).
//
// Capture: on visibilitychange(hidden)/pagehide we synchronously snapshot any
// in-progress streaming response (a `char` message in a chat with isStreaming).
//   - localStorage  → sync write, always completes even as the page backgrounds
//                     (this is the core fix: the existing server save path uses a
//                      non-keepalive async fetch that the OS freezes before it lands)
//   - sendBeacon    → cross-device delivery, guaranteed even during backgrounding
// Restore: on load / visible we scan both sources, hydrate the target chat from the
// server, and only flag drafts that are genuinely lost. The user confirms via banner.
//
// This file is owned by the BG-PRESERVE patch (not part of upstream PocketRisu),
// so an upstream update never overwrites it — only the few one-line hooks need
// re-applying via bg-preserve-install.cjs.

import { get } from 'svelte/store'
import { DBState, selectedCharID } from './stores.svelte'
import { requestImmediateSave, setBgStreamFetchImpl, reportBgPreserveSignal } from './globalApi.svelte'
import { ensureChatHydrated } from './storage/chatStorage'
import { fetchViaBgStreamJob, isBgStreamEnabled, abortGen, bgRecoveringMainGens } from './bgStreamFetch'

export interface BgStreamDraft {
    key: string
    charId: string
    chatId: string
    charName?: string
    generationId?: string
    model?: string
    // token meta (carried from generation start via setBgGenContext → job meta) so the
    // restored message's generationInfo shows tokens instead of '?'.
    inputTokens?: number
    outputTokens?: number
    maxContext?: number
    data: string
    time: number
    // true when the server received the whole response (bgStreamJob done). Only final
    // drafts auto-recover; partial client captures wait for the final to supersede them.
    final?: boolean
}

const LS_PREFIX = 'bg-stream-draft:'
const SERVER_PATH = '/api/bg-stream-draft'

// Reactive list of drafts that look genuinely lost and need user action.
export const bgRestoreState = $state<{ candidates: BgStreamDraft[] }>({ candidates: [] })

function draftKey(charId: string, chatId: string): string {
    return `${charId}::${chatId}`
}

// ---------------------------------------------------------------- capture

function collectStreamingDrafts(): BgStreamDraft[] {
    const out: BgStreamDraft[] = []
    const chars: any[] = (DBState as any)?.db?.characters ?? []
    for (const ch of chars) {
        const charId: string | undefined = ch?.chaId
        const chats: any[] | undefined = ch?.chats
        if (!charId || !Array.isArray(chats)) continue
        for (const chat of chats) {
            if (!chat?.isStreaming) continue
            const chatId: string | undefined = chat?.id
            if (!chatId) continue
            const msgs: any[] | undefined = chat?.message
            if (!Array.isArray(msgs) || msgs.length === 0) continue
            const last = msgs[msgs.length - 1]
            if (!last || last.role !== 'char') continue
            const data: string = typeof last.data === 'string' ? last.data : ''
            if (!data) continue // nothing streamed yet → nothing to preserve
            out.push({
                key: draftKey(charId, chatId),
                charId,
                chatId,
                charName: typeof ch?.name === 'string' ? ch.name : undefined,
                generationId: typeof last.chatId === 'string' ? last.chatId : undefined,
                data,
                time: Date.now(),
            })
        }
    }
    return out
}

function persistDraftLocal(draft: BgStreamDraft): void {
    try {
        localStorage.setItem(LS_PREFIX + draft.key, JSON.stringify(draft))
    } catch {
        // storage full / disabled — best-effort
    }
}

function persistDraftServer(draft: BgStreamDraft): void {
    try {
        const blob = new Blob([JSON.stringify(draft)], { type: 'application/json' })
        // sendBeacon guarantees delivery even as the page is being backgrounded;
        // cookies (session auth) are sent automatically for same-origin.
        if (typeof navigator !== 'undefined' && navigator.sendBeacon) {
            navigator.sendBeacon(SERVER_PATH, blob)
        } else {
            void fetch(SERVER_PATH, {
                method: 'POST',
                body: blob,
                keepalive: true,
                credentials: 'same-origin',
            }).catch(() => {})
        }
    } catch {
        // ignore best-effort failures
    }
}

// Called synchronously on background/hide. The localStorage write is synchronous
// and therefore always completes before the OS freezes the page.
function captureNow(): void {
    const drafts = collectStreamingDrafts()
    for (const d of drafts) {
        persistDraftLocal(d)
        persistDraftServer(d)
    }
}

// ---------------------------------------------------------------- restore

function readLocalDrafts(): BgStreamDraft[] {
    const out: BgStreamDraft[] = []
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i)
            if (!k || !k.startsWith(LS_PREFIX)) continue
            const v = localStorage.getItem(k)
            if (!v) continue
            try {
                out.push(JSON.parse(v))
            } catch {
                // corrupt entry → drop it
                try { localStorage.removeItem(k) } catch {}
            }
        }
    } catch {
        // localStorage unavailable
    }
    return out
}

async function readServerDrafts(): Promise<BgStreamDraft[]> {
    try {
        const r = await fetch(SERVER_PATH, { method: 'GET', credentials: 'same-origin' })
        if (!r.ok) return []
        const j = await r.json()
        if (Array.isArray(j)) return j
        if (Array.isArray(j?.drafts)) return j.drafts
        return []
    } catch {
        return []
    }
}

function mergeDrafts(a: BgStreamDraft[], b: BgStreamDraft[]): BgStreamDraft[] {
    const map = new Map<string, BgStreamDraft>()
    for (const d of [...a, ...b]) {
        if (!d?.key) continue
        const ex = map.get(d.key)
        // prefer the longer partial; tie-break on freshest capture time
        const dLen = d.data?.length ?? 0
        const exLen = ex?.data?.length ?? 0
        if (!ex || dLen > exLen || (dLen === exLen && (d.time ?? 0) > (ex.time ?? 0))) {
            map.set(d.key, d)
        }
    }
    return [...map.values()]
}

function findCharChat(draft: BgStreamDraft): { charIdx: number; chatIdx: number } | null {
    const chars: any[] = (DBState as any)?.db?.characters ?? []
    const charIdx = chars.findIndex((c) => c?.chaId === draft.charId)
    if (charIdx < 0) return null
    const chats: any[] | undefined = chars[charIdx]?.chats
    if (!Array.isArray(chats)) return null
    const chatIdx = chats.findIndex((c) => c?.id === draft.chatId)
    if (chatIdx < 0) return null
    return { charIdx, chatIdx }
}

function findGenIdx(msgs: any[], generationId?: string): number {
    if (!generationId) return -1
    return msgs.findIndex((m) => m?.chatId === generationId)
}

// A draft is "lost" if, after hydration, the live chat has no matching message
// or a shorter one than what we preserved. (If the server already has an equal/
// longer completed message, the stream finished normally → not lost.)
function isLost(draft: BgStreamDraft): boolean {
    const loc = findCharChat(draft)
    if (!loc) return false
    const chat: any = (DBState as any).db.characters[loc.charIdx].chats[loc.chatIdx]
    const msgs: any[] = chat?.message ?? []
    const idx = findGenIdx(msgs, draft.generationId)
    if (idx < 0) return true
    const cur: string = msgs[idx]?.data ?? ''
    return draft.data.length > cur.length
}

export async function restoreDraft(draft: BgStreamDraft, opts: { navigate?: boolean } = {}): Promise<void> {
    const navigate = opts.navigate !== false // default: jump to the chat (manual restore)
    // Abort the ORIGINAL request for THIS draft's generation (gen-scoped → unrelated chats
    // untouched). On return from background the original often retries and pushes a second,
    // duplicate copy of the recovered message (the index 46/47 case); aborting its generation
    // stops that. FOLD is re-applied via runTrigger('start') below, so killing the original
    // main request is safe. No-op if the generation already settled.
    try { abortGen(draft.generationId) } catch { /* best-effort */ }
    const loc = findCharChat(draft)
    if (loc) {
        const char: any = (DBState as any).db.characters[loc.charIdx]
        try {
            // Pull the real messages from the server before mutating (the chat may
            // be a placeholder stub with an empty message array).
            await ensureChatHydrated(char.chats, loc.chatIdx, char.chaId)
        } catch {
            // hydration failed — proceed best-effort with whatever is loaded
        }
        const chat: any = char.chats[loc.chatIdx]
        const msgs: any[] = chat.message
        const idx = findGenIdx(msgs, draft.generationId)
        if (idx >= 0 && (msgs[idx]?.data?.length ?? 0) >= draft.data.length) {
            // The original main response already landed normally (equal/longer) →
            // don't duplicate it; just clear the draft.
            await dismissDraft(draft)
            return
        }
        if (idx >= 0) {
            msgs[idx].data = draft.data
            if (!msgs[idx].generationInfo) {
                msgs[idx].generationInfo = { model: draft.model, generationId: draft.generationId, inputTokens: draft.inputTokens, outputTokens: draft.outputTokens, maxContext: draft.maxContext }
            }
        } else {
            msgs.push({
                role: 'char',
                data: draft.data,
                chatId: draft.generationId,
                time: draft.time,
                generationInfo: { model: draft.model, generationId: draft.generationId, inputTokens: draft.inputTokens, outputTokens: draft.outputTokens, maxContext: draft.maxContext },
            })
        }
        chat.isStreaming = false
        // Persist explicitly: the target chat may not be the active one, so the
        // active-chat autosave effect would not pick it up.
        try { requestImmediateSave() } catch {}
        // Bring the user to the restored chat so they can see the result — manual restore
        // only. Auto-recovery stays silent (navigate:false) so it never yanks the view away
        // from a different chat the user is currently reading.
        if (navigate) {
            try {
                selectedCharID.set(loc.charIdx)
                char.chatPage = loc.chatIdx
            } catch {}
        }
        // Re-run 'start' triggers (e.g. FOLD: aux-model classification → setChatVar)
        // so module side-effects apply to the recovered message. These call only the
        // auxiliary model (axLLM), not the main model, so no main-response duplication.
        try {
            const { runTrigger } = await import('./process/triggers')
            const r: any = await runTrigger(char, 'start', { chat })
            if (r && r.chat) {
                char.chats[loc.chatIdx] = r.chat
                try { requestImmediateSave() } catch {}
            }
        } catch (e) {
            console.warn('[bg-preserve] start-trigger replay failed:', e)
        }
    }
    await dismissDraft(draft)
}

export async function dismissDraft(draft: BgStreamDraft): Promise<void> {
    try { localStorage.removeItem(LS_PREFIX + draft.key) } catch {}
    try {
        await fetch(SERVER_PATH + '/delete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            credentials: 'same-origin',
            body: JSON.stringify({ charId: draft.charId, chatId: draft.chatId, key: draft.key }),
        })
    } catch {
        // best-effort
    }
    bgRestoreState.candidates = bgRestoreState.candidates.filter((d) => d.key !== draft.key)
}

export async function restoreAll(): Promise<void> {
    for (const d of [...bgRestoreState.candidates]) {
        await restoreDraft(d)
    }
}

export async function dismissAll(): Promise<void> {
    for (const d of [...bgRestoreState.candidates]) {
        await dismissDraft(d)
    }
}

let scanning = false
async function scanForLostDrafts(): Promise<void> {
    if (scanning) return
    scanning = true
    try {
        // Option A: the banner appears immediately on return — we no longer defer while a
        // generation is in progress. isLost() below still suppresses the banner when the
        // original response already landed (equal/longer), so a short background the
        // original survives produces no noise. If the user taps [restore] while the
        // original is still alive, restoreDraft() aborts it first (+ generationId dedup).
        const merged = mergeDrafts(readLocalDrafts(), await readServerDrafts())
        const lost: BgStreamDraft[] = []
        for (const d of merged) {
            const loc = findCharChat(d)
            if (!loc) {
                // chat no longer exists (deleted) → clean up silently
                await dismissDraft(d)
                continue
            }
            const char: any = (DBState as any).db.characters[loc.charIdx]
            try {
                await ensureChatHydrated(char.chats, loc.chatIdx, char.chaId)
            } catch {
                // if hydration fails, fall through and treat conservatively
            }
            if (isLost(d)) {
                lost.push(d)
            } else {
                await dismissDraft(d)
            }
        }
        // Auto-recover only server-completed drafts (final = the server received the whole
        // response). At that point the server job has finished, so restoreDraft's abort is a
        // no-op and there's no risk of recovering a partial. Partial captures (client
        // snapshot, final falsy) are left as banner fallback — they get superseded by the
        // final draft shortly. Auto-recovery is silent (no view navigation).
        const remaining: BgStreamDraft[] = []
        for (const d of lost) {
            // T2-a: B(원래 흐름 복구)가 진행 중인 gen이면 자동복구 보류 → 중복(index 46/47) 방지.
            // doingChat true→false 재scan에서 B settle 후 처리(성공=isLost false로 dismiss, 실패=복구).
            if (d.generationId && bgRecoveringMainGens.has(d.generationId)) {
                continue
            }
            if (d.final) {
                // T3-b: auto-recovery is the most silent failure — the user never clicked anything,
                // so a throw here would vanish. Surface it (the banner-click path is user-visible).
                try { await restoreDraft(d, { navigate: false }) } catch (e) { reportBgPreserveSignal('restore-fail', String((e as any)?.message ?? e).slice(0, 120)) }
            } else {
                remaining.push(d)
            }
        }
        bgRestoreState.candidates = remaining
    } finally {
        scanning = false
    }
}

// ---------------------------------------------------------------- setup

let inited = false
export function initBgStreamPreserve(): void {
    if (inited) return
    inited = true
    // Stage B: register the background-resilient streaming fetch (gemini) unless the
    // runtime toggle is off. fetchNative calls this impl when set.
    try {
        if (isBgStreamEnabled()) {
            setBgStreamFetchImpl(fetchViaBgStreamJob)
        }
    } catch { /* best-effort */ }
    if (typeof document !== 'undefined') {
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'hidden') {
                captureNow()
            } else if (document.visibilityState === 'visible') {
                void scanForLostDrafts()
            }
        })
        if (typeof window !== 'undefined') {
            window.addEventListener('pagehide', captureNow)
        }
    }
    // Initial scan. Chats may still be hydrating on first load, so scan once now
    // and again shortly after.
    void scanForLostDrafts()
    setTimeout(() => { void scanForLostDrafts() }, 2500)
    // Re-scan when a generation finishes (true→false). scanForLostDrafts defers while
    // a generation is in progress (the original is likely alive). On load-failed the
    // original dies → doingChat flips to false → this re-scan surfaces the banner that
    // was deferred, so the originating device also gets the recovery prompt.
    void (async () => {
        try {
            const idxMod = await import('./process/index.svelte')
            let prev = get(idxMod.doingChat)
            idxMod.doingChat.subscribe((v: boolean) => {
                if (prev && !v) { setTimeout(() => { void scanForLostDrafts() }, 300) }
                prev = v
            })
        } catch { /* best-effort */ }
    })()
}

// BG-PRESERVE (Stage B) — client side.
//
// Routes an external LLM streaming request through our server-side job endpoint
// (POST /api/bg-stream-job) instead of the plain pipe, so the server keeps receiving
// the stream after the mobile client backgrounds/disconnects. The live stream is
// delivered over the EXISTING WebSocket (/proxy-stream-jobs/:id/ws — the job we create
// lands in the same server-side job Map). If the client backgrounds, the WS just
// closes (no DELETE → the server job keeps running and persists the result to kv).
// Sub/main model calls reconnect to the exact job and, when its replay is incomplete or already
// GC'd, append the missing suffix from the authoritative `bg-sub-result:` raw response.
//
// Owned by the BG-PRESERVE patch (not upstream PocketRisu). Registered into globalApi
// via setBgStreamFetchImpl (impl-register pattern, like requestImmediateSaveImpl) to
// avoid an import cycle.

import { get } from 'svelte/store'
import { forageStorage } from './globalApi.svelte'
import { DBState, selectedCharID } from './stores.svelte'
import { parseProxyJobWsEvent, decodeProxyJobWsChunk, formatProxyStreamErrorMessage } from './network/proxyJobWs'
import { recoveredResponseWithAck } from './bgResponseAck'
import {
    classifyRawStreamRecoveryRecord,
    reconcileStreamChunk,
    streamCompletionNeedsRecovery,
} from './bgStreamRecovery'

const BG_HEARTBEAT_SEC = 15

// T2-a: 백그라운드 복구가 진행 중(Promise pending = 응답 headers 도착 전 = §8.3 중복 시점)인 메인 생성의
// generationId 집합. scanForLostDrafts가 이 gen의 final draft 자동복구를 보류해 B(원래 흐름 복구)와의
// 중복(index 46/47)을 막음. settle 시 Promise.finally 단일 지점에서 삭제 → delete 누락 0(timeout 불필요).
export const bgRecoveringMainGens = new Set<string>()

// generationId → chat coordinates, registered by index.svelte.ts when a generation
// starts (fetchNative only carries generationId as `chatId`, not charId/chat.id).
interface BgGenCtx { charId?: string; chatId?: string; charName?: string; inputTokens?: number; outputTokens?: number; maxContext?: number }
const bgGenContext = new Map<string, BgGenCtx>()

export function setBgGenContext(generationId: string, ctx: BgGenCtx): void {
    if (!generationId) return
    bgGenContext.set(generationId, ctx)
    // bound memory: keep only the most recent ~50 generations
    if (bgGenContext.size > 50) {
        const firstKey = bgGenContext.keys().next().value
        if (firstKey !== undefined) bgGenContext.delete(firstKey)
    }
}

export function getBgGenContext(generationId: string): BgGenCtx | undefined {
    return bgGenContext.get(generationId)
}

export function clearBgGenContext(generationId: string): void {
    if (generationId) bgGenContext.delete(generationId)
}

// The chat screen registers the current sendChat's AbortController.abort here while a
// generation runs. bindGenToActiveAbort() then snapshots it under that generation's id,
// so recovery can abort EXACTLY the original request for a given draft (not the global
// last one). A still-retrying original would otherwise push a duplicate of the recovered
// message (the index 46/47 case). FOLD is re-applied via runTrigger('start') in
// restoreDraft, so killing the original main request is safe.
let pendingChatAbort: (() => void) | null = null
export function setActiveChatAbort(fn: (() => void) | null): void {
    pendingChatAbort = fn
}
// generationId → that request's abort fn (snapshot of pendingChatAbort at generation start).
const genAbortMap = new Map<string, () => void>()
export function bindGenToActiveAbort(gen: string): void {
    if (!gen || !pendingChatAbort) return
    genAbortMap.set(gen, pendingChatAbort)
    if (genAbortMap.size > 50) {
        const first = genAbortMap.keys().next().value
        if (first !== undefined) genAbortMap.delete(first)
    }
}
export function abortGen(gen: string): void {
    const fn = gen ? genAbortMap.get(gen) : undefined
    if (fn) {
        genAbortMap.delete(gen)
        try { fn() } catch { /* best-effort */ }
    }
}

// Runtime toggle (default on). Lets the user fall back to the original /proxy2 path
// without a rebuild if anything regresses.
export function isBgStreamEnabled(): boolean {
    try {
        return localStorage.getItem('bg-preserve-stream') !== 'off'
    } catch {
        return true
    }
}

function toBase64(body: Uint8Array): string {
    return Buffer.from(body).toString('base64')
}

export async function fetchViaBgStreamJob(url: string, arg: {
    method: string
    headers: Record<string, string>
    body?: Uint8Array
    signal?: AbortSignal
    requestTimeoutMs?: number
    chatId?: string
    bgSubKey?: string
}): Promise<Response> {
    const auth = await forageStorage.createAuth()
    const bodyBase64 = arg.body ? toBase64(arg.body) : ''

    // fetchNative passes the message generationId as `chatId` (native path). Plugin
    // providers (cache keeper) call fetchNative without it, so fall back to the active chat.
    const generationId = arg.chatId
    const ctx = generationId ? getBgGenContext(generationId) : undefined
    const meta: { charId?: string; chatId?: string; charName?: string; generationId?: string; inputTokens?: number; outputTokens?: number; maxContext?: number; isSub?: boolean; subKey?: string } = {
        charId: ctx?.charId,
        chatId: ctx?.chatId,
        charName: ctx?.charName,
        generationId,
        inputTokens: ctx?.inputTokens,
        outputTokens: ctx?.outputTokens,
        maxContext: ctx?.maxContext,
        // BG-PRESERVE 2a: sub-model/helper call (FOLD/hypa). Consumed inline by the
        // generation flow, never shown as a chat message — server skips chat-draft persist.
        isSub: !!arg.bgSubKey,
        subKey: arg.bgSubKey,
    }
    if (!meta.charId || !meta.chatId) {
        try {
            const idx = get(selectedCharID)
            const char: any = (DBState as any)?.db?.characters?.[idx]
            if (char?.chaId) {
                const chat: any = char?.chats?.[char?.chatPage]
                meta.charId = meta.charId || char.chaId
                meta.chatId = meta.chatId || chat?.id
                meta.charName = meta.charName || char.name
                if (!meta.generationId) {
                    const msgs: any[] = chat?.message
                    const last = Array.isArray(msgs) && msgs.length ? msgs[msgs.length - 1] : null
                    if (last && last.role === 'char' && typeof last.chatId === 'string') {
                        meta.generationId = last.chatId
                    }
                }
            }
        } catch { /* best-effort */ }
    }

    const jobRes = await fetch('/api/bg-stream-job', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'same-origin', // cookie session auth (sessionAuthMiddleware)
        body: JSON.stringify({
            url,
            method: arg.method,
            headers: arg.headers,
            bodyBase64,
            meta,
            requestTimeoutMs: arg.requestTimeoutMs,
            heartbeatSec: BG_HEARTBEAT_SEC,
        }),
        signal: arg.signal,
    })

    if (!jobRes.ok) {
        throw new Error(`Failed to create bg stream job: ${jobRes.status} ${await jobRes.text()}`)
    }

    const { jobId } = await jobRes.json() as { jobId: string }
    const wsProtocol = location.protocol === 'https:' ? 'wss:' : 'ws:'
    const wsUrl = `${wsProtocol}//${location.host}/proxy-stream-jobs/${encodeURIComponent(jobId)}/ws?risu-auth=${encodeURIComponent(auth)}`

    const isSub = !!arg.bgSubKey
    // 2a step-4: the MAIN generation (cache-keeper provider: isProvider, no bgSubKey) also needs
    // background recovery. It carries the chat's generationId as chatId. Treat it like a sub for
    // reconnect/kv recovery so a backgrounded WS close doesn't fall back to a duplicate proxy re-request.
    const isMainPreserve = !isSub && !!arg.chatId
    const inflightPromise = new Promise<Response>((resolve, reject) => {
        let resolved = false
        let done = false
        let responseStatus = 200
        let responseHeaders: Record<string, string> = {}
        let streamController: ReadableStreamDefaultController<Uint8Array> | null = null
        let ws: WebSocket | null = null
        let reconnectArmed = false
        let reconnectTried = false
        let onVisHandler: (() => void) | null = null
        let resultAcknowledged = false
        let streamEnded = false
        let aborted = false
        let rawPrefixBytes = 0
        let kvRecoveryStarted = false
        let kvRecoveryFinished = false
        const queuedChunks: Uint8Array[] = []
        const detachAbortHandler = () => arg.signal?.removeEventListener('abort', abortHandler)

        const acknowledgeConsumedResult = () => {
            detachAbortHandler()
            if (resultAcknowledged || (!isSub && !isMainPreserve)) return
            resultAcknowledged = true
            fetch(`/api/bg-sub-result/${encodeURIComponent(jobId)}/ack`, {
                method: 'POST',
                credentials: 'same-origin',
            }).catch(() => {
                // Best effort only: a missed ACK leaves the recovery record to its bounded TTL.
            })
        }

        // ACK only when a Response consumer asks past the last queued byte. Receiving the WS
        // `done` event alone is too early: a suspended page may not have drained the body yet.
        const flushStream = () => {
            if (!streamController) return
            while (queuedChunks.length > 0 && (streamController.desiredSize ?? 1) > 0) {
                streamController.enqueue(queuedChunks.shift()!)
            }
            if (streamEnded && queuedChunks.length === 0 && (streamController.desiredSize ?? 1) > 0) {
                try { streamController.close() } catch { /* already closed */ }
                acknowledgeConsumedResult()
            }
        }

        // Explicit user cancel/abort → tear down the server job too (recovery not wanted).
        const deleteJob = () => {
            fetch(`/proxy-stream-jobs/${encodeURIComponent(jobId)}`, {
                method: 'DELETE',
                headers: { 'risu-auth': auth },
            }).catch(() => {})
        }

        // Fully stop: detach the reconnect listener + handlers + close socket so neither a
        // pending visibilitychange nor onclose can re-arm reconnect after abort/cancel.
        const teardown = () => {
            if (onVisHandler) {
                document.removeEventListener('visibilitychange', onVisHandler)
                onVisHandler = null
            }
            reconnectArmed = false
            if (ws) {
                try { ws.onclose = null; ws.onerror = null; ws.onmessage = null; ws.close() } catch { /* ignore */ }
                ws = null
            }
        }

        const stream = new ReadableStream<Uint8Array>({
            start(controller) {
                streamController = controller
            },
            pull() {
                flushStream()
            },
            cancel() {
                detachAbortHandler()
                teardown()
                deleteJob()
            },
        })

        const abortHandler = () => {
            aborted = true
            detachAbortHandler()
            teardown()
            deleteJob()
            if (!resolved) {
                resolved = true
                reject(new DOMException('Aborted', 'AbortError'))
            } else {
                try { streamController?.error(new DOMException('Aborted', 'AbortError')) } catch { /* closed */ }
            }
        }

        if (arg.signal) {
            if (arg.signal.aborted) {
                abortHandler()
                return
            }
            arg.signal.addEventListener('abort', abortHandler, { once: true })
        }

        const fetchRecoveryControl = async (url: string): Promise<Response> => {
            const controller = new AbortController()
            const timeout = setTimeout(() => controller.abort(), 15_000)
            const forwardAbort = () => controller.abort()
            if (arg.signal) arg.signal.addEventListener('abort', forwardAbort, { once: true })
            try {
                return await fetch(url, {
                    credentials: 'same-origin',
                    signal: controller.signal,
                })
            } finally {
                clearTimeout(timeout)
                if (arg.signal) arg.signal.removeEventListener('abort', forwardAbort)
            }
        }

        // BG-PRESERVE 2a: a sub-model/helper call (FOLD/hypa), and the long main model request,
        // keep their await alive across a
        // backgrounded WS close. The server job survives (no DELETE on bg close) and buffers
        // events; on return we reconnect to the SAME job and the server replays its
        // pendingEvents so the stream continues.
        const armReconnect = () => {
            if (reconnectArmed) return
            reconnectArmed = true
            onVisHandler = () => {
                if (document.visibilityState === 'visible') {
                    if (onVisHandler) document.removeEventListener('visibilitychange', onVisHandler)
                    onVisHandler = null
                    reconnectArmed = false
                    reconnectTried = true
                    connect()
                }
            }
            document.addEventListener('visibilitychange', onVisHandler)
        }

        // 2a step-3: a sub reconnect landed on a GC'd job (long background, >30s past completion).
        // Fetch the sub's cached raw response (persisted server-side on completion) and resolve the
        // await with a rebuilt Response so the generation continues with NO re-call (no API cost).
        // kv miss → reject (the model gets re-called, original behavior).
        // [A] 폴링 복구: recoverKv가 응답 도착 *전*에 호출되면(reconnect 후 또 백그라운드) 1회 MISS로
        // reject하던 게 레이스였음. job 완료(성공 raw / 빈 종결마커=실패)가 kv에 나올 때까지 폴링한다.
        // - found + rawBase64 비어있지 않음 → resolve(Response) (정상/에러응답 둘 다, 원래 거동)
        // - found + rawBase64 빈('') → 서버 종결마커=생성 실패 → reject
        // - found 아님(아직 결과 없음) → POLL_INTERVAL 후 재시도
        // - deadline(job timeout) 초과 → reject (job이 영영 안 끝나는 극단 안전장치)
        // 폴링 fetch는 복귀(visible) 시에만 도므로(setTimeout은 백그라운드 suspend) bg fetch abort와 무관.
        const recoverSubFromKv = () => {
            if (kvRecoveryStarted || kvRecoveryFinished || aborted) return
            kvRecoveryStarted = true
            const deadline = Date.now() + (arg.requestTimeoutMs || 600000)
            let polls = 0
            const poll = async () => {
                if (kvRecoveryFinished || aborted) return
                polls++
                try {
                    const r = await fetchRecoveryControl(`/api/bg-sub-result/${encodeURIComponent(jobId)}`)
                    if (r.ok) {
                        const j = await r.json() as {
                            found?: boolean; rawBase64?: string; status?: number; contentType?: string; final?: boolean
                        }
                        const recoveryDecision = classifyRawStreamRecoveryRecord(j)
                        if (recoveryDecision !== 'pending') {
                            kvRecoveryFinished = true
                            if (recoveryDecision === 'ready') {
                                const bytes = Buffer.from(j.rawBase64!, 'base64')
                                const headers: Record<string, string> = {}
                                if (j.contentType) headers['content-type'] = j.contentType
                                if (!resolved) {
                                    resolved = true
                                    resolve(recoveredResponseWithAck(
                                        bytes,
                                        { status: j.status || 200, headers },
                                        acknowledgeConsumedResult,
                                    ))
                                } else if (rawPrefixBytes <= bytes.length) {
                                    const suffix = bytes.subarray(rawPrefixBytes)
                                    if (suffix.length > 0) queuedChunks.push(suffix)
                                    rawPrefixBytes = bytes.length
                                    streamEnded = true
                                    flushStream()
                                } else {
                                    try { streamController?.error(new Error('bg recovery raw prefix mismatch')) } catch { /* closed */ }
                                }
                            } else {
                                // Empty/partial/overflow terminal record = no faithful response can
                                // be reconstructed. Propagate failure instead of accepting a prefix.
                                const error = new Error(j.final === false
                                    ? 'bg job ended with partial result'
                                    : 'bg job ended without result')
                                if (!resolved) {
                                    resolved = true
                                    acknowledgeConsumedResult()
                                    reject(error)
                                } else {
                                    try { streamController?.error(error) } catch { /* closed */ }
                                    acknowledgeConsumedResult()
                                }
                            }
                            return
                        }
                    }
                } catch { /* 네트워크 일시 실패: 폴링 계속 */ }
                if (kvRecoveryFinished || aborted) return
                if (Date.now() >= deadline) {
                    kvRecoveryFinished = true
                    const error = new Error(`WebSocket closed before response (poll timeout, ${polls} polls)`)
                    if (!resolved) {
                        resolved = true
                        detachAbortHandler()
                        reject(error)
                    } else {
                        try { streamController?.error(error) } catch { /* closed */ }
                        detachAbortHandler()
                    }
                    return
                }
                // [A] 적응적 백오프: 초반 1s(빨리 도착하는 대부분은 지연↓) → 점증 최대 4s
                // (응답이 오래 걸리는 소수에서 GET 부하↓). 고정 간격보다 지연·부하 양쪽 개선.
                setTimeout(() => { void poll() }, Math.min(4000, 1000 + (polls - 1) * 500))
            }
            void poll()
        }

        const connect = () => {
            ws = new WebSocket(wsUrl)

            ws.onmessage = (ev) => {
                const event = parseProxyJobWsEvent(typeof ev.data === 'string' ? ev.data : '')
                if (!event) return
                switch (event.type) {
                    case 'job_accepted':
                    case 'ping':
                        break
                    case 'upstream_headers':
                        responseStatus = event.status
                        responseHeaders = event.headers
                        if (!resolved) {
                            resolved = true
                            resolve(new Response(stream, { status: responseStatus, headers: responseHeaders }))
                        }
                        break
                    case 'chunk': {
                        const bytes = decodeProxyJobWsChunk(event.dataBase64)
                        const chunkOffset = typeof (event as { offset?: unknown }).offset === 'number'
                            ? (event as { offset: number }).offset : undefined
                        const reconciled = reconcileStreamChunk(rawPrefixBytes, chunkOffset, bytes)
                        if (reconciled.gap && (isSub || isMainPreserve)) {
                            // The server still captures the complete raw response. Stop accepting a
                            // non-contiguous WS suffix and rebuild the remainder from exact KV bytes.
                            teardown()
                            recoverSubFromKv()
                            break
                        }
                        rawPrefixBytes = reconciled.nextOffset
                        if (reconciled.append.length > 0) queuedChunks.push(reconciled.append)
                        flushStream()
                        break
                    }
                    case 'error': {
                        const msg = formatProxyStreamErrorMessage(event.status, event.message)
                        done = true
                        if (!resolved) {
                            resolved = true
                            resolve(recoveredResponseWithAck(
                                new TextEncoder().encode(msg),
                                {
                                    status: event.status ?? 502,
                                    headers: { 'content-type': 'text/plain' },
                                },
                                acknowledgeConsumedResult,
                            ))
                        } else if (isSub || isMainPreserve) {
                            // An error can follow headers/partial chunks. The KV record contains the
                            // authoritative contiguous raw prefix and is published on the next tick.
                            teardown()
                            recoverSubFromKv()
                        } else {
                            streamEnded = true
                            flushStream()
                        }
                        break
                    }
                    case 'done':
                        done = true
                        if ((isSub || isMainPreserve) && streamCompletionNeedsRecovery(
                            rawPrefixBytes, event.totalBytes, resolved,
                        )) {
                            // pendingEvents is bounded. If it evicted upstream_headers or an early
                            // chunk, a bare done must not close a truncated/unresolved Response.
                            teardown()
                            recoverSubFromKv()
                            break
                        }
                        streamEnded = true
                        flushStream()
                        break
                }
            }

            ws.onerror = () => {
                // Let onclose decide (reconnect for backgrounded sub call, else reject).
            }

            ws.onclose = () => {
                if (done) {
                    flushStream()
                    return
                }
                // 2a (iOS fix): a sub call's WS closed because the tab backgrounded. iOS may fire this
                // onclose WHILE hidden, or delay it until RETURN (hidden:false). Either way, recover:
                // arm for a still-hidden tab (wait for visibility → connect), or reconnect immediately
                // if already visible (iOS delivered the onclose on return). reconnectTried gates a single
                // attempt so a reconnect that lands on a GC'd job falls through to kv recovery below.
                if ((isSub || isMainPreserve) && !reconnectTried) {
                    if (document.visibilityState === 'hidden') {
                        armReconnect()
                    } else {
                        reconnectTried = true
                        connect()
                    }
                    return
                }
                // Foreground close, or a preserve reconnect to a gone job.
                if (!resolved) {
                    // 2a step-3: a sub whose reconnect landed on a GC'd job (long background) →
                    // recover the cached raw response from kv and continue WITHOUT re-calling.
                    // Gated on reconnectTried so foreground / first-connect failures keep the
                    // original reject behavior (no kv detour when no background happened).
                    if ((isSub || isMainPreserve) && reconnectTried) {
                        void recoverSubFromKv()
                    } else {
                        resolved = true
                        detachAbortHandler()
                        reject(new Error('WebSocket closed before response'))
                    }
                } else {
                    if ((isSub || isMainPreserve) && reconnectTried) {
                        // Response headers may already have resolved the fetch Promise. Keep that
                        // same body stream open and append the missing suffix from KV.
                        recoverSubFromKv()
                    } else {
                        streamEnded = true
                        flushStream()
                    }
                }
            }
        }

        connect()
    })
    // T2-a: 메인 복구 진행(Promise pending) 동안 gen을 마킹 → scanForLostDrafts 자동복구 보류.
    // settle(resolve/reject) 시 .finally 1곳에서 해제. (원본 Promise를 그대로 반환 — finally는 side-effect만)
    if (isMainPreserve && arg.chatId) {
        const gen = arg.chatId
        bgRecoveringMainGens.add(gen)
        // 원본 inflightPromise는 호출측(google.ts)이 처리. 이 finally 체인의 rejection은 여기서 삼켜
        // unhandled rejection 방지 (delete는 settle 시 어쨌든 실행됨).
        void inflightPromise.finally(() => { bgRecoveringMainGens.delete(gen) }).catch(() => {})
    }
    return inflightPromise
}

// Rebuild an in-memory recovery response without acknowledging it at GET time. The first pull
// queues the bytes; only the consumer's next pull (past the final byte) closes and ACKs.
export function recoveredResponseWithAck(
    bytes: Uint8Array,
    init: ResponseInit,
    acknowledge: () => void,
): Response {
    let sent = false
    const body = new ReadableStream<Uint8Array>({
        pull(controller) {
            if (!sent) {
                sent = true
                if (bytes.length > 0) controller.enqueue(bytes)
                return
            }
            controller.close()
            acknowledge()
        },
    })
    return new Response(body, init)
}

export interface ReconciledStreamChunk {
    append: Uint8Array
    nextOffset: number
    gap: boolean
}

// Reconcile a replayable chunk against the contiguous raw prefix already retained by the client.
// A reconnect may replay an overlapping chunk; only its unseen suffix is appended. A forward gap
// is never guessed across — the caller switches to the server's full raw KV copy instead.
export function reconcileStreamChunk(
    prefixOffset: number,
    chunkOffset: number | undefined,
    bytes: Uint8Array,
): ReconciledStreamChunk {
    if (!Number.isSafeInteger(chunkOffset) || (chunkOffset as number) < 0) {
        return { append: bytes, nextOffset: prefixOffset + bytes.length, gap: false }
    }
    const offset = chunkOffset as number
    if (offset > prefixOffset) {
        return { append: new Uint8Array(), nextOffset: prefixOffset, gap: true }
    }
    const overlap = prefixOffset - offset
    if (overlap >= bytes.length) {
        return { append: new Uint8Array(), nextOffset: prefixOffset, gap: false }
    }
    const append = overlap === 0 ? bytes : bytes.subarray(overlap)
    return { append, nextOffset: prefixOffset + append.length, gap: false }
}

export function streamCompletionNeedsRecovery(
    receivedBytes: number,
    totalBytes: unknown,
    responseResolved: boolean,
): boolean {
    // A replay whose upstream_headers event was evicted cannot construct a faithful Response even
    // if every chunk happened to remain. KV carries the authoritative status/content-type too.
    if (!responseResolved) return true
    // Rolling old servers do not include totalBytes. Preserve their existing behavior once headers
    // have resolved; new servers make truncation detectable with an exact final byte count.
    if (typeof totalBytes !== 'number' || !Number.isSafeInteger(totalBytes) || totalBytes < 0) return false
    return receivedBytes !== totalBytes
}

export type RawStreamRecoveryDecision = 'pending' | 'ready' | 'terminal-error'

export function classifyRawStreamRecoveryRecord(record: {
    found?: unknown
    rawBase64?: unknown
    final?: unknown
} | null | undefined): RawStreamRecoveryDecision {
    if (!record?.found || typeof record.rawBase64 !== 'string') return 'pending'
    // Only an upstream body that reached normal EOF is replayable. `final:false` carries either a
    // bounded partial prefix, an overflow marker, or an upstream/abort failure and must never be
    // promoted to a successful Response merely because some bytes were captured.
    if (record.final !== true || record.rawBase64.length === 0) return 'terminal-error'
    return 'ready'
}

import { describe, expect, test } from 'vitest'
import {
    classifyRawStreamRecoveryRecord,
    reconcileStreamChunk,
    streamCompletionNeedsRecovery,
} from './bgStreamRecovery'

describe('reconcileStreamChunk', () => {
    const bytes = (...values: number[]) => new Uint8Array(values)

    test('appends the next exact chunk', () => {
        expect(reconcileStreamChunk(2, 2, bytes(3, 4))).toEqual({
            append: bytes(3, 4), nextOffset: 4, gap: false,
        })
    })

    test('keeps only the unseen suffix of an overlapping replay', () => {
        expect(reconcileStreamChunk(3, 1, bytes(2, 3, 4, 5))).toEqual({
            append: bytes(4, 5), nextOffset: 5, gap: false,
        })
    })

    test('drops a fully duplicated replay', () => {
        expect(reconcileStreamChunk(5, 1, bytes(2, 3))).toEqual({
            append: bytes(), nextOffset: 5, gap: false,
        })
    })

    test('surfaces a forward gap without appending corrupt bytes', () => {
        expect(reconcileStreamChunk(2, 4, bytes(5, 6))).toEqual({
            append: bytes(), nextOffset: 2, gap: true,
        })
    })

    test('keeps rolling compatibility when an old server omits offsets', () => {
        expect(reconcileStreamChunk(2, undefined, bytes(3))).toEqual({
            append: bytes(3), nextOffset: 3, gap: false,
        })
    })
})

describe('streamCompletionNeedsRecovery', () => {
    test('accepts an exact new-server byte count after headers resolved', () => {
        expect(streamCompletionNeedsRecovery(12, 12, true)).toBe(false)
    })

    test('recovers when a replay omitted bytes before done', () => {
        expect(streamCompletionNeedsRecovery(8, 12, true)).toBe(true)
    })

    test('recovers when replay headers were evicted even if all bytes remain', () => {
        expect(streamCompletionNeedsRecovery(12, 12, false)).toBe(true)
    })

