        expect(classifyRawStreamRecoveryRecord({ found: true, rawBase64: '', final: false })).toBe('terminal-error')
        expect(classifyRawStreamRecoveryRecord({ found: true, rawBase64: '', final: true })).toBe('terminal-error')
    })

