    })
})

// BG-PRESERVE — client side of server-driven chat orchestration (S4 + auto-fallback).
//
// Goal (§18.3): the existing bg-stream-job preserves each LLM *fetch* in the background, but the
// *client JS that assembles the main prompt from the aux result* stalls when the phone is
// backgrounded → the MAIN request only fires after the user returns, so they wait the (flex-tier
// ~150s) main again from the return point. This runs the WHOLE pipeline (assembly + aux + main +
// post) on the SERVER so the phone can be backgrounded and the answer is already done on return.
//
// Always on (no flag): the patch's mere presence enables it — install.cjs apply = on, revert = off.
// (The old localStorage/URL flags were dropped: iOS Safari evicts script-writable storage after
// ~7 days with no access, which would silently turn a localStorage flag off — the very devices
// this preserves generations for. A code default is eviction-immune.)
//
// Auto-fallback (replaces the old manual off switch): if the server fails to produce a MAIN reply
// (chat:null / a throw / no new assistant message / the delegate POST itself failing), the client
// transparently regenerates with its own normal path, so the user always gets a reply. If the main
// reply WAS produced (even when post-processing threw), the partial result is merged and the client
// does NOT regenerate — no double main LLM call = no double cost.

import { get } from 'svelte/store'
import { v4 } from 'uuid'
import { DBState, selectedCharID, ReloadChatPointer } from './stores.svelte'
import { requestDurableSave } from './globalApi.svelte'
import { ensureChatHydrated, fetchChatFromServer } from './storage/chatStorage'
import { alertError } from './alert'
import { playNotificationSound } from './notificationSound'
// sendChat + chatProcessStage live in the same module (index ↔ this circular import is fine — both
// are only referenced at call time). chatProcessStage drives the top-bar; sendChat is the client's
// own normal generation path, invoked by the auto-fallback below.
import { chatProcessStage, doingChat, sendChat } from './process/index.svelte'
import {
    handoffServerGenerationToClient,
    orchestrating,
    setServerGenerationBusy,
} from './generationBusy'
// 요청 상태 표시 toast: in delegated mode the client's own request.ts never runs, so its status
// store stays empty. The server relays its status snapshot each poll; feed it in so the toast shows.
import { ingestRelayedStatuses, clearRelayedStatuses } from './status/requestStatus'
import { isPartialOrchestrationResult, isTerminalOrchestrationResult } from './bgOrchestrationResult'
import { runClientFallbackLifecycle } from './bgOrchestrationFallback'
import {
    classifyOrchestrationStatusResponse,
    persistBeforeOrchestrationStart,
    persistCanonicalOrchestrationBase,
    reconcileOrchestrationStart,
} from './bgOrchestrationStart'
import {
    findChatDelivery,
    isConfirmedOrchestrationAcknowledgement,
    markChatDelivery,
    persistBeforeResultAck,
    readFullyCommittedDelivery,
    readRootDelivery,
    recordRootDelivery,
    type OrchestrationAckState,
} from './bgOrchestrationDelivery'
import {
    classifyOrchestrationResultOrder,
    commitOrchestrationResultOrder,
    createOrchestrationPollGate,
    type AppliedOrchestrationRevision,
} from './bgOrchestrationOrdering'
import {
    recordAppliedMessagesDelta,
    seedAppliedMessagesDelta,
    seedAppliedMessagesDeltaFromStatics,
    takeUnappliedMessagesDelta,
} from './bgOrchestrationStats'
import {
    clearPendingMarker as clearStoredPendingMarker,
    readPendingMarkers,
    type OrchestrationPendingMarker,
    updatePendingMarker,
    writePendingMarker as writeStoredPendingMarker,
} from './bgOrchestrationPending'
import {
    applyOrchestrationChatResult,
    orchestrationChatRevision,
    orchestrationRecoveryTargetIsFull,
    resolveOrchestrationRecoveryTarget,
    type OrchestrationMergeTarget,
} from './bgOrchestrationMerge'
import {
    applyOrchestrationGlobalDelta,
    recordOrchestrationGlobalConflicts,
} from './bgOrchestrationGlobals'

// Exact server-generation ownership remains separately readable for the cancel path. The public
// doingChat store is the union of this lease and the client lease, so every existing busy consumer
// observes detached orchestration without importing this module-specific state.
export { orchestrating }

// Always-on gate (no localStorage / URL toggle — see header). on/off = the patch's existence.
// EXCEPT inside the server orchestration bundle: that bundle imports this module (via index → here)
// and runs sendChat itself — if the redirect fired there it would loop (server sendChat → POST
// /api/bg-orchestrate → server sendChat → …). The bundle sets globalThis.__bgOrch at load
// (bgOrchBundle.build.cjs entry), which the client never does, so it's a reliable server-runtime
// marker. (The old localStorage-flag read happened to return false here because the bundle's
// localStorage stub yields null; the always-on flag needs this explicit guard instead.)
export function isServerOrchestrationEnabled(): boolean {
    try { if ((globalThis as { __bgOrch?: unknown }).__bgOrch) return false } catch { /* ignore */ }
    return true
}

export interface OrchestrateOutcome {
    handled: boolean
    result?: boolean
}

// ── round-trip watch + merge + auto-fallback ─────────────────────────────────
const ORCH_POLL_MS = 2500
const ORCH_DEADLINE_MS = 900000 // 15 min — covers the worst flex-tier gen (main 2-5min + post);
                                // past this assume the gen was lost (server restart) and stop.
const ORCH_CONTROL_FETCH_TIMEOUT_MS = 15_000
let watchTimer: ReturnType<typeof setInterval> | null = null
let watchDeadlineTimer: ReturnType<typeof setTimeout> | null = null
let watchDeadline = 0
let watchKey: { charId: string, chatId: string } | null = null
let activeOperationCoordinates: { charId: string, chatId: string } | null = null
// Client-generated identity for the active whole-pipeline run. The server maps this exact id to
// its AbortController; unlike char/chat coordinates it cannot cancel a different tab's run.
let activeOperationId: string | null = null
// Highest cumulative statics.messages delta already merged for each operation. Intermediate and
// terminal records both carry cumulative values, so only their positive suffix is applied.
const appliedStaticsDeltaByOperation = new Map<string, number>()
// Overlapping interval/visibility polls may peek the same non-destructive revision. Deduplicate
// only that exact resultId; a terminal revision that replaces a slow intermediate remains free to
// progress. A hung delivery therefore holds at most one entry instead of spawning a save per tick.
const resultDeliveriesInFlight = new Set<string>()
// M7: interval and visibility polls share one foreground flight per watch epoch. An old hung fetch
// does not block a later operation: stop/cancel advances watchEpoch, while the old response still
// fails the epoch guard before merge. Ordered revisions commit only after strict save succeeds.
const foregroundPollGate = createOrchestrationPollGate()
const appliedResultOrderByOperation = new Map<string, AppliedOrchestrationRevision>()
const mergeTargetByOperation = new Map<string, OrchestrationMergeTarget>()
const completionNotifiedOperations = new Set<string>()
// A durable save can outlive the watch deadline. Keep its result-claim heartbeat centrally
// cancellable so stop/cancel/timeout never leaves a background interval refreshing that claim
// forever while the save promise is stuck.
const resultClaimHeartbeatStops = new Set<() => void>()
// Invalidates poll responses already in flight when cancel/final/fallback closes this watch.
// Without this, a response that began before cancel ACK could still merge afterwards.
let watchEpoch = 0
// Messages in the chat at delegation time. The server result is a MAIN reply iff its chat grew past
// this (statics/trigger vars can change with no reply, so message-count is the reliable signal).
let watchBaselineMsgs = 0
// The original sendChat arg, captured at delegation, replayed by the fallback (minus the now-stale
// AbortSignal) so a fallback continue-generation etc. behaves like the original call.
let watchArg: Record<string, unknown> = {}
// One-shot guard so the watch fires the fallback (or stops) exactly once per delegation.
let fallbackFired = false
// Gate for consuming the server result. watchKey is armed BEFORE the POST ACK (so a failed
// delegate-POST can still fall back), but the result must only be GET-consumed AFTER the ACK —
// the server clears any stale result for this chat at the start of the detached handler, so a poll
// firing in the pre-ACK window (e.g. a visibilitychange) could otherwise consume a stale result
// from a prior unconsumed gen. Set true only in startWatchTimer (post-ACK).
let pollingActive = false
let watchResultKeyVersion: 0 | 1 = 0
const orchestrationConsumerId = v4()

async function fetchOrchestrationControl(
    url: string,
    init: RequestInit = {},
): Promise<Response> {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), ORCH_CONTROL_FETCH_TIMEOUT_MS)
    try {
        return await fetch(url, { ...init, signal: controller.signal })
    } finally {
        clearTimeout(timer)
    }
}

// ── cold-boot recovery marker ────────────────────────────────────────────────
// The in-memory watch above survives a background *suspend* (same JS context, visibilitychange
// re-polls). But an iOS *kill* (jetsam — happens when two home-screen PWAs compete for memory)
// cold-reloads the page: watchKey is gone and nothing re-arms it, so a completed generation sits
// unconsumed in the server kv (30-min TTL). We persist a small marker at delegation and, on the
// next boot, poll that chat's result and merge it. localStorage survives a cold reload
// (sessionStorage does not); this marker lives only minutes, so the 7-day-eviction reason the
// on/off flags avoid localStorage (see header) does not apply.
function writePendingMarker(
    charId: string,
    chatId: string,
    baselineMsgs: number,
    operationId: string,
    expectedChatRevision: string,
): void {
    try {
        writeStoredPendingMarker(localStorage, {
            charId, chatId, baselineMsgs, operationId,
            deliveryVersion: 3, resultKeyVersion: 0, staticsMessagesApplied: 0,
            deliveryChatId: chatId, expectedChatRevision, completionNotified: false, ts: Date.now(),
        })
    }
    catch { /* no storage (private mode) — recovery just won't run */ }
}
function rememberAppliedStaticsDelta(operationId: string, cumulative: number): void {
    try {
        updatePendingMarker(localStorage, operationId, (marker) => ({
            ...marker, staticsMessagesApplied: cumulative,
        }))
    } catch { /* best-effort; in-memory idempotency still protects this page */ }
}
function rememberResultKeyVersion(operationId: string, resultKeyVersion: 0 | 1): void {
    watchResultKeyVersion = resultKeyVersion
    try {
        updatePendingMarker(localStorage, operationId, (marker) => ({ ...marker, resultKeyVersion }))
    } catch { /* best-effort; active watch retains the negotiated value in memory */ }
}
function clearPendingMarker(operationId: string | null): void {
    try { clearStoredPendingMarker(localStorage, operationId) } catch { /* best-effort */ }
}

function playMessageCompletionSound(): void {
    try {
        if ((DBState as any)?.db?.playMessage) {
            void playNotificationSound(
                (DBState as any).db.messageSound,
                (DBState as any).db.messageSoundVolume,
            )
        }
    } catch { /* best-effort browser epilogue */ }
}

function runServerCompletionEpilogue(operationId: string | null, data: any): void {
    if (!operationId || completionNotifiedOperations.has(operationId)) return
    completionNotifiedOperations.add(operationId)
    try {
        updatePendingMarker(localStorage, operationId, (marker) => ({
            ...marker, completionNotified: true,
        }))
    } catch { /* in-memory guard still prevents duplicates on this page */ }
    playMessageCompletionSound()
    try {
        if (!(DBState as any)?.db?.notification || typeof Notification === 'undefined') return
        const messages = Array.isArray(data?.chat?.message) ? data.chat.message : []
        const body = [...messages].reverse().find((message: any) => message?.role === 'char')?.data
        void Notification.requestPermission().then((permission) => {
            if (permission !== 'granted') return
            const notification = new Notification('Risuai', { body: typeof body === 'string' ? body : '' })
            notification.onclick = () => { try { window.focus() } catch { /* ignore */ } }
        }).catch(() => {})
    } catch { /* browser may not expose Notification */ }
}

function stopWatch(options: { handoffToClient?: boolean, preservePendingMarker?: boolean } = {}): void {
    const operationId = activeOperationId
    watchEpoch++
    if (watchTimer) { clearInterval(watchTimer); watchTimer = null }
    if (watchDeadlineTimer) { clearTimeout(watchDeadlineTimer); watchDeadlineTimer = null }
    watchKey = null
    activeOperationCoordinates = null
    activeOperationId = null
    pollingActive = false
    watchResultKeyVersion = 0
    if (options.handoffToClient) handoffServerGenerationToClient()
    else setServerGenerationBusy(false)
    chatProcessStage.set(0)
    // A UI deadline is not proof that the paid operation/result vanished. Retain its bounded
    // marker so a later cold boot can finish an unconfirmed exact ACK without regenerating.
    if (!options.preservePendingMarker) clearPendingMarker(operationId)
    // This module has one active watch/marker. Clear the whole ledger so an existing M10
    // cross-tab result mismatch cannot strand a different operation's entry in memory.
    appliedStaticsDeltaByOperation.clear()
    resultDeliveriesInFlight.clear()
    appliedResultOrderByOperation.clear()
    stopAllResultClaimHeartbeats()
    if (operationId) mergeTargetByOperation.delete(operationId)
    if (operationId) completionNotifiedOperations.delete(operationId)
    try { clearRelayedStatuses() } catch { /* best-effort */ }
}

// Arm the watch state at delegation time (BEFORE the POST resolves) so even a delegate-POST failure
// can fall back with a valid key. The polling timer is started separately, only after the ACK.
function armWatch(
    charId: string,
    chatId: string,
    baselineMsgs: number,
    arg: Record<string, unknown>,
    operationId: string,
    expectedChatRevision: string,
    acceptedChatRevisions: string[] = [],
): void {
    appliedStaticsDeltaByOperation.clear()
    appliedResultOrderByOperation.clear()
    watchEpoch++
    watchKey = { charId, chatId }
    activeOperationCoordinates = { charId, chatId }
    activeOperationId = operationId
    mergeTargetByOperation.set(operationId, {
        deliveryChatId: chatId, expectedChatRevision, acceptedChatRevisions, conflict: false,
    })
    watchBaselineMsgs = baselineMsgs
    watchArg = arg
    fallbackFired = false
    pollingActive = false
    watchResultKeyVersion = 0
    watchDeadline = Date.now() + ORCH_DEADLINE_MS
    if (watchDeadlineTimer) clearTimeout(watchDeadlineTimer)
    const deadlineEpoch = watchEpoch
    // Single-flight intentionally prevents a second poll from overtaking a slow one. Its deadline
    // must therefore be independent of poll entry: a permanently pending GET/save/ACK would
    // otherwise also prevent the interval's old in-function deadline check from ever running.
    watchDeadlineTimer = setTimeout(() => {
        if (watchEpoch !== deadlineEpoch || !watchKey) return
        console.warn('[bg-orch] watch deadline timer, giving up', watchKey)
        stopWatch({ preservePendingMarker: true })
        try { alertError('백그라운드 생성이 시간 초과됐어요. 다시 보내주세요.') } catch { /* best-effort */ }
    }, ORCH_DEADLINE_MS)
}

function startWatchTimer(): void {
    if (watchTimer) clearInterval(watchTimer)
    pollingActive = true // server has ACKed (and cleared any stale result) — safe to consume now
    watchTimer = setInterval(() => { void pollOrchestrationResult() }, ORCH_POLL_MS)
}

// The server didn't produce a main reply (chat:null / threw before the main / 0 new messages / the
// delegate POST failed). Stop watching and transparently regenerate on the client — UNLESS the user
// has since navigated to a different chat (regenerating would land in the wrong chat), in which case
// just notify. Guarded to run once. Captures the key/arg before stopWatch() clears them.
function triggerClientFallback(reason: string): void {
    if (fallbackFired) return
    fallbackFired = true
    const key = watchKey
    const arg = watchArg
    console.warn('[bg-orch] server produced no main reply → client fallback:', reason)
    stopWatch({ handoffToClient: true })
    if (!key) { doingChat.set(false); return }
    try {
        const chars: unknown = (DBState as any)?.db?.characters
        const charIdx = get(selectedCharID)
        const char: any = Array.isArray(chars) ? (chars as any[])[charIdx] : null
        const chat: any = char?.chats?.[char?.chatPage]
        // Only regenerate if the user is still on the chat the delegation was for; else regenerating
        // would generate into whatever chat is now open. bgOrchFallback:true makes sendChat's
        // redirect skip re-delegating (would loop straight back to the server).
        if (char && chat && char.chaId === key.charId && chat.id === key.chatId) {
            void runClientFallbackLifecycle(
                () => sendChat(-1, { ...arg, bgOrchFallback: true }),
                () => {
                    // Direct fallback bypasses DefaultChatScreen.sendChatMain(), whose final
                    // `$doingChat = false` normally releases the composer. Always mirror that
                    // cleanup here, including rejected/throwing fallback generations.
                    doingChat.set(false)
                    chatProcessStage.set(0)
                },
                (e) => console.error('[bg-orch] fallback sendChat rejected', e),
                playMessageCompletionSound,
            )
        } else {
            doingChat.set(false)
            try { alertError('백그라운드 생성을 완료하지 못했어요. 해당 채팅에서 다시 보내주세요.') } catch { /* best-effort */ }
        }
    } catch (e) {
        doingChat.set(false)
        console.error('[bg-orch] fallback dispatch failed', e)
    }
}

function orchestrationResultUrl(
    charId: string,
    chatId: string,
    operationId: string | null,
    resultKeyVersion: 0 | 1,
): string {
    if (resultKeyVersion === 1 && operationId) {
        const query = new URLSearchParams({ charId, chatId, consumerId: orchestrationConsumerId })
        return `/api/bg-orchestrate-result/${encodeURIComponent(operationId)}?${query.toString()}`
    }
    return `/api/bg-orchestrate-result/${encodeURIComponent(charId)}/${encodeURIComponent(chatId)}?delivery=ack-v1`
}

const ORCH_RESULT_CLAIM_HEARTBEAT_MS = 20_000

// Keep the operation-keyed delivery lease alive only while the local durable save is running.
// The heartbeat response deliberately omits the full chat payload, so even a long IndexedDB save
// does not repeatedly download a potentially large result. If the page is frozen/killed the timer
// stops and the server's normal two-minute lease expiry lets another PWA recover the revision.
function startResultClaimHeartbeat(
    charId: string,
    chatId: string,
    operationId: string | null,
    resultKeyVersion: 0 | 1,
): () => void {
    if (resultKeyVersion !== 1 || !operationId) return () => {}
    let stopped = false
    let inFlight = false
    const baseUrl = orchestrationResultUrl(charId, chatId, operationId, 1)
    const timer = setInterval(() => {
        if (stopped || inFlight) return
        inFlight = true
        void fetchOrchestrationControl(`${baseUrl}&heartbeat=1`, {
            method: 'GET', credentials: 'same-origin',
        }).catch(() => {
            // A failed refresh is recoverable: the parked revision remains available and either
            // the next heartbeat or the exact ACK can still confirm this consumer.
        }).finally(() => { inFlight = false })
    }, ORCH_RESULT_CLAIM_HEARTBEAT_MS)
    const stop = () => {
        if (stopped) return
        stopped = true
        clearInterval(timer)
        resultClaimHeartbeatStops.delete(stop)
    }
    resultClaimHeartbeatStops.add(stop)
    return stop
}

function stopAllResultClaimHeartbeats(): void {
    for (const stop of [...resultClaimHeartbeatStops]) stop()
}

async function probeOperationResultKeyVersion(
    charId: string,
    chatId: string,
    operationId: string,
): Promise<0 | 1 | null> {
    try {
        const query = `charId=${encodeURIComponent(charId)}&chatId=${encodeURIComponent(chatId)}`
        const res = await fetchOrchestrationControl(`/api/bg-orchestrate-status/${encodeURIComponent(operationId)}?${query}`, {
            method: 'GET', credentials: 'same-origin',
        })
        let data: any = null
        try { data = await res.json() } catch { /* old server generic 404 */ }
        if (res.ok && data?.accepted === true && data.operationId === operationId) {
            return data.resultKeyVersion === 1 ? 1 : 0
        }
        if (res.status === 404) return 0
        return null
    } catch {
        return null
    }
}

async function acknowledgeResultRevision(
    charId: string,
    chatId: string,
    operationId: string | null,
    resultKeyVersion: 0 | 1,
    resultId: string,
): Promise<Exclude<OrchestrationAckState, 'legacy'>> {
    const url = resultKeyVersion === 1 && operationId
        ? `/api/bg-orchestrate-result/${encodeURIComponent(operationId)}/${encodeURIComponent(resultId)}?consumerId=${encodeURIComponent(orchestrationConsumerId)}`
        : `/api/bg-orchestrate-result/${encodeURIComponent(charId)}/${encodeURIComponent(chatId)}/${encodeURIComponent(resultId)}`
    const res = await fetchOrchestrationControl(url, { method: 'DELETE', credentials: 'same-origin' })
    let data: any = null
    try { data = await res.json() } catch { /* handled below */ }
    if (res.ok && data?.acked === true) return 'acked'
    if (res.status === 409 && data?.reason === 'superseded') return 'superseded'
    return 'unconfirmed'
}

async function persistMergedOrchestrationResult(charId: string, chatId: string, data: any) {
    const merge = mergeOrchestrationResult(charId, chatId, data)
    if (!merge.merged) {
        return {
            durable: false,
            acknowledgement: 'not-attempted' as const,
            conflictCreated: false,
            globalConflicts: 0,
            error: new Error('orchestration merge failed'),
        }
    }
    const operationId = typeof data.operationId === 'string' ? data.operationId : null
    const resultKeyVersion = data.resultKeyVersion === 1 ? 1 : 0
    const stopClaimHeartbeat = startResultClaimHeartbeat(charId, chatId, operationId, resultKeyVersion)
    try {
        const delivery = await persistBeforeResultAck(
            data,
            async () => {
                await requestDurableSave({ chat: [charId, merge.savedChatId], root: true })
                const cumulative = operationId ? (appliedStaticsDeltaByOperation.get(operationId) || 0) : 0
                if (operationId && cumulative > 0) rememberAppliedStaticsDelta(operationId, cumulative)
                if (operationId) {
                    const target = mergeTargetByOperation.get(operationId)
                    if (target) {
                        try {
                            updatePendingMarker(localStorage, operationId, (marker) => ({
                                ...marker,
                                deliveryChatId: target.deliveryChatId,
                                expectedChatRevision: target.expectedChatRevision,
                            }))
                        } catch { /* DB commit remains authoritative; marker update is best-effort */ }
                    }
                }
            },
            (resultId) => acknowledgeResultRevision(
                charId, chatId, operationId, resultKeyVersion, resultId,
            ),
        )
        return { ...delivery, conflictCreated: merge.conflictCreated, globalConflicts: merge.globalConflicts }
    } finally {
        stopClaimHeartbeat()
    }
}

async function acknowledgeUnmergedResult(charId: string, chatId: string, data: any): Promise<OrchestrationAckState> {
    const outcome = await persistBeforeResultAck(
        data,
        () => {},
        (resultId) => acknowledgeResultRevision(
            charId, chatId,
            typeof data.operationId === 'string' ? data.operationId : null,
            data.resultKeyVersion === 1 ? 1 : 0,
            resultId,
        ),
    )
    return outcome.acknowledgement === 'not-attempted' ? 'unconfirmed' : outcome.acknowledgement
}

async function pollOrchestrationResult(): Promise<void> {
    if (!watchKey || !pollingActive) return // only consume after the start ACK
    const pollEpoch = watchEpoch
    if (!foregroundPollGate.tryEnter(pollEpoch)) return
    try {
        if (Date.now() > watchDeadline) {
            console.warn('[bg-orch] watch deadline, giving up', watchKey)
            stopWatch({ preservePendingMarker: true })
            // Deadline = the gen was likely lost to a server restart (its context is gone too), so
            // auto-regenerating could surprise the user with a stale-context reply — notify instead.
            try { alertError('백그라운드 생성이 시간 초과됐어요. 다시 보내주세요.') } catch { /* best-effort */ }
            return
        }
        const { charId, chatId } = watchKey
        const operationId = activeOperationId
        const resultKeyVersion = watchResultKeyVersion
        const res = await fetchOrchestrationControl(orchestrationResultUrl(charId, chatId, operationId, resultKeyVersion), {
            method: 'GET', credentials: 'same-origin',
        })
        if (res.status === 409) return // another live PWA currently owns this exact result revision
        if (!res.ok) throw new Error(`result peek failed: HTTP ${res.status}`)
        const data = await res.json()
        // Cancel/final/fallback may have closed this watch while the GET was in flight. Never let
        // that stale response merge a cancelled result or overwrite a newer generation.
        if (pollEpoch !== watchEpoch || !watchKey
            || watchKey.charId !== charId || watchKey.chatId !== chatId) return
        if (!data || !data.found) {
            if (data?.operationState === 'start-retry-required') {
                // queued is written before provider work. It is the sole restart state that proves
                // no model cost began, so the still-live page can safely use its captured fallback.
                triggerClientFallback('server-restarted-before-provider-work')
                return
            }
            if (data?.operationState === 'interrupted-before-result') {
                stopWatch()
                try { alertError('서버 재시작으로 백그라운드 생성 흐름이 중단됐어요. 이미 사용된 토큰 비용이 있을 수 있으므로 다시 보내기 전에 확인해 주세요.') } catch { /* best-effort */ }
                return
            }
            if (data?.operationState === 'interrupted-after-main') {
                playMessageCompletionSound()
                stopWatch()
                try { alertError('본문 답변은 저장했지만 서버 재시작으로 후처리를 끝내지 못했어요.') } catch { /* best-effort */ }
                return
            }
            if (data?.operationState === 'delivery-failed') {
                stopWatch()
                try {
                    alertError('생성은 끝났지만 서버가 결과를 저장하지 못했어요. 다시 보내면 이전 생성 비용에 더해 새 비용이 들 수 있어요.')
                } catch { /* best-effort */ }
                return
            }
            if (data?.operationState === 'delivered' || data?.operationState === 'cancelled') {
                stopWatch()
                return
            }
            // Still generating → reflect the server's pipeline stage on the top-bar, keep polling.
            if (data && typeof data.stage === 'number') {
                const activeWithoutStage = data.operationState === 'queued' || data.operationState === 'running'
                chatProcessStage.set(activeWithoutStage && data.stage === 0 ? 1 : data.stage)
            }
            // Relay the server's request-status snapshot into the local toast store.
            if (data && Array.isArray(data.status)) { try { ingestRelayedStatuses(data.status) } catch { /* best-effort */ } }
            return
        }
        // Rolling legacy delivery is char/chat-keyed. It is non-destructive, so reject a different
        // operation without ACKing or merging it; the owning page can still consume it.
        if (operationId && data.operationId !== operationId) return
        const orderDecision = classifyOrchestrationResultOrder(data, appliedResultOrderByOperation)
        if (orderDecision === 'conflict') {
            console.error('[bg-orch] result sequence conflict; retaining server revision', {
                operationId: data.operationId, publishSeq: data.publishSeq, resultId: data.resultId,
            })
            return
        }
        if (orderDecision === 'duplicate' || orderDecision === 'stale') {
            const resultId = typeof data.resultId === 'string' ? data.resultId : null
            if (!resultId) return
            const acknowledgement = await acknowledgeResultRevision(
                charId, chatId, operationId, resultKeyVersion, resultId,
            )
            if (pollEpoch !== watchEpoch || acknowledgement === 'superseded') return
            if (!isConfirmedOrchestrationAcknowledgement(acknowledgement)) {
                if (isTerminalOrchestrationResult(data)) {
                    runServerCompletionEpilogue(operationId, data)
                    // The reply is already durable. A lost cleanup response must not hold the
                    // composer/purple stage for 15 minutes; retain the marker for a later exact ACK.
                    stopWatch({ preservePendingMarker: true })
                }
                return
            }
            if (isTerminalOrchestrationResult(data)) {
                runServerCompletionEpilogue(operationId, data)
                stopWatch()
            }
            return
        }
        // Found a result. Did the server produce a MAIN reply (chat grew past the baseline)?
        const resultId = typeof data.resultId === 'string' && data.resultId.length > 0 ? data.resultId : null
        if (resultId && resultDeliveriesInFlight.has(resultId)) return
        if (resultId) resultDeliveriesInFlight.add(resultId)
        try {
            const newMsgs = data.chat && Array.isArray(data.chat.message) ? data.chat.message.length : -1
            const hasMainReply = !!data.chat && newMsgs > watchBaselineMsgs
            if (hasMainReply) {
                const delivery = await persistMergedOrchestrationResult(charId, chatId, data)
                if (pollEpoch !== watchEpoch) return
                if (!delivery.durable) {
                    console.warn('[bg-orch] merged result save failed; retaining server revision', delivery.error)
                    return
                }
                if (isTerminalOrchestrationResult(data)) {
                    // Local durable persistence is the user-visible completion point. Server ACK is
                    // cleanup/ownership confirmation and may be retried without holding the UI busy.
                    runServerCompletionEpilogue(operationId, data)
                }
                if (delivery.conflictCreated) {
                    try { alertError('생성 중 채팅이 수정되어 서버 결과를 “BG conflict” 새 채팅으로 보존했어요.') } catch { /* best-effort */ }
                }
                if (delivery.globalConflicts > 0) {
                    try { alertError(`생성 중 수정된 전역 변수 ${delivery.globalConflicts}개는 현재 값을 유지하고 서버 변경도 복구 기록에 보존했어요.`) } catch { /* best-effort */ }
                }
                commitOrchestrationResultOrder(data, appliedResultOrderByOperation)
                // A newer revision replaced the one we saved before its ACK arrived. Its exact resultId
                // remains parked; continue polling rather than closing on the stale revision.
                if (delivery.acknowledgement === 'superseded') return
                // Saving locally is not enough to transfer sole ownership. If the exact ACK did
                // not reach the server, keep the marker/watch and retry as an ordered duplicate;
                // otherwise another PWA could claim and preserve a second conflict copy later.
                if (!isConfirmedOrchestrationAcknowledgement(delivery.acknowledgement)) {
                    if (isTerminalOrchestrationResult(data)) {
                        stopWatch({ preservePendingMarker: true })
                    }
                    return
                }
                // The explicit result kind separates the only non-terminal record (the early main
                // snapshot) from success/partial/error terminals. Legacy servers remain compatible.
                if (isTerminalOrchestrationResult(data)) {
                    if (isPartialOrchestrationResult(data)) console.warn('[bg-orch] terminal partial merged (post threw):', data.error)
                    runServerCompletionEpilogue(operationId, data)
                    stopWatch()
                }
            } else {
                // No main reply (chat:null / threw before main / 0 new messages). Don't merge — a failed
                // server run still bumped statics.messages, so merging would double-count once the
                // client regenerates. ACK this exact terminal decision, then use the normal fallback.
                const acknowledgement = await acknowledgeUnmergedResult(charId, chatId, data)
                if (pollEpoch !== watchEpoch || acknowledgement === 'superseded') return
                if (!isConfirmedOrchestrationAcknowledgement(acknowledgement)) {
                    // No reply exists to merge, but an uncertain DELETE is not active generation.
                    // Release the UI and retain the marker instead of presenting a stuck stage.
                    stopWatch({ preservePendingMarker: true })
                    try { alertError('백그라운드 생성은 답변 없이 끝났고 서버 정리 확인이 지연됐어요. 다시 열면 정리를 재확인해요.') } catch { /* best-effort */ }
                    return
                }
                triggerClientFallback(data.chat ? 'no-new-message' : (data.error || 'empty-result'))
            }
        } finally {
            if (resultId) resultDeliveriesInFlight.delete(resultId)
        }
    } catch (e) {
        console.warn('[bg-orch] poll error', e) // network/save hiccup — keep polling until deadline
    } finally {
        foregroundPollGate.leave(pollEpoch)
    }
}

function mergeOrchestrationResult(
    charId: string,
    chatId: string,
    data: any,
): { merged: boolean, savedChatId: string, conflictCreated: boolean, globalConflicts: number } {
    try {
        const chars: any[] = (DBState as any)?.db?.characters
        if (!Array.isArray(chars)) return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
        const ci = chars.findIndex((c) => c && c.chaId === charId)
        if (ci < 0) return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
        const char: any = chars[ci]
        if (!Array.isArray(char.chats)) return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
        const chi = char.chats.findIndex((c: any) => c && c.id === chatId)
        if (!data.chat || typeof data.chat !== 'object') {
            return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
        }
        const operationId = typeof data.operationId === 'string' ? data.operationId : null
        if (!operationId && chi < 0) {
            return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
        }
        let target = operationId ? mergeTargetByOperation.get(operationId) : undefined
        if (!target && operationId) {
            target = {
                deliveryChatId: chatId,
                expectedChatRevision: chi >= 0 ? orchestrationChatRevision(char.chats[chi]) : '',
                conflict: false,
            }
            mergeTargetByOperation.set(operationId, target)
        }
        const workingTarget = target || {
            deliveryChatId: chatId,
            expectedChatRevision: orchestrationChatRevision(char.chats[chi]),
            conflict: false,
        }
        const liveDeliveryTarget = char.chats.find(
            (candidate: any) => candidate?.id === workingTarget.deliveryChatId,
        )
        if (liveDeliveryTarget && !orchestrationRecoveryTargetIsFull(liveDeliveryTarget)) {
            // A DB/chat-array replacement can race after the initial boot hydration barrier. Never
            // reinterpret a replacement placeholder/malformed shell as a real user edit; leave the
            // non-destructive server result parked so a later poll/boot can retry after hydration.
            return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
        }
        // saveChatToServer runs before database.bin. If a prior strict save committed the chat but
        // failed on root persistence, its in-chat exact-result marker is authoritative: do not
        // overwrite a later user edit or create a duplicate conflict copy; finish only the root half.
        const exactChatDelivery = operationId && typeof data.resultId === 'string'
            ? findChatDelivery(char.chats, operationId, data.resultId)
            : null
        let targetIndex: number
        let conflictCreated = false
        if (exactChatDelivery) {
            targetIndex = char.chats.findIndex((candidate: any) => candidate?.id === exactChatDelivery.deliveryChatId)
            if (targetIndex < 0) {
                return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
            }
            target = {
                deliveryChatId: exactChatDelivery.deliveryChatId,
                expectedChatRevision: exactChatDelivery.expectedChatRevision,
                conflict: exactChatDelivery.conflict,
            }
        } else {
            const applied = applyOrchestrationChatResult(char.chats, data.chat, workingTarget, v4)
            target = applied.target
            targetIndex = applied.targetIndex
            conflictCreated = applied.conflictCreated
            const deliveredChat = char.chats[targetIndex]
            const expectedChatRevision = orchestrationChatRevision(deliveredChat)
            const delivery = operationId && typeof data.resultId === 'string'
                ? markChatDelivery(deliveredChat, data, expectedChatRevision, target.conflict)
                : null
            if (delivery) target.expectedChatRevision = expectedChatRevision
        }
        // Replace the chat object AND the chats array with NEW references so the currentChatSlot /
        // currentChat $derived chain recomputes. An in-place Object.assign kept the same refs and the
        // message list only refreshed after a background return forced a re-render. reloadKeys is DEAD;
        // ReloadChatPointer (below) re-runs Chats.updateChatBody on the now-fresh currentChat.
        char.chats = char.chats.slice()
        if (operationId) mergeTargetByOperation.set(operationId, target)
        const db = (DBState as any).db as Record<string, unknown>
        if (operationId && typeof data.resultId === 'string') {
            const delivery = findChatDelivery(char.chats, operationId, data.resultId)
            if (delivery) recordRootDelivery(db, delivery)
        }
        const gv = db.globalChatVariables = (db.globalChatVariables && typeof db.globalChatVariables === 'object')
            ? db.globalChatVariables : {}
        const globalMerge = applyOrchestrationGlobalDelta(
            gv as Record<string, unknown>,
            data.globalChatVariables,
            data.globalChatVariablesDeleted,
            data.globalChatVariablesExpected,
        )
        recordOrchestrationGlobalConflicts(db, operationId, globalMerge.conflicts)
        const statics = (DBState as any).db.statics
        // Do not advance the operation ledger unless there is an actual counter to mutate. A
        // malformed/partially migrated DB without `statics` must remain retryable after repair.
        const staticsIncrement = statics
            ? takeUnappliedMessagesDelta(data, appliedStaticsDeltaByOperation)
            : 0
        if (statics && staticsIncrement > 0) {
            statics.messages = (statics.messages || 0) + staticsIncrement
        }
        const cumulative = operationId ? (appliedStaticsDeltaByOperation.get(operationId) || 0) : 0
        if (statics && operationId && cumulative > 0) {
            recordAppliedMessagesDelta(statics, operationId, cumulative)
        }
        ReloadChatPointer.set({}) // force the message list to re-render (the verified trigger)
        return {
            merged: true,
            savedChatId: target?.deliveryChatId || chatId,
            conflictCreated,
            globalConflicts: globalMerge.conflicts.length,
        }
    } catch (e) {
        console.error('[bg-orch] merge failed', e)
        return { merged: false, savedChatId: chatId, conflictCreated: false, globalConflicts: 0 }
    }
}

// One visibilitychange listener (module load): poll immediately on foreground return (iOS suspends
// the setInterval in the background). On the server bundle document is a stub → no-op.
try {
    if (typeof document !== 'undefined') {
        document.addEventListener('visibilitychange', () => {
            if (document.visibilityState === 'visible' && watchKey) void pollOrchestrationResult()
        })
    }
} catch { /* best-effort */ }

// ── cold-boot recovery ───────────────────────────────────────────────────────
// A dedicated poll (NOT the in-memory watch's pollOrchestrationResult) so the verified suspend path
// stays untouched. It drives the 생성중 UI (orchestrating + chatProcessStage + relayed status toast)
// ONLY once the server confirms an active gen (stage ≥ 1) or a parked result — so a stale marker
// (nothing running) never shows a phantom spinner (else the user can't tell "recovering" from
// "queue lost" — and a leftover marker would spin forever). It does NOT client-regenerate on failure
// (the original sendChat arg is gone after a reload): it merges a completed result or, on a definitive
// server failure, notifies. Reuses mergeOrchestrationResult + the kv result endpoint.
let bootRecoveryEpoch = 0
let bootRecoveryActive = false
let bootRecoveryQueue: OrchestrationPendingMarker[] = []
let bootRecoveryReadyTimer: ReturnType<typeof setInterval> | null = null
async function fetchBootRecovery(url: string): Promise<Response> {
    return fetchOrchestrationControl(url, { method: 'GET', credentials: 'same-origin' })
}
// Terminal cleanup of the recovery 생성중 UI (mirror of stopWatch's UI reset, minus the in-memory
// watch state which boot recovery doesn't use).
function endBootRecoveryUI(operationId: string | null): void {
    bootRecoveryEpoch++
    if (bootRecoveryReadyTimer) {
        clearInterval(bootRecoveryReadyTimer)
        bootRecoveryReadyTimer = null
    }
    activeOperationId = null
    activeOperationCoordinates = null
    watchResultKeyVersion = 0
    setServerGenerationBusy(false)
    chatProcessStage.set(0)
    try { clearRelayedStatuses() } catch { /* best-effort */ }
    appliedStaticsDeltaByOperation.clear()
    resultDeliveriesInFlight.clear()
    appliedResultOrderByOperation.clear()
    stopAllResultClaimHeartbeats()
    if (operationId) mergeTargetByOperation.delete(operationId)
    if (operationId) completionNotifiedOperations.delete(operationId)
}
function finishBootRecovery(operationId: string | null): void {
    clearPendingMarker(operationId)
    endBootRecoveryUI(operationId)
    bootRecoveryActive = false
    setTimeout(scheduleNextBootRecovery, 0)
}
function deferBootRecovery(operationId: string | null): void {
    // Stop the visible recovery attempt but retain its bounded localStorage marker. A future boot
    // can still ACK/merge the paid result until the normal 30-minute marker/result TTL expires.
    endBootRecoveryUI(operationId)
    bootRecoveryActive = false
    setTimeout(scheduleNextBootRecovery, 0)
}
// consecutive (found:false + stage:0) polls that mean "no gen running server-side" ⇒ the marker
// points at an already-done/consumed/lost gen (stale) ⇒ give up without ever showing a spinner.
// A grace of a few polls covers a brief boot/server-restart race; a genuinely in-flight gen (started
// before the kill) is well past stage 0 by the time we poll, so it reports stage ≥ 1.
const BOOT_EMPTY_LIMIT = 3
function bootRecoverPoll(
    charId: string,
    chatId: string,
    baselineMsgs: number,
    operationId: string | null,
    resultKeyVersion: 0 | 1,
    deadline: number,
    emptyCount: number,
    epoch: number,
): void {
    if (epoch !== bootRecoveryEpoch) return
    if (Date.now() > deadline) { deferBootRecovery(operationId); return }
    void (async () => {
        try {
            const res = await fetchBootRecovery(
                orchestrationResultUrl(charId, chatId, operationId, resultKeyVersion),
            )
            if (res.status === 409) {
                setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, emptyCount, epoch), ORCH_POLL_MS)
                return
            }
            if (!res.ok) throw new Error(`boot result peek failed: HTTP ${res.status}`)
            const data = await res.json()
            if (epoch !== bootRecoveryEpoch) return
            if (!data || !data.found) {
                const stage = data && typeof data.stage === 'number' ? data.stage : 0
                const operationState = data?.operationState
                if (operationState === 'start-retry-required') {
                    finishBootRecovery(operationId)
                    try { alertError('서버가 생성 시작 전에 재시작됐어요. 해당 채팅에서 다시 보내주세요.') } catch { /* best-effort */ }
                    return
                }
                if (operationState === 'interrupted-before-result') {
                    finishBootRecovery(operationId)
                    try { alertError('서버 재시작으로 백그라운드 생성 흐름이 중단됐어요. 이미 사용된 토큰 비용이 있을 수 있어요.') } catch { /* best-effort */ }
                    return
                }
                if (operationState === 'interrupted-after-main') {
                    playMessageCompletionSound()
                    finishBootRecovery(operationId)
                    try { alertError('본문 답변은 저장했지만 서버 재시작으로 후처리를 끝내지 못했어요.') } catch { /* best-effort */ }
                    return
                }
                // The page can be killed after the server accepted operation-keyed delivery but
                // before the POST response updated its marker. Re-negotiate from exact status before
                // treating a legacy stage-0 response as stale.
                if (resultKeyVersion === 0 && operationId && stage === 0) {
                    const negotiated = await probeOperationResultKeyVersion(charId, chatId, operationId)
                    if (epoch !== bootRecoveryEpoch) return
                    if (negotiated === 1) {
                        try {
                            updatePendingMarker(localStorage, operationId, (marker) => ({
                                ...marker, resultKeyVersion: 1,
                            }))
                        } catch { /* in-memory recovery can still continue */ }
                        watchResultKeyVersion = 1
                        setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, 1, deadline, 0, epoch), 0)
                        return
                    }
                    if (negotiated === null) {
                        setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, 0, deadline, emptyCount, epoch), ORCH_POLL_MS)
                        return
                    }
                }
                if (operationState === 'delivery-failed') {
                    finishBootRecovery(operationId)
                    try {
                        alertError('생성은 끝났지만 서버가 결과를 저장하지 못했어요. 다시 보내면 이전 생성 비용에 더해 새 비용이 들 수 있어요.')
                    } catch { /* best-effort */ }
                    return
                }
                if (operationState === 'delivered' || operationState === 'cancelled') {
                    finishBootRecovery(operationId)
                    return
                }
                // An operation-keyed route has exact durable state; missing+stage0 cannot be a
                // queued cold-start ambiguity. Clear it after one bounded probe instead of showing
                // a recovery spinner for the legacy three-poll grace period.
                if (resultKeyVersion === 1 && operationState === 'missing' && stage === 0) {
                    finishBootRecovery(operationId)
                    return
                }
                const activeWithoutStage = operationState === 'queued' || operationState === 'running'
                if (stage >= 1 || activeWithoutStage) {
                    setServerGenerationBusy(true)
                    chatProcessStage.set(stage >= 1 ? stage : 1)
                    if (Array.isArray(data.status)) { try { ingestRelayedStatuses(data.status) } catch { /* best-effort */ } }
                    setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                } else { // stage 0 = nothing running → stale marker after a short grace → stop (no phantom spinner)
                    const n = emptyCount + 1
                    if (n >= BOOT_EMPTY_LIMIT) { finishBootRecovery(operationId); return }
                    setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, n, epoch), ORCH_POLL_MS)
                }
                return
            }
            if (operationId && data.operationId !== operationId) {
                setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, emptyCount, epoch), ORCH_POLL_MS)
                return
            }
            // Only a confirmed active/result response owns the visible busy lease. A stale marker
            // plus an offline server must never create a 15-minute phantom purple spinner.
            setServerGenerationBusy(true)
            chatProcessStage.set(4)
            const orderDecision = classifyOrchestrationResultOrder(data, appliedResultOrderByOperation)
            if (orderDecision === 'conflict') {
                console.error('[bg-orch] boot result sequence conflict; retaining server revision', {
                    operationId: data.operationId, publishSeq: data.publishSeq, resultId: data.resultId,
                })
                setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                return
            }
            if (orderDecision === 'duplicate' || orderDecision === 'stale') {
                const resultId = typeof data.resultId === 'string' ? data.resultId : null
                if (!resultId) return
                const acknowledgement = await acknowledgeResultRevision(
                    charId, chatId, operationId, resultKeyVersion, resultId,
                )
                if (epoch !== bootRecoveryEpoch) return
                if (acknowledgement === 'superseded') {
                    setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                    return
                }
                if (!isConfirmedOrchestrationAcknowledgement(acknowledgement)) {
                    if (isTerminalOrchestrationResult(data)) {
                        runServerCompletionEpilogue(operationId, data)
                        deferBootRecovery(operationId)
                    } else {
                        setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                    }
                    return
                }
                if (isTerminalOrchestrationResult(data)) {
                    runServerCompletionEpilogue(operationId, data)
                    finishBootRecovery(operationId)
                } else {
                    setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                }
                return
            }
            const newMsgs = data.chat && Array.isArray(data.chat.message) ? data.chat.message.length : -1
            if (data.chat && newMsgs > baselineMsgs) {
                const delivery = await persistMergedOrchestrationResult(charId, chatId, data)
                if (epoch !== bootRecoveryEpoch) return
                if (!delivery.durable) {
                    console.warn('[bg-orch] boot merged result save failed; retaining server revision', delivery.error)
                    setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                    return
                }
                if (isTerminalOrchestrationResult(data)) {
                    runServerCompletionEpilogue(operationId, data)
                }
                if (delivery.conflictCreated) {
                    try { alertError('생성 중 채팅이 수정되어 서버 결과를 “BG conflict” 새 채팅으로 보존했어요.') } catch { /* best-effort */ }
                }
                if (delivery.globalConflicts > 0) {
                    try { alertError(`생성 중 수정된 전역 변수 ${delivery.globalConflicts}개는 현재 값을 유지하고 서버 변경도 복구 기록에 보존했어요.`) } catch { /* best-effort */ }
                }
                commitOrchestrationResultOrder(data, appliedResultOrderByOperation)
                if (delivery.acknowledgement === 'superseded') {
                    setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                    return
                }
                if (!isConfirmedOrchestrationAcknowledgement(delivery.acknowledgement)) {
                    if (isTerminalOrchestrationResult(data)) deferBootRecovery(operationId)
                    else setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                    return
                }
                if (isTerminalOrchestrationResult(data)) {
                    if (isPartialOrchestrationResult(data)) console.warn('[bg-orch] boot recovery merged terminal partial:', data.error)
                    runServerCompletionEpilogue(operationId, data)
                    finishBootRecovery(operationId)
                    return
                }
                setServerGenerationBusy(true) // intermediate main snapshot; post still running
                setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
            } else {
                // Definitive failure (chat:null / threw before main / 0 new messages). Can't replay the
                // original send after a reload — ACK the exact decision, then notify so the user resends.
                const acknowledgement = await acknowledgeUnmergedResult(charId, chatId, data)
                if (epoch !== bootRecoveryEpoch) return
                if (acknowledgement === 'superseded'
                ) {
                    setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, 0, epoch), ORCH_POLL_MS)
                    return
                }
                if (!isConfirmedOrchestrationAcknowledgement(acknowledgement)) {
                    deferBootRecovery(operationId)
                    try { alertError('백그라운드 생성은 답변 없이 끝났고 서버 정리 확인이 지연됐어요. 다음 실행 때 재확인해요.') } catch { /* best-effort */ }
                    return
                }
                finishBootRecovery(operationId)
                try { alertError('백그라운드 생성을 완료하지 못했어요. 해당 채팅에서 다시 보내주세요.') } catch { /* best-effort */ }
            }
        } catch {
            setTimeout(() => bootRecoverPoll(charId, chatId, baselineMsgs, operationId, resultKeyVersion, deadline, emptyCount, epoch), ORCH_POLL_MS)
        }
    })()
}

// At boot: if a delegation marker survived a kill, wait for its char/chat to load into DBState, then
// recover. Guarded to the client runtime (the server bundle sets __bgOrch → isServerOrchestrationEnabled
// false, and has no real localStorage/DBState).
function scheduleBootRecovery(): void {
    try { bootRecoveryQueue = readPendingMarkers(localStorage) } catch { return }
    scheduleNextBootRecovery()
}

async function beginBootRecoveryAfterHydration(
    marker: OrchestrationPendingMarker,
    readyStart: number,
    readyTimeoutMs: number,
): Promise<void> {
    const { charId, chatId, baselineMsgs, operationId, resultKeyVersion } = marker
    const readinessEpoch = bootRecoveryEpoch
    try {
        const timeoutToken = Symbol('boot-recovery-hydration-timeout')
        let chats: any[] = []
        let db = (DBState as any).db as Record<string, unknown>
        let rootDelivery = operationId ? readRootDelivery(db, operationId) : null
        // The character or its chats array can be replaced while an async hydration is in flight.
        // Repeat against the current DB reference until the exact array we hydrated is still live.
        while (true) {
            const currentDb = (DBState as any)?.db as Record<string, unknown>
            const chars = (currentDb as any)?.characters
            const currentChar = Array.isArray(chars)
                ? chars.find((candidate: any) => candidate && candidate.chaId === charId)
                : null
            if (!currentChar || !Array.isArray(currentChar.chats)) {
                deferBootRecovery(operationId)
                return
            }
            chats = currentChar.chats
            db = currentDb
            // Root evidence survives lazy-chat boot and, when present, names the exact branch whose
            // body must be hydrated before we can validate the matching in-chat delivery evidence.
            rootDelivery = operationId ? readRootDelivery(db, operationId) : null
            const recoveryChatId = rootDelivery?.deliveryChatId || marker.deliveryChatId || chatId
            const remainingMs = readyTimeoutMs - (Date.now() - readyStart)
            let hydrationTimeout: ReturnType<typeof setTimeout> | null = null
            const readiness = remainingMs <= 0
                ? timeoutToken
                : await Promise.race([
                    resolveOrchestrationRecoveryTarget(
                        chats, recoveryChatId, charId, ensureChatHydrated,
                    ),
                    new Promise<typeof timeoutToken>((resolve) => {
                        hydrationTimeout = setTimeout(() => resolve(timeoutToken), remainingMs)
                    }),
                ]).finally(() => {
                    if (hydrationTimeout) clearTimeout(hydrationTimeout)
                })

            // A foreground send can explicitly defer this marker while hydration is in flight.
            if (!bootRecoveryActive || bootRecoveryEpoch !== readinessEpoch) return
            if (readiness === timeoutToken || readiness.status === 'retry') {
                // Never poll, merge, or ACK against a placeholder. The server result and local marker
                // remain parked for a later boot after storage/hydration recovers.
                deferBootRecovery(operationId)
                return
            }
            const latestDb = (DBState as any)?.db as Record<string, unknown>
            const latestChars = (latestDb as any)?.characters
            const latestChar = Array.isArray(latestChars)
                ? latestChars.find((candidate: any) => candidate && candidate.chaId === charId)
                : null
            if (latestDb === currentDb && latestChar === currentChar && latestChar?.chats === chats) break
        }
        if (watchKey || activeOperationId || get(doingChat)) {
            bootRecoveryQueue.unshift(marker)
            bootRecoveryActive = false
            return
        }

        if (operationId) {
            const committed = readFullyCommittedDelivery(db, chats, operationId)
            // If the user deleted an already-delivered branch, root evidence still identifies the
            // deleted target so the existing conflict-copy fallback preserves the parked result.
            const chatDelivery = committed || findChatDelivery(chats, operationId) || rootDelivery
            const deliveryChatId = chatDelivery?.deliveryChatId || marker.deliveryChatId || chatId
            const deliveryChat = chats.find((candidate: any) => candidate && candidate.id === deliveryChatId)
            const originalChat = chats.find((candidate: any) => candidate && candidate.id === chatId)
            mergeTargetByOperation.set(operationId, {
                deliveryChatId,
                expectedChatRevision: chatDelivery?.expectedChatRevision || marker.expectedChatRevision
                    || orchestrationChatRevision(deliveryChat || originalChat || null),
                conflict: chatDelivery?.conflict ?? (deliveryChatId !== chatId),
            })
            if (committed) {
                appliedResultOrderByOperation.set(operationId, {
                    publishSeq: committed.publishSeq,
                    resultId: committed.resultId,
                })
            }
        }
        seedAppliedMessagesDeltaFromStatics(
            appliedStaticsDeltaByOperation,
            (DBState as any)?.db?.statics,
            operationId,
        )
        if (operationId && marker.completionNotified) {
            completionNotifiedOperations.add(operationId)
        }
        const epoch = ++bootRecoveryEpoch
        // Reserve only the recovery identity. The first exact server response turns on the visible
        // busy lease; a foreground send that wins this probe window explicitly defers this marker.
        activeOperationId = operationId
        activeOperationCoordinates = { charId, chatId }
        watchResultKeyVersion = resultKeyVersion
        // Do NOT show 생성중 upfront — the poll turns it on only if the server reports an active gen
        // (stage ≥ 1), so a stale marker (nothing running) never produces a phantom spinner.
        bootRecoverPoll(
            charId, chatId, baselineMsgs, operationId, resultKeyVersion,
            Date.now() + ORCH_DEADLINE_MS, 0, epoch,
        )
    } catch {
        if (bootRecoveryActive && bootRecoveryEpoch === readinessEpoch) {
            deferBootRecovery(operationId)
        }
    }
}

function scheduleNextBootRecovery(): void {
    if (bootRecoveryActive) return
    const marker = bootRecoveryQueue.shift()
    if (!marker) return
    bootRecoveryActive = true
    const { charId, chatId, baselineMsgs, operationId, resultKeyVersion } = marker
    // Pre-M6 markers have no DB-atomic ledger, so retain their best available localStorage seed for
    // rolling recovery. M6+ markers deliberately ignore it and seed from statics after DB load.
    if (marker.deliveryVersion < 2) {
        seedAppliedMessagesDelta(appliedStaticsDeltaByOperation, operationId, marker.staticsMessagesApplied)
    }
    const readyStart = Date.now()
    const READY_TIMEOUT_MS = 60000 // db never loaded the char (deleted?) → give up
    if (bootRecoveryReadyTimer) clearInterval(bootRecoveryReadyTimer)
    const iv = bootRecoveryReadyTimer = setInterval(() => {
        if (Date.now() - readyStart > READY_TIMEOUT_MS) {
            clearInterval(iv)
            if (bootRecoveryReadyTimer === iv) bootRecoveryReadyTimer = null
            // DB readiness can be transient on a cold mobile boot. Retain the marker for the next
            // boot instead of turning a 60-second load delay into permanent result loss.
            appliedStaticsDeltaByOperation.clear()
            bootRecoveryActive = false
            scheduleNextBootRecovery()
            return
        }
        const chars = (DBState as any)?.db?.characters
        if (!Array.isArray(chars)) return
        const char = chars.find((c: any) => c && c.chaId === charId)
        if (!char) return
        const chat = Array.isArray(char.chats) ? char.chats.find((c: any) => c && c.id === chatId) : null
        if (!chat && !operationId) return
        // A foreground generation may have started while this marker was waiting for DB readiness.
        // Never overwrite its single in-memory watch identity. Put this marker back; the combined
        // busy-store subscription below resumes recovery when that generation reaches terminal.
        if (watchKey || activeOperationId || get(doingChat)) {
            clearInterval(iv)
            if (bootRecoveryReadyTimer === iv) bootRecoveryReadyTimer = null
            bootRecoveryQueue.unshift(marker)
            bootRecoveryActive = false
            return
        }
        clearInterval(iv)
        if (bootRecoveryReadyTimer === iv) bootRecoveryReadyTimer = null
        void beginBootRecoveryAfterHydration(marker, readyStart, READY_TIMEOUT_MS)
    }, 500)
}
try {
    if (isServerOrchestrationEnabled() && typeof document !== 'undefined') scheduleBootRecovery()
} catch { /* best-effort */ }

// A marker deferred because a normal client/server generation was active resumes when the shared
// busy lease becomes idle. This avoids a polling timer for the entire (possibly multi-minute) run.
try {
    doingChat.subscribe((busy) => {
        if (!busy && !bootRecoveryActive && bootRecoveryQueue.length > 0 && !watchKey) {
            setTimeout(scheduleNextBootRecovery, 0)
        }
    })
} catch { /* server bundle / early module init: no recovery queue there */ }

// Entry from sendChat's redirect. Hand the WHOLE generation to the server, return handled:true
// (the client does NOT generate), then watch + merge on return — with auto-fallback to the client's
// own generation if the server produces no main reply.
export async function runServerOrchestratedChat(
    chatProcessIndex: number,
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    arg: any,
): Promise<OrchestrateOutcome> {
    try {
        const charIdx = get(selectedCharID)
        const char: any = (DBState as any)?.db?.characters?.[charIdx]
        const chat: any = char?.chats?.[char?.chatPage]
        if (!char || !chat) return { handled: false }

        if (bootRecoveryActive && !watchKey) {
            // A user send won the short pre-confirmation boot probe window. Invalidate that poll and
            // retain its marker for a later boot instead of letting it replace this foreground watch.
            deferBootRecovery(activeOperationId)
        }

        // User's message already exists only in browser memory at this point. Hold the ordinary
        // client lease while strictly saving it, then read the committed chat back through the same
        // decode/normalize path used by hydration. That canonical graph is the provider and recovery
        // base; provider work must never begin if either the save or canonical read fails.
        doingChat.set(true)
        chatProcessStage.set(1) // show the top-bar immediately (assembly); polls refine the stage
        const charId = char.chaId, chatId = chat.id
        let delegatedChat: any
        let liveExpectedChatRevision = ''
        try {
            delegatedChat = await persistBeforeOrchestrationStart(
                () => persistCanonicalOrchestrationBase(
                    () => {
                        const chars: any[] = (DBState as any)?.db?.characters
                        const currentChar = Array.isArray(chars)
                            ? chars.find((candidate) => candidate?.chaId === charId)
                            : null
                        const currentChat = Array.isArray(currentChar?.chats)
                            ? currentChar.chats.find((candidate: any) => candidate?.id === chatId)
                            : null
                        if (!currentChat || currentChat._placeholder) {
                            throw new Error('durable orchestration base chat is unavailable')
                        }
                        return orchestrationChatRevision(currentChat)
                    },
                    () => requestDurableSave({ chat: [charId, chatId] }),
                    async () => {
                        const chars: any[] = (DBState as any)?.db?.characters
                        const currentChar = Array.isArray(chars)
                            ? chars.find((candidate) => candidate?.chaId === charId)
                            : null
                        const chatIndex = Array.isArray(currentChar?.chats)
                            ? currentChar.chats.findIndex((candidate: any) => candidate?.id === chatId)
                            : -1
                        if (chatIndex < 0) {
                            throw new Error('canonical orchestration base chat is unavailable')
                        }
                        const persistedChat: any = await fetchChatFromServer(charId, chatIndex, chatId)
                        if (!persistedChat || persistedChat.id !== chatId || persistedChat._placeholder) {
                            throw new Error('canonical orchestration base chat is unavailable after save')
                        }
                        return persistedChat
                    },
                ),
                (persistedChat) => {
                    const chars: any[] = (DBState as any)?.db?.characters
                    const liveChar = Array.isArray(chars)
                        ? chars.find((candidate) => candidate?.chaId === charId)
                        : null
                    const liveChat = Array.isArray(liveChar?.chats)
                        ? liveChar.chats.find((candidate: any) => candidate?.id === chatId)
                        : null
                    if (!liveChat || liveChat._placeholder) {
                        throw new Error('live orchestration base chat is unavailable after canonical read')
                    }
                    liveExpectedChatRevision = orchestrationChatRevision(liveChat)
                    return persistedChat
                },
                { signal: arg?.signal },
            )
        } catch (error) {
            doingChat.set(false)
            chatProcessStage.set(0)
            if (arg?.signal?.aborted || (error as { name?: unknown })?.name === 'AbortError') {
                return { handled: true, result: false }
            }
            console.error('[bg-orch] base chat save failed; provider not started', error)
            try { alertError('채팅을 서버에 저장하지 못해 생성을 시작하지 않았어요. 잠시 후 다시 보내주세요.') } catch { /* best-effort */ }
            return { handled: true, result: false }
        }
        if (arg?.signal?.aborted) {
            doingChat.set(false)
            chatProcessStage.set(0)
            return { handled: true, result: false }
        }

        const operationId = v4()
        const baselineMsgs = Array.isArray(delegatedChat.message) ? delegatedChat.message.length : 0
        const expectedChatRevision = orchestrationChatRevision(delegatedChat)
        // The current page still holds the live MobX representation while a cold boot hydrates the
        // canonical representation above. Accept both exact start revisions only for this in-memory
        // operation; the recovery marker and durable operation state retain the canonical one alone.
        const acceptedChatRevisions = liveExpectedChatRevision
            && liveExpectedChatRevision !== expectedChatRevision ? [liveExpectedChatRevision] : []
        // Capture the arg for a faithful fallback replay; drop the stale AbortSignal.
        const fallbackArg: Record<string, unknown> = { ...(arg || {}) }
        delete fallbackArg.signal
        armWatch(
            charId, chatId, baselineMsgs, fallbackArg, operationId,
            expectedChatRevision, acceptedChatRevisions,
        )
        // Persist a cold-boot recovery marker: if the phone kills this page mid-gen (jetsam), the
        // next boot reads this and re-fetches the parked result. Cleared by stopWatch on any terminal.
        writePendingMarker(charId, chatId, baselineMsgs, operationId, expectedChatRevision)
        // Switch leases without exposing an idle transition: acquire the server lease before
        // releasing the client/save lease. From here the spinner tap uses the operation cancel API.
        setServerGenerationBusy(true)
        doingChat.set(false)
        const startBody = JSON.stringify({
            selectedCharId: charId,
            selectedChatId: chatId,
            chatProcessIndex,
            currentChat: delegatedChat,
            currentGlobalChatVariables: (DBState as any)?.db?.globalChatVariables || {},
            globalVariablesVersion: 1,
            detached: true,
            operationId,
            baseChatRevision: expectedChatRevision,
            resultOrderVersion: 1,
            startAckVersion: 1,
            resultKeyVersion: 1,
        })
        void reconcileOrchestrationStart({
            start: async (signal) => {
                const res = await fetch('/api/bg-orchestrate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: startBody,
                    credentials: 'same-origin',
                    signal,
                })
                let data: any = null
                try { data = await res.json() } catch { /* ambiguous response; status reconciles */ }
                if (res.ok && data?.started === true) {
                    rememberResultKeyVersion(operationId, data.resultKeyVersion === 1 ? 1 : 0)
                    return 'accepted'
                }
                // This response came from the start request itself, so auth rejection proves that
                // this POST did not enter the detached pipeline. A later status-request auth error
                // is intentionally still ambiguous: the original POST may already be running.
                if (res.status === 401 || res.status === 403) return 'rejected'
                if (data?.reason === 'operation-coordinate-conflict') {
                    throw new Error('operation coordinate conflict')
                }
                if (data?.started === false || (res.ok && data?.handled === false)) return 'rejected'
                throw new Error(`detached start ambiguous: HTTP ${res.status}`)
            },
            status: async (signal) => {
                const query = `charId=${encodeURIComponent(charId)}&chatId=${encodeURIComponent(chatId)}`
                const res = await fetch(`/api/bg-orchestrate-status/${encodeURIComponent(operationId)}?${query}`, {
                    method: 'GET', credentials: 'same-origin', signal,
                })
                let data: any = null
                try { data = await res.json() } catch { /* a pre-M8 server may return a generic 404 */ }
                const statusClass = classifyOrchestrationStatusResponse(res.status, data, operationId)
                if (statusClass === 'missing') return 'missing'
                if (statusClass === 'legacy-unknown') {
                    // Rolling new-client/old-server: the status route itself is absent, so 404 says
                    // nothing about whether POST started. Probe the existing non-destructive result
                    // endpoint/stage; never retry or fallback merely because capability is absent.
                    const probe = await fetch(orchestrationResultUrl(charId, chatId, operationId, 0), {
                        method: 'GET', credentials: 'same-origin', signal,
                    })
                    if (!probe.ok) throw new Error(`detached legacy status probe failed: HTTP ${probe.status}`)
                    const legacy = await probe.json()
                    if (legacy?.found === true && legacy?.operationId === operationId) return 'accepted'
                    if (legacy?.found === false && typeof legacy.stage === 'number' && legacy.stage >= 1) return 'accepted'
                    throw new Error('detached status unavailable on rolling server')
                }
                if (statusClass === 'accepted') {
                    rememberResultKeyVersion(operationId, data?.resultKeyVersion === 1 ? 1 : 0)
                    return 'accepted'
                }
                if (!res.ok) throw new Error(`detached status ambiguous: HTTP ${res.status}`)
                throw new Error('detached status malformed')
            },
            isCurrent: () => activeOperationId === operationId && !!watchKey,
            deadlineAt: watchDeadline,
        }).then((resolution) => {
            if (activeOperationId !== operationId || !watchKey) return
            if (resolution === 'accepted') startWatchTimer()
            else if (resolution === 'rejected') {
                console.error('[bg-orch] detached start rejected')
                triggerClientFallback('delegate-not-started')
            }
            // abandoned means cancel/deadline already closed the watch; never fallback on ambiguity.
        })
        return { handled: true }
    } catch (e) {
        console.error('[bg-orch] error', e)
        try { stopWatch() } catch { /* don't strand the UI */ }
    }
    return { handled: false }
}

let cancelPromise: Promise<boolean> | null = null
export function cancelServerOrchestratedChat(): Promise<boolean> {
    if (cancelPromise) return cancelPromise
    const operationId = activeOperationId
    if (!operationId) {
        try { alertError('서버에서 취소할 생성 작업을 찾지 못했어요.') } catch { /* best-effort */ }
        return Promise.resolve(false)
    }
    cancelPromise = (async () => {
        try {
            const query = new URLSearchParams()
            if (activeOperationCoordinates?.charId) query.set('charId', activeOperationCoordinates.charId)
            if (activeOperationCoordinates?.chatId) query.set('chatId', activeOperationCoordinates.chatId)
            const suffix = query.size > 0 ? `?${query.toString()}` : ''
            const res = await fetchOrchestrationControl(`/api/bg-orchestrate/${encodeURIComponent(operationId)}${suffix}`, {
                method: 'DELETE', credentials: 'same-origin',
            })
            let data: any = null
            try { data = await res.json() } catch { /* handled below */ }
            if (!res.ok || !data || data.cancelled !== true) {
                try { alertError('서버가 취소 대상을 아직 확인하지 못했어요. 잠시 후 다시 눌러 주세요.') } catch { /* best-effort */ }
                return false
            }
            // ACK means the server delivered abort and forbids any further result publish. Invalidate
            // in-flight polls before hiding the spinner so a late response cannot merge afterwards.
            if (activeOperationId === operationId) {
                if (watchKey) stopWatch()
                else finishBootRecovery(operationId)
            }
            return true
        } catch (e) {
            console.error('[bg-orch] cancel request failed', e)
            try { alertError('취소 요청을 서버에서 확인하지 못했어요. 다시 눌러 주세요.') } catch { /* best-effort */ }
            return false
        } finally {
            cancelPromise = null
        }
    })()
    return cancelPromise
}

export interface OrchestrationPendingMarker {
    charId: string
    chatId: string
    baselineMsgs: number
    operationId: string | null
    deliveryVersion: number
    resultKeyVersion: 0 | 1
    staticsMessagesApplied: number
    deliveryChatId?: string
    expectedChatRevision?: string
    // The reply may already be durable while its exact server ACK is still pending. Persist the
    // browser epilogue separately so a cold boot can retry cleanup without replaying sound/notice.
    completionNotified?: boolean
    ts: number
}

export interface MarkerStorage {
    length: number
    key(index: number): string | null
    getItem(key: string): string | null
    setItem(key: string, value: string): void
    removeItem(key: string): void
}

export const ORCHESTRATION_PENDING_PREFIX = 'bg-orch-pending:'
export const LEGACY_ORCHESTRATION_PENDING_KEY = 'bg-orch-pending'
export const ORCHESTRATION_PENDING_MAX_AGE_MS = 30 * 60 * 1000
// Match the server run registry's hard bound. A smaller client ledger can silently discard an
// older paid operation while the server is still retaining and completing it.
export const ORCHESTRATION_PENDING_MAX_ENTRIES = 128

function markerKey(operationId: string): string {
    return ORCHESTRATION_PENDING_PREFIX + operationId
}

function parseMarker(raw: string | null): OrchestrationPendingMarker | null {
    if (!raw) return null
    try {
        const value = JSON.parse(raw) as Partial<OrchestrationPendingMarker>
        if (!value || typeof value.charId !== 'string' || !value.charId
            || typeof value.chatId !== 'string' || !value.chatId) return null
        return {
            charId: value.charId,
            chatId: value.chatId,
            baselineMsgs: typeof value.baselineMsgs === 'number' ? value.baselineMsgs : 0,
            operationId: typeof value.operationId === 'string' ? value.operationId : null,
            deliveryVersion: typeof value.deliveryVersion === 'number' ? value.deliveryVersion : 0,
            resultKeyVersion: value.resultKeyVersion === 1 ? 1 : 0,
            staticsMessagesApplied: typeof value.staticsMessagesApplied === 'number'
                ? value.staticsMessagesApplied : 0,
            deliveryChatId: typeof value.deliveryChatId === 'string' ? value.deliveryChatId : undefined,
            expectedChatRevision: typeof value.expectedChatRevision === 'string'
                ? value.expectedChatRevision : undefined,
            completionNotified: value.completionNotified === true,
            ts: typeof value.ts === 'number' ? value.ts : 0,
        }
    } catch {
        return null
    }
}

export function readPendingMarkers(
    storage: MarkerStorage,
    now = Date.now(),
): OrchestrationPendingMarker[] {
    const candidates: Array<{ key: string, marker: OrchestrationPendingMarker }> = []
    const keys: string[] = []
    for (let i = 0; i < storage.length; i++) {
        const key = storage.key(i)
        if (key === LEGACY_ORCHESTRATION_PENDING_KEY || key?.startsWith(ORCHESTRATION_PENDING_PREFIX)) {
            keys.push(key)
        }
    }
    for (const key of keys) {
        const marker = parseMarker(storage.getItem(key))
        if (!marker || (marker.ts > 0 && now - marker.ts > ORCHESTRATION_PENDING_MAX_AGE_MS)) {
            storage.removeItem(key)
            continue
        }
        candidates.push({ key, marker })
    }
    candidates.sort((a, b) => a.marker.ts - b.marker.ts)
    const retained = candidates.slice(-ORCHESTRATION_PENDING_MAX_ENTRIES)
    for (const candidate of candidates.slice(0, -ORCHESTRATION_PENDING_MAX_ENTRIES)) {
        storage.removeItem(candidate.key)
    }
    const seen = new Set<string>()
    return retained.map(({ marker }) => marker).filter((marker) => {
        const identity = marker.operationId || `${marker.charId}\0${marker.chatId}\0${marker.ts}`
        if (seen.has(identity)) return false
        seen.add(identity)
        return true
    })
}

export function writePendingMarker(
    storage: MarkerStorage,
    marker: OrchestrationPendingMarker,
): void {
    if (!marker.operationId) throw new Error('new pending markers require an operation id')
    storage.setItem(markerKey(marker.operationId), JSON.stringify(marker))
    readPendingMarkers(storage, marker.ts)
}

export function updatePendingMarker(
    storage: MarkerStorage,
    operationId: string,
    update: (marker: OrchestrationPendingMarker) => OrchestrationPendingMarker,
): void {
    const key = markerKey(operationId)
    const marker = parseMarker(storage.getItem(key))
    if (!marker || marker.operationId !== operationId) return
    storage.setItem(key, JSON.stringify(update(marker)))
}

export function clearPendingMarker(storage: MarkerStorage, operationId: string | null): void {
    storage.removeItem(operationId ? markerKey(operationId) : LEGACY_ORCHESTRATION_PENDING_KEY)
}

import { describe, expect, test } from 'vitest'
import {
    clearPendingMarker,
    LEGACY_ORCHESTRATION_PENDING_KEY,
    ORCHESTRATION_PENDING_MAX_AGE_MS,
    ORCHESTRATION_PENDING_MAX_ENTRIES,
    ORCHESTRATION_PENDING_PREFIX,
    readPendingMarkers,
    type MarkerStorage,
    updatePendingMarker,
    writePendingMarker,
} from './bgOrchestrationPending'

class MemoryStorage implements MarkerStorage {
    values = new Map<string, string>()
    get length() { return this.values.size }
    key(index: number) { return [...this.values.keys()][index] ?? null }
    getItem(key: string) { return this.values.get(key) ?? null }
    setItem(key: string, value: string) { this.values.set(key, value) }
    removeItem(key: string) { this.values.delete(key) }
}

function marker(operationId: string, ts: number) {
    return {
        charId: 'char-1', chatId: 'chat-1', baselineMsgs: 2, operationId,
        deliveryVersion: 3, resultKeyVersion: 0 as const, staticsMessagesApplied: 0, ts,
    }
}

describe('orchestration pending markers', () => {
    test('different operations use independent keys instead of overwriting one slot', () => {
        const storage = new MemoryStorage()
        writePendingMarker(storage, marker('operation-1', 1))
        writePendingMarker(storage, marker('operation-2', 2))

        expect(readPendingMarkers(storage, 2).map((value) => value.operationId)).toEqual([
            'operation-1', 'operation-2',
        ])
        clearPendingMarker(storage, 'operation-1')
        expect(storage.values.has(`${ORCHESTRATION_PENDING_PREFIX}operation-2`)).toBe(true)
    })

    test('protocol capability and statics progress update only the exact operation', () => {
        const storage = new MemoryStorage()
        writePendingMarker(storage, marker('operation-1', 1))
        writePendingMarker(storage, marker('operation-2', 2))
        updatePendingMarker(storage, 'operation-1', (value) => ({
            ...value, resultKeyVersion: 1, staticsMessagesApplied: 3, completionNotified: true,
        }))

        expect(readPendingMarkers(storage, 2)).toMatchObject([
            { operationId: 'operation-1', resultKeyVersion: 1, staticsMessagesApplied: 3, completionNotified: true },
            { operationId: 'operation-2', resultKeyVersion: 0, staticsMessagesApplied: 0, completionNotified: false },
        ])
    })

    test('expired and excess markers are pruned without touching unrelated storage', () => {
        const storage = new MemoryStorage()
        storage.setItem('unrelated', 'keep')
        writePendingMarker(storage, marker('expired-operation', 1))
        const now = ORCHESTRATION_PENDING_MAX_AGE_MS + 2
        for (let i = 0; i < ORCHESTRATION_PENDING_MAX_ENTRIES + 2; i++) {
            writePendingMarker(storage, marker(`operation-${i}`, now + i))
        }

        expect(readPendingMarkers(storage, now + ORCHESTRATION_PENDING_MAX_ENTRIES + 2)).toHaveLength(
            ORCHESTRATION_PENDING_MAX_ENTRIES,
        )
        expect(storage.getItem('unrelated')).toBe('keep')
        expect(storage.values.has(`${ORCHESTRATION_PENDING_PREFIX}expired-operation`)).toBe(false)
    })

    test('a legacy single marker remains recoverable and independently clearable', () => {
        const storage = new MemoryStorage()
        storage.setItem(LEGACY_ORCHESTRATION_PENDING_KEY, JSON.stringify({
            charId: 'char-old', chatId: 'chat-old', baselineMsgs: 1, ts: 5,
        }))
        expect(readPendingMarkers(storage, 5)).toMatchObject([
            { charId: 'char-old', chatId: 'chat-old', operationId: null, resultKeyVersion: 0 },
        ])
        clearPendingMarker(storage, null)
        expect(storage.length).toBe(0)
    })
})

