import { ORCHESTRATION_CHAT_DELIVERY_FIELD } from './bgOrchestrationDelivery'

export interface OrchestrationMergeTarget {
    deliveryChatId: string
    expectedChatRevision: string
    acceptedChatRevisions?: string[]
    conflict: boolean
}

export type OrchestrationRecoveryTarget<T extends Record<string, unknown>> =
    | { status: 'ready', index: number, chat: T }
    | { status: 'missing', index: -1, chat: null }
    | { status: 'retry', index: number, chat: null }

export function orchestrationRecoveryTargetIsFull(chat: unknown): chat is Record<string, unknown> {
    return !!chat && typeof chat === 'object' && !Array.isArray(chat)
        && (chat as Record<string, unknown>)._placeholder !== true
        && Array.isArray((chat as Record<string, unknown>).message)
}

// A cold Node boot initially exposes lazy-chat placeholders with the real id but an empty message
// graph. Conflict detection must never compare that synthetic graph with the canonical delegation
// base. Re-find by id after hydration because the chat array can be reordered or the target can be
// deleted while the server read is in flight.
export async function resolveOrchestrationRecoveryTarget<T extends Record<string, unknown>>(
    chats: T[],
    chatId: string,
    charId: string,
    hydrate: (targetChats: T[], index: number, targetCharId: string) => Promise<T | null>,
): Promise<OrchestrationRecoveryTarget<T>> {
    let index = chats.findIndex((chat) => chat && chat.id === chatId)
    if (index < 0) return { status: 'missing', index: -1, chat: null }

    const initial = chats[index]
    if (initial._placeholder !== true) {
        return orchestrationRecoveryTargetIsFull(initial)
            ? { status: 'ready', index, chat: initial }
            : { status: 'retry', index, chat: null }
    }

    try {
        await hydrate(chats, index, charId)
    } catch { /* a transient storage failure leaves the parked result retryable next boot */ }

    index = chats.findIndex((chat) => chat && chat.id === chatId)
    if (index < 0) return { status: 'missing', index: -1, chat: null }
    const current = chats[index]
    if (!orchestrationRecoveryTargetIsFull(current)) {
        return { status: 'retry', index, chat: null }
    }
    return { status: 'ready', index, chat: current }
}

const ORCHESTRATION_TRANSIENT_CHAT_FIELDS = new Set([
    ORCHESTRATION_CHAT_DELIVERY_FIELD,
    '_placeholder',
    'isStreaming',
])
const ORCHESTRATION_TRANSIENT_MESSAGE_FIELDS = new Set(['chatId', 'time'])

type RevisionContext = 'chat' | 'message' | 'nested'

// Build a stable semantic JSON graph. PocketRisu hydration and the server send pipeline are allowed
// to add/remove engine-owned fields without the user editing anything: hydration removes the
// placeholder, streaming toggles isStreaming, sendChat backfills message chatId, and historical
// saves do not consistently retain message time. Those fields must not fork a paid cold-boot
// result. Everything user-visible/editable remains in the graph, and sorting object keys also
// makes equivalent decoded objects independent of serialization insertion order.
function orchestrationRevisionValue(value: unknown, context: RevisionContext): unknown {
    if (value === null || typeof value === 'string' || typeof value === 'boolean') return value
    if (typeof value === 'number') return Number.isFinite(value) ? value : null
    if (typeof value === 'undefined' || typeof value === 'function'
        || typeof value === 'symbol' || typeof value === 'bigint') return undefined
    if (Array.isArray(value)) {
        return value.map((item) => {
            const normalized = orchestrationRevisionValue(item, context)
            return normalized === undefined ? null : normalized
        })
    }
    if (typeof value !== 'object') return value

    const source = value as Record<string, unknown>
    const normalized: Record<string, unknown> = {}
    for (const key of Object.keys(source).sort()) {
        if (context === 'chat' && ORCHESTRATION_TRANSIENT_CHAT_FIELDS.has(key)) continue
        if (context === 'message' && ORCHESTRATION_TRANSIENT_MESSAGE_FIELDS.has(key)) continue
        const childContext: RevisionContext = context === 'chat' && key === 'message'
            ? 'message'
            : 'nested'
        const child = orchestrationRevisionValue(source[key], childContext)
        if (child !== undefined) normalized[key] = child
    }
    return normalized
}

// Compact deterministic semantic fingerprint for conflict detection. Two independent 32-bit lanes
// make an accidental collision negligible while keeping the cold-boot marker small.
export function orchestrationChatRevision(chat: unknown): string {
    const revisionSource = orchestrationRevisionValue(chat, 'chat')
    const text = JSON.stringify(revisionSource) ?? ''
    let first = 0x811c9dc5
    let second = 0x9e3779b9
    for (let i = 0; i < text.length; i++) {
        const code = text.charCodeAt(i)
        first = Math.imul(first ^ code, 0x01000193)
        second = Math.imul(second ^ (code + i), 0x85ebca6b)
    }
    return `${text.length.toString(36)}-${(first >>> 0).toString(36)}-${(second >>> 0).toString(36)}`
}

// Rolling compatibility for pending markers written before semantic revisions existed. Those
// markers carry the exact full-object hash and can remain in localStorage for 30 minutes across a
// frontend deployment. Accept an unchanged legacy graph, but keep its old conservative behavior
// when save/hydration already changed the graph: the paid result then forks instead of overwriting.
export function orchestrationLegacyChatRevision(chat: unknown): string {
    const revisionSource = chat && typeof chat === 'object' && !Array.isArray(chat)
        ? { ...(chat as Record<string, unknown>) }
        : chat
    if (revisionSource && typeof revisionSource === 'object' && !Array.isArray(revisionSource)) {
        delete (revisionSource as Record<string, unknown>)[ORCHESTRATION_CHAT_DELIVERY_FIELD]
    }
    const text = JSON.stringify(revisionSource) ?? ''
    let first = 0x811c9dc5
    let second = 0x9e3779b9
    for (let i = 0; i < text.length; i++) {
        const code = text.charCodeAt(i)
        first = Math.imul(first ^ code, 0x01000193)
        second = Math.imul(second ^ (code + i), 0x85ebca6b)
    }
    return `${text.length.toString(36)}-${(first >>> 0).toString(36)}-${(second >>> 0).toString(36)}`
}

export function orchestrationTargetHasConflict(
    currentChat: unknown,
    target: Pick<OrchestrationMergeTarget, 'expectedChatRevision' | 'acceptedChatRevisions'>,
): boolean {
    const semanticRevision = orchestrationChatRevision(currentChat)
    if (semanticRevision === target.expectedChatRevision
        || target.acceptedChatRevisions?.includes(semanticRevision)) return false
    return orchestrationLegacyChatRevision(currentChat) !== target.expectedChatRevision
}

export function createConflictChat(
    incomingChat: Record<string, unknown>,
    newChatId: string,
): Record<string, unknown> {
    const cloned = JSON.parse(JSON.stringify(incomingChat)) as Record<string, unknown>
    const originalName = typeof cloned.name === 'string' && cloned.name.trim() ? cloned.name.trim() : 'Chat'
    return {
        ...cloned,
        id: newChatId,
        name: `${originalName} · BG conflict`,
        isStreaming: false,
        _placeholder: false,
    }
}

export function applyOrchestrationChatResult(
    chats: Array<Record<string, unknown>>,
    incomingChat: Record<string, unknown>,
    target: OrchestrationMergeTarget,
    newConflictId: () => string,
): { target: OrchestrationMergeTarget, targetIndex: number, conflictCreated: boolean } {
    const nextTarget = { ...target }
    let targetIndex = chats.findIndex((chat) => chat && chat.id === nextTarget.deliveryChatId)
    let conflictCreated = false
    if (targetIndex >= 0 && orchestrationTargetHasConflict(chats[targetIndex], nextTarget)) {
        const conflictId = newConflictId()
        chats.push(createConflictChat(incomingChat, conflictId))
        targetIndex = chats.length - 1
        nextTarget.deliveryChatId = conflictId
        nextTarget.conflict = true
        conflictCreated = true
    } else if (targetIndex < 0) {
        const conflictId = nextTarget.conflict ? nextTarget.deliveryChatId : newConflictId()
        chats.push(createConflictChat(incomingChat, conflictId))
        targetIndex = chats.length - 1
        nextTarget.deliveryChatId = conflictId
        nextTarget.conflict = true
        conflictCreated = true
    } else if (nextTarget.conflict) {
        const existingName = chats[targetIndex]?.name
        chats[targetIndex] = {
            ...chats[targetIndex], ...incomingChat,
            id: nextTarget.deliveryChatId,
            name: existingName,
            isStreaming: false,
            _placeholder: false,
        }
    } else {
        chats[targetIndex] = { ...chats[targetIndex], ...incomingChat }
    }
    nextTarget.expectedChatRevision = orchestrationChatRevision(chats[targetIndex])
    // Start-representation aliases are valid only before the first successful result application.
    nextTarget.acceptedChatRevisions = []
    return { target: nextTarget, targetIndex, conflictCreated }
}

import { describe, expect, test } from 'vitest'
import {
    createConflictChat,
    applyOrchestrationChatResult,
    orchestrationChatRevision,
    orchestrationLegacyChatRevision,
    orchestrationTargetHasConflict,
    resolveOrchestrationRecoveryTarget,
} from './bgOrchestrationMerge'

describe('orchestration conflict support', () => {
    test('cold-boot recovery waits for a placeholder target to hydrate', async () => {
        const chats: any[] = [{ id: 'chat-1', name: 'Main', message: [], _placeholder: true }]
        let releaseHydration!: () => void
        const hydrationGate = new Promise<void>((resolve) => { releaseHydration = resolve })
        const resolving = resolveOrchestrationRecoveryTarget(
            chats,
            'chat-1',
            'char-1',
            async (targetChats, index) => {
                await hydrationGate
                targetChats[index] = {
                    id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'hello' }],
                }
                return targetChats[index]
            },
        )

        let settled = false
        void resolving.then(() => { settled = true })
        await Promise.resolve()
        expect(settled).toBe(false)

        releaseHydration()
        await expect(resolving).resolves.toMatchObject({
            status: 'ready',
            index: 0,
            chat: { id: 'chat-1', message: [{ data: 'hello' }] },
        })
    })

    test('cold-boot recovery retries after hydration failure or an unresolved placeholder', async () => {
        const failed: any[] = [{ id: 'chat-1', message: [], _placeholder: true }]
        await expect(resolveOrchestrationRecoveryTarget(
            failed, 'chat-1', 'char-1', async () => null,
        )).resolves.toEqual({ status: 'retry', index: 0, chat: null })

        const rejected: any[] = [{ id: 'chat-1', message: [], _placeholder: true }]
        await expect(resolveOrchestrationRecoveryTarget(
            rejected, 'chat-1', 'char-1', async () => { throw new Error('storage unavailable') },
        )).resolves.toEqual({ status: 'retry', index: 0, chat: null })

        const unresolved: any[] = [{ id: 'chat-1', message: [], _placeholder: true }]
        await expect(resolveOrchestrationRecoveryTarget(
            unresolved, 'chat-1', 'char-1', async (_chats, index) => unresolved[index],
        )).resolves.toEqual({ status: 'retry', index: 0, chat: null })

        const malformed: any[] = [{ id: 'chat-1', name: 'Main' }]
        await expect(resolveOrchestrationRecoveryTarget(
            malformed, 'chat-1', 'char-1', async () => { throw new Error('must not hydrate') },
        )).resolves.toEqual({ status: 'retry', index: 0, chat: null })
    })

    test('cold-boot recovery keeps deleted and already hydrated targets distinct', async () => {
        const hydrate = async () => { throw new Error('must not hydrate') }
        await expect(resolveOrchestrationRecoveryTarget(
            [], 'missing-chat', 'char-1', hydrate,
        )).resolves.toEqual({ status: 'missing', index: -1, chat: null })

        const full: any[] = [{ id: 'chat-1', message: [{ role: 'user', data: 'hello' }] }]
        await expect(resolveOrchestrationRecoveryTarget(
            full, 'chat-1', 'char-1', hydrate,
        )).resolves.toMatchObject({ status: 'ready', index: 0, chat: full[0] })
    })

    test('cold-boot recovery treats deletion during hydration as a deleted target', async () => {
        const chats: any[] = [{ id: 'chat-1', message: [], _placeholder: true }]
        await expect(resolveOrchestrationRecoveryTarget(
            chats,
            'chat-1',
            'char-1',
            async () => {
                chats.splice(0, 1)
                return null
            },
        )).resolves.toEqual({ status: 'missing', index: -1, chat: null })
    })

    test('cold-boot recovery re-finds a target reordered during hydration', async () => {
        const chats: any[] = [{ id: 'chat-1', message: [], _placeholder: true }]
        await expect(resolveOrchestrationRecoveryTarget(
            chats,
            'chat-1',
            'char-1',
            async () => {
                chats[0] = { id: 'chat-1', message: [{ role: 'user', data: 'hello' }] }
                chats.unshift({ id: 'chat-2', message: [] })
                return chats[1]
            },
        )).resolves.toMatchObject({ status: 'ready', index: 1, chat: { id: 'chat-1' } })
    })

    test('equivalent serializable chats have the same compact revision', () => {
        const first = { id: 'chat-1', message: [{ role: 'user', data: 'hello' }], note: '' }
        const second = JSON.parse(JSON.stringify(first))
        expect(orchestrationChatRevision(second)).toBe(orchestrationChatRevision(first))
    })

    test('message edit, append, and deletion each change the revision', () => {
        const base = { id: 'chat-1', message: [{ role: 'user', data: 'hello' }], note: '' }
        expect(orchestrationChatRevision({ ...base, message: [{ role: 'user', data: 'edited' }] }))
            .not.toBe(orchestrationChatRevision(base))
        expect(orchestrationChatRevision({ ...base, message: [...base.message, { role: 'char', data: 'new' }] }))
            .not.toBe(orchestrationChatRevision(base))
        expect(orchestrationChatRevision({ ...base, message: [] })).not.toBe(orchestrationChatRevision(base))
    })

    test('save/hydration runtime fields do not look like a user edit', () => {
        const beforeSave = {
            id: 'chat-1', name: 'Main', note: '', localLore: [], isStreaming: true,
            message: [{
                role: 'user', data: 'same text', name: null, time: 123,
            }],
        }
        const afterColdBoot = {
            localLore: [], note: '', name: 'Main', id: 'chat-1', _placeholder: false,
            message: [{
                data: 'same text', role: 'user', name: null, chatId: 'engine-generated-id',
            }],
        }

        expect(orchestrationChatRevision(afterColdBoot)).toBe(orchestrationChatRevision(beforeSave))
    })

    test('semantic chat and message metadata edits still change the revision', () => {
        const base = {
            id: 'chat-1', name: 'Main', note: '', localLore: [],
            message: [{ role: 'user', data: 'same text', disabled: false }],
        }
        expect(orchestrationChatRevision({ ...base, note: 'edited note' }))
            .not.toBe(orchestrationChatRevision(base))
        expect(orchestrationChatRevision({
            ...base, message: [{ role: 'user', data: 'same text', disabled: true }],
        })).not.toBe(orchestrationChatRevision(base))
    })

    test('a pre-deploy full-object marker remains compatible for its unchanged graph', () => {
        const base = { id: 'chat-1', message: [{ role: 'user', data: 'hello', time: 123 }] }
        const target = { expectedChatRevision: orchestrationLegacyChatRevision(base) }
        expect(orchestrationTargetHasConflict(JSON.parse(JSON.stringify(base)), target)).toBe(false)
        expect(orchestrationTargetHasConflict({
            ...base, message: [{ role: 'user', data: 'edited', time: 123 }],
        }, target)).toBe(true)
    })

    test('an unchanged target can be replaced while an edited target must fork', () => {
        const base = { id: 'chat-1', message: [{ role: 'user', data: 'hello' }] }
        const target = { expectedChatRevision: orchestrationChatRevision(base) }
        expect(orchestrationTargetHasConflict(JSON.parse(JSON.stringify(base)), target)).toBe(false)
        expect(orchestrationTargetHasConflict({
            ...base, message: [{ role: 'user', data: 'local edit' }],
        }, target)).toBe(true)
    })

    test('one operation accepts its exact live and canonical start representations only', () => {
        const canonical = {
            id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'hello' }],
            normalizedByStorage: true,
        }
        const live = {
            id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'hello' }],
            normalizedByStorage: false,
        }
        const target = {
            expectedChatRevision: orchestrationChatRevision(canonical),
            acceptedChatRevisions: [orchestrationChatRevision(live)],
        }
        expect(orchestrationTargetHasConflict(live, target)).toBe(false)
        expect(orchestrationTargetHasConflict({
            ...live, message: [{ role: 'user', data: 'edited' }],
        }, target)).toBe(true)
    })

    test('a conflict branch preserves the incoming result under a fresh id without mutating it', () => {
        const incoming = { id: 'chat-1', name: 'Original', message: [{ role: 'char', data: 'answer' }] }
        const conflict = createConflictChat(incoming, 'chat-conflict')
        expect(conflict).toMatchObject({
            id: 'chat-conflict', name: 'Original · BG conflict',
            message: [{ role: 'char', data: 'answer' }], isStreaming: false, _placeholder: false,
        })
        expect(incoming).toEqual({
            id: 'chat-1', name: 'Original', message: [{ role: 'char', data: 'answer' }],
        })
    })

    test('unchanged target is replaced in place', () => {
        const chats: any[] = [{ id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'hi' }] }]
        const target = {
            deliveryChatId: 'chat-1', expectedChatRevision: orchestrationChatRevision(chats[0]), conflict: false,
        }
        const outcome = applyOrchestrationChatResult(chats, {
            id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'hi' }, { role: 'char', data: 'answer' }],
        }, target, () => 'conflict-1')
        expect(outcome.conflictCreated).toBe(false)
        expect(chats).toHaveLength(1)
        expect((chats[0].message as any[]).at(-1).data).toBe('answer')
    })

    test('local edit and original deletion each preserve the server result in a conflict chat', () => {
        const edited: any[] = [{ id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'edited' }] }]
        const target = {
            deliveryChatId: 'chat-1',
            expectedChatRevision: orchestrationChatRevision({
                id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'original' }],
            }),
            conflict: false,
        }
        const incoming = {
            id: 'chat-1', name: 'Main', message: [{ role: 'user', data: 'original' }, { role: 'char', data: 'answer' }],
        }
        const editedOutcome = applyOrchestrationChatResult(edited, incoming, target, () => 'conflict-edit')
        expect(edited[0].message[0].data).toBe('edited')
        expect(edited[1]).toMatchObject({ id: 'conflict-edit', name: 'Main · BG conflict' })
        expect(editedOutcome.conflictCreated).toBe(true)

