export interface GlobalVariableExpectation {
    present: boolean
    value?: unknown
}

export interface GlobalVariableConflict {
    key: string
    action: 'set' | 'delete'
    serverValue?: unknown
}

function own(object: object, key: string): boolean {
    return Object.prototype.hasOwnProperty.call(object, key)
}

function jsonDeepEqual(left: unknown, right: unknown): boolean {
    if (Object.is(left, right)) return true
    if (left === null || right === null || typeof left !== 'object' || typeof right !== 'object') return false
    if (Array.isArray(left) || Array.isArray(right)) {
        if (!Array.isArray(left) || !Array.isArray(right) || left.length !== right.length) return false
        return left.every((value, index) => jsonDeepEqual(value, right[index]))
    }
    const leftObject = left as Record<string, unknown>
    const rightObject = right as Record<string, unknown>
    const leftKeys = Object.keys(leftObject).sort()
    const rightKeys = Object.keys(rightObject).sort()
    if (leftKeys.length !== rightKeys.length) return false
    return leftKeys.every((key, index) => key === rightKeys[index]
        && jsonDeepEqual(leftObject[key], rightObject[key]))
}

function setOwn(object: Record<string, unknown>, key: string, value: unknown): void {
    Object.defineProperty(object, key, { value, enumerable: true, writable: true, configurable: true })
}

export function applyOrchestrationGlobalDelta(
    current: Record<string, unknown>,
    changedValue: unknown,
    deletedValue: unknown,
    expectedValue: unknown,
): { conflicts: GlobalVariableConflict[] } {
    const changed = changedValue && typeof changedValue === 'object' && !Array.isArray(changedValue)
        ? changedValue as Record<string, unknown> : {}
    const deleted = Array.isArray(deletedValue) ? deletedValue.filter((key): key is string => typeof key === 'string') : []
    const expected = expectedValue && typeof expectedValue === 'object' && !Array.isArray(expectedValue)
        ? expectedValue as Record<string, GlobalVariableExpectation> : null
    const conflicts: GlobalVariableConflict[] = []

    const canApply = (key: string): boolean => {
        // Rolling compatibility: an older server has no expectation map, preserving its original
        // unconditional behavior. New results are compare-and-apply per key.
        if (!expected || !own(expected, key)) return true
        const base = expected[key]
        if (!base || typeof base.present !== 'boolean') return false
        const present = own(current, key)
        return present === base.present && (!present || jsonDeepEqual(current[key], base.value))
    }

    for (const key of Object.keys(changed)) {
        // A strict durable-save retry sees the value this same result already applied in memory.
        // Treat that exact desired value as idempotent success instead of manufacturing a conflict.
        if (canApply(key) || (own(current, key) && jsonDeepEqual(current[key], changed[key]))) {
            setOwn(current, key, changed[key])
        }
        else conflicts.push({ key, action: 'set', serverValue: changed[key] })
    }
    for (const key of deleted) {
        // Likewise, an already-absent key is this delete's committed in-memory outcome.
        if (canApply(key) || !own(current, key)) delete current[key]
        else conflicts.push({ key, action: 'delete' })
    }
    return { conflicts }
}

export function recordOrchestrationGlobalConflicts(
    db: Record<string, unknown>,
    operationId: string | null,
    conflicts: GlobalVariableConflict[],
): void {
    if (!operationId || conflicts.length === 0) return
    const old = Array.isArray(db.bgOrchestrationGlobalConflicts)
        ? db.bgOrchestrationGlobalConflicts.filter((entry): entry is Record<string, unknown> => !!entry && typeof entry === 'object')
        : []
    const record = {
        operationId,
        time: Date.now(),
        conflicts: JSON.parse(JSON.stringify(conflicts)),
    }
    const withoutSameOperation = old.filter((entry) => entry.operationId !== operationId)
    db.bgOrchestrationGlobalConflicts = [...withoutSameOperation, record].slice(-20)
}

import { createRequire } from 'node:module'
import { describe, expect, test } from 'vitest'
import {
    applyOrchestrationGlobalDelta,
    recordOrchestrationGlobalConflicts,
} from './bgOrchestrationGlobals'

const require = createRequire(import.meta.url)
const { diffGlobalVariables } = require('../../server/node/bgOrchestrationGlobalVariables.cjs') as {
    diffGlobalVariables: (before: unknown, after: unknown) => {
        changed: Record<string, unknown>
        deleted: string[]
        expected: Record<string, { present: boolean, value?: unknown }>
    }
}

describe('orchestration global-variable round trip', () => {
    test('server diff includes exact expectations and ignores equal object values', () => {
        const diff = diffGlobalVariables(
            { keep: 'same', remove: 'old', nested: { b: 2, a: 1 } },
            { keep: 'same', add: 'new', nested: { a: 1, b: 2 } },
        )
        expect(diff.changed).toEqual({ add: 'new' })
        expect(diff.deleted).toEqual(['remove'])
        expect(diff.expected).toEqual({
            add: { present: false },
            remove: { present: true, value: 'old' },
        })
    })

    test('client applies keys whose baseline is unchanged', () => {
        const current: Record<string, unknown> = { change: 'old', remove: 'old' }
        const result = applyOrchestrationGlobalDelta(
            current,
            { change: 'server', add: 1 },
            ['remove'],
            {
                change: { present: true, value: 'old' },
                add: { present: false },
                remove: { present: true, value: 'old' },
            },
        )
        expect(result.conflicts).toEqual([])
        expect(current).toEqual({ change: 'server', add: 1 })
    })

    test('reapplying the same set/delete after a failed durable save is idempotent', () => {
        const current: Record<string, unknown> = { change: 'old', remove: 'old' }
        const expected = {
            change: { present: true, value: 'old' },
            remove: { present: true, value: 'old' },
        }
        expect(applyOrchestrationGlobalDelta(
            current, { change: 'server' }, ['remove'], expected,
        ).conflicts).toEqual([])
        expect(applyOrchestrationGlobalDelta(
            current, { change: 'server' }, ['remove'], expected,
        ).conflicts).toEqual([])
        expect(current).toEqual({ change: 'server' })
    })

    test('client preserves concurrent edits and records the server alternative', () => {
        const current: Record<string, unknown> = { change: 'local', remove: 'local' }
        const result = applyOrchestrationGlobalDelta(
            current,
            { change: 'server' },
            ['remove'],
            {
                change: { present: true, value: 'old' },
                remove: { present: true, value: 'old' },
            },
        )
        expect(current).toEqual({ change: 'local', remove: 'local' })
        expect(result.conflicts).toEqual([
            { key: 'change', action: 'set', serverValue: 'server' },
            { key: 'remove', action: 'delete' },
        ])
        const db: Record<string, unknown> = {}
        recordOrchestrationGlobalConflicts(db, 'operation-1', result.conflicts)
        recordOrchestrationGlobalConflicts(db, 'operation-1', [{ key: 'newer', action: 'delete' }])
        expect(db.bgOrchestrationGlobalConflicts).toEqual([expect.objectContaining({
            operationId: 'operation-1', conflicts: [{ key: 'newer', action: 'delete' }],
        })])
    })

    test('dangerous variable names stay own data properties instead of changing prototypes', () => {
        const current: Record<string, unknown> = {}
        const changed = JSON.parse('{"__proto__":{"polluted":true}}')
        const expected = JSON.parse('{"__proto__":{"present":false}}')
        const result = applyOrchestrationGlobalDelta(current, changed, [], expected)
        expect(result.conflicts).toEqual([])
        expect(Object.prototype.hasOwnProperty.call(current, '__proto__')).toBe(true)
        expect(({} as any).polluted).toBeUndefined()
    })
})

// A client fallback calls process.sendChat directly, outside DefaultChatScreen.sendChatMain.
// Keep its completion cleanup in one awaited lifecycle so both success and failure release
// process.doingChat instead of leaving the composer in a permanent busy state.
export async function runClientFallbackLifecycle(
    run: () => Promise<unknown>,
    cleanup: () => void,
    reportError: (error: unknown) => void,
    onSuccess?: () => void,
): Promise<void> {
    try {
        const result = await run()
        if (result !== false) onSuccess?.()
    } catch (error) {
        reportError(error)
    } finally {
        cleanup()
    }
}

import { describe, expect, test, vi } from 'vitest'
import { runClientFallbackLifecycle } from './bgOrchestrationFallback'

describe('client fallback lifecycle', () => {
    test('successful fallback always releases the busy state', async () => {
        const cleanup = vi.fn()
        const reportError = vi.fn()

        await runClientFallbackLifecycle(async () => true, cleanup, reportError)

        expect(cleanup).toHaveBeenCalledOnce()
        expect(reportError).not.toHaveBeenCalled()
    })

    test('rejected fallback reports the error and still releases the busy state', async () => {
        const failure = new Error('fallback failed')
        const cleanup = vi.fn()
        const reportError = vi.fn()

        await runClientFallbackLifecycle(async () => { throw failure }, cleanup, reportError)

        expect(reportError).toHaveBeenCalledOnce()
        expect(reportError).toHaveBeenCalledWith(failure)
        expect(cleanup).toHaveBeenCalledOnce()
    })

    test('completion callback runs only for a successful generation result', async () => {
        const completed = vi.fn()
        await runClientFallbackLifecycle(async () => true, () => {}, () => {}, completed)
        await runClientFallbackLifecycle(async () => false, () => {}, () => {}, completed)
        expect(completed).toHaveBeenCalledOnce()
    })
})

import { derived, readonly, writable, type Readable, type Writable } from 'svelte/store'

export interface GenerationBusyCoordinator {
    // Backward-compatible public store. Existing client-generation writers keep using set/update,
    // while every subscriber observes the union of client and server generation ownership.
    doingChat: Writable<boolean>
    orchestrating: Readable<boolean>
    setServerBusy: (active: boolean) => void
    handoffServerToClient: () => void
}

export function createGenerationBusyCoordinator(): GenerationBusyCoordinator {
    const clientBusy = writable(false)
    const serverBusy = writable(false)
    const combinedBusy = derived(
        [clientBusy, serverBusy],
        ([$clientBusy, $serverBusy]) => $clientBusy || $serverBusy,
    )

    const doingChat: Writable<boolean> = {
        subscribe: combinedBusy.subscribe,
        // Legacy writers own only the client-generation lease. In particular,
        // DefaultChatScreen's post-send set(false) must not release a detached server run.
        set: clientBusy.set,
        update: clientBusy.update,
    }

    return {
        doingChat,
        orchestrating: readonly(serverBusy),
        setServerBusy: (active) => serverBusy.set(active),
        // Fallback must not expose a false transition between releasing the server lease and
        // acquiring the client lease: Suggestion subscribes to false and would start an auxiliary
        // request against the pre-fallback chat. Acquire client first, then release server.
        handoffServerToClient: () => {
            clientBusy.set(true)
            serverBusy.set(false)
        },
    }
}

const generationBusy = createGenerationBusyCoordinator()

export const doingChat = generationBusy.doingChat
export const orchestrating = generationBusy.orchestrating
export const setServerGenerationBusy = generationBusy.setServerBusy
export const handoffServerGenerationToClient = generationBusy.handoffServerToClient

export function shouldBlockTopLevelGeneration(
    busy: boolean,
    chatProcessIndex: number,
    orchestrationFallback: boolean,
): boolean {
    return busy && chatProcessIndex === -1 && !orchestrationFallback
}

import { createRequire } from 'node:module'
import { PassThrough, Readable } from 'node:stream'
import { describe, expect, test, vi } from 'vitest'

const require = createRequire(import.meta.url)
const { consumeNodeReadable, pipelineProxyResponse, isExpectedProxyClientClose } = require('../../server/node/bgStreamReader.cjs') as {
    consumeNodeReadable: (
        readable: PassThrough,
        onChunk: (chunk: Buffer) => void,
        options?: { signal?: AbortSignal },
    ) => Promise<void>
    pipelineProxyResponse: (readable: Readable, response: PassThrough) => Promise<void>
    isExpectedProxyClientClose: (error: any, state: Record<string, boolean>) => boolean
}

describe('background Node stream reader', () => {
    test('delivers every chunk and resolves only on end', async () => {
        const stream = new PassThrough()
        const chunks: string[] = []
        const consumed = consumeNodeReadable(stream, (chunk) => chunks.push(chunk.toString()))
        stream.write('a')
        stream.end('b')
        await consumed
        expect(chunks.join('')).toBe('ab')
    })

    test('early close rejects once through the owned Promise without an unhandled error', async () => {
        const stream = new PassThrough()
        const consumed = consumeNodeReadable(stream, () => {})
        stream.destroy()
        await expect(consumed).rejects.toMatchObject({ code: 'ERR_STREAM_PREMATURE_CLOSE' })
    })

    test('abort destroys the reader and resolves as intentional cancellation', async () => {
        const stream = new PassThrough()
        const controller = new AbortController()
        const consumed = consumeNodeReadable(stream, vi.fn(), { signal: controller.signal })
        controller.abort()
        await expect(consumed).resolves.toBeUndefined()
        expect(stream.destroyed).toBe(true)
    })

    test('a chunk callback failure rejects through the owned Promise', async () => {
        const stream = new PassThrough()
        const consumed = consumeNodeReadable(stream, () => { throw new Error('consumer failed') })
        stream.write('a')
        await expect(consumed).rejects.toThrow('consumer failed')
        expect(stream.destroyed).toBe(true)
    })

    test('a downstream-first premature close is expected client-disconnect noise', async () => {
        const source = new PassThrough()
        const response = new PassThrough()
        const piped = pipelineProxyResponse(source, response)
        response.destroy()
        const error = await piped.catch((reason) => reason)
        expect(error).toMatchObject({
            code: 'ERR_STREAM_PREMATURE_CLOSE',
            proxyStreamFailureOrigin: 'downstream',
        })
        expect(isExpectedProxyClientClose(error, {})).toBe(true)
    })

    test('an upstream-first truncation remains a real error after pipeline destroys the response', async () => {
        const source = new PassThrough()
        const response = new PassThrough()
        const piped = pipelineProxyResponse(source, response)
        source.destroy()
        const error = await piped.catch((reason) => reason)
        expect(response.destroyed).toBe(true)
        expect(error).toMatchObject({
            code: 'ERR_STREAM_PREMATURE_CLOSE',
            proxyStreamFailureOrigin: 'upstream',
        })
        expect(isExpectedProxyClientClose(error, { requestAborted: false })).toBe(false)
        expect(isExpectedProxyClientClose(error, { requestAborted: true })).toBe(false)
        expect(isExpectedProxyClientClose({ code: 'ECONNRESET', proxyStreamFailureOrigin: 'downstream' }, {})).toBe(false)
    })
})

