export const GEMINI_CACHE_STATE_STORAGE_KEY = 'nodeOnlyGeminiCacheState'
export const GEMINI_CACHE_HISTORY_STORAGE_KEY = 'nodeOnlyGeminiCacheHistory'
export const GEMINI_CACHE_HISTORY_LIMIT = 200

export type GeminiCacheEventType =
    | 'miss' | 'invalidate' | 'explicit-hit' | 'implicit-hit'
    | 'create' | 'create-failed' | 'extend' | 'extend-failed'
    | 'cache-rejected' | 'session-disabled'

export interface GeminiCacheTelemetryEvent {
    id: string
    time: number
    type: GeminiCacheEventType
    cacheKey: string
    chatKey: string
    task: string
    presetId: string
    modelId: string
    cacheName?: string
    cacheTokenCount?: number
    requestPromptTokens?: number
    requestCachedTokens?: number
    expiresAt?: number
    reason?: string
    status?: number
}

let eventSequence = 0

function validEvent(value: unknown): value is GeminiCacheTelemetryEvent {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false
    const event = value as Record<string, unknown>
    return typeof event.id === 'string'
        && typeof event.time === 'number'
        && typeof event.type === 'string'
        && typeof event.cacheKey === 'string'
        && typeof event.chatKey === 'string'
        && typeof event.presetId === 'string'
        && typeof event.modelId === 'string'
}

export function readGeminiCacheTelemetry(): GeminiCacheTelemetryEvent[] {
    try {
        const raw = globalThis.localStorage?.getItem(GEMINI_CACHE_HISTORY_STORAGE_KEY)
        if (!raw) return []
        const parsed: unknown = JSON.parse(raw)
        return Array.isArray(parsed) ? parsed.filter(validEvent).slice(-GEMINI_CACHE_HISTORY_LIMIT) : []
    } catch {
        return []
    }
}

export function recordGeminiCacheEvent(
    event: Omit<GeminiCacheTelemetryEvent, 'id' | 'time'> & { time?: number },
): GeminiCacheTelemetryEvent {
    const time = event.time ?? Date.now()
    const record: GeminiCacheTelemetryEvent = {
        ...event,
        time,
        id: `${time.toString(36)}-${(++eventSequence).toString(36)}`,
    }
    try {
        const history = readGeminiCacheTelemetry()
        history.push(record)
        globalThis.localStorage?.setItem(
            GEMINI_CACHE_HISTORY_STORAGE_KEY,
            JSON.stringify(history.slice(-GEMINI_CACHE_HISTORY_LIMIT)),
        )
        mirrorActiveCacheTokenCount(record, history)
    } catch {
        // Telemetry must never affect a model request. The server route will simply show no record.
    }
    return record
}

function mirrorActiveCacheTokenCount(
    record: GeminiCacheTelemetryEvent,
    history: GeminiCacheTelemetryEvent[],
): void {
    const rawState = globalThis.localStorage?.getItem(GEMINI_CACHE_STATE_STORAGE_KEY)
    if (!rawState) return
    const state: unknown = JSON.parse(rawState)
    if (!state || typeof state !== 'object' || Array.isArray(state)) return
    const entry = (state as Record<string, unknown>)[record.cacheKey]
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) return
    const active = entry as Record<string, unknown>
    const create = [...history].reverse().find((event) => event.type === 'create'
        && event.cacheKey === record.cacheKey
        && (!event.cacheName || event.cacheName === active['cacheName']))
    const storedExact = Number.isFinite(active['cacheTokenCount'])
        ? active['cacheTokenCount']
        : undefined
    const exact = storedExact ?? create?.cacheTokenCount
    if (typeof exact !== 'number' || !Number.isFinite(exact)) return
    if (storedExact === exact) return
    active['cacheTokenCount'] = exact
    globalThis.localStorage?.setItem(GEMINI_CACHE_STATE_STORAGE_KEY, JSON.stringify(state))
}

export function resetGeminiCacheTelemetryRuntime(): void {
    eventSequence = 0
}

