export type OrchestrationStartAttempt = 'accepted' | 'rejected'
export type OrchestrationStartStatus = 'accepted' | 'missing'
export type OrchestrationStartResolution = 'accepted' | 'rejected' | 'abandoned'
export type OrchestrationStatusResponse = 'accepted' | 'missing' | 'legacy-unknown' | 'ambiguous'

export const ORCHESTRATION_BASE_SAVE_TIMEOUT_MS = 60_000

interface OrchestrationBaseSaveOptions {
    signal?: AbortSignal
    timeoutMs?: number
}

function baseSaveAbortError(): Error {
    const error = new Error('orchestration base save cancelled')
    error.name = 'AbortError'
    return error
}

// saveChatToServer encodes synchronously but awaits the network write. A local script or another
// PWA can mutate the same chat during that await, leaving the just-saved base one revision behind
// the object about to be delegated. Retry a bounded number of times until one save spans a stable
// semantic revision; perpetual mutation stops before provider work instead of weakening recovery.
export async function persistStableOrchestrationBase(
    readRevision: () => string,
    persistBase: () => Promise<void>,
    maxAttempts = 3,
): Promise<void> {
    let revision = readRevision()
    for (let attempt = 0; attempt < Math.max(1, maxAttempts); attempt++) {
        await persistBase()
        const current = readRevision()
        if (current === revision) return
        revision = current
    }
    throw new Error('orchestration base changed while saving; provider not started')
}

// A successful POST only proves the bytes were committed; it does not turn the browser's live
// proxy graph into the shape a cold boot will decode. Read the committed chat back through the
// same storage decoder/normalizer used by hydration and delegate that canonical object. A mutation
// during either the save or canonical read restarts the whole transaction so the provider never
// receives a base different from the one named by the pending marker.
export async function persistCanonicalOrchestrationBase<T>(
    readRevision: () => string,
    persistBase: () => Promise<void>,
    readPersistedBase: () => Promise<T>,
    maxAttempts = 3,
): Promise<T> {
    let revision = readRevision()
    for (let attempt = 0; attempt < Math.max(1, maxAttempts); attempt++) {
        await persistBase()
        let current = readRevision()
        if (current !== revision) {
            revision = current
            continue
        }
        const canonical = await readPersistedBase()
        current = readRevision()
        if (current === revision) return canonical
        revision = current
    }
    throw new Error('orchestration base changed while saving or reading; provider not started')
}

// The client message that defines the server request must exist durably before provider work can
// start. Keeping this ordering helper pure makes the no-save/no-start contract independently
// testable without loading the browser orchestration module.
export async function persistBeforeOrchestrationStart<P, T>(
    persistBase: () => Promise<P>,
    prepareDelegation: (persisted: P) => T,
    options: OrchestrationBaseSaveOptions = {},
): Promise<T> {
    const timeoutMs = Math.max(1, options.timeoutMs || ORCHESTRATION_BASE_SAVE_TIMEOUT_MS)
    const persisted = await new Promise<P>((resolve, reject) => {
        let settled = false
        let timer: ReturnType<typeof setTimeout> | null = null
        const finish = (complete: () => void) => {
            if (settled) return
            settled = true
            if (timer) clearTimeout(timer)
            if (options.signal) options.signal.removeEventListener('abort', onAbort)
            complete()
        }
        const onAbort = () => finish(() => reject(baseSaveAbortError()))
        if (options.signal?.aborted) { onAbort(); return }
        if (options.signal) options.signal.addEventListener('abort', onAbort, { once: true })
        timer = setTimeout(() => {
            finish(() => reject(new Error('orchestration base save timed out; provider not started')))
        }, timeoutMs)
        Promise.resolve().then(persistBase).then(
            (value) => finish(() => resolve(value)),
            (error) => finish(() => reject(error)),
        )
    })
    return prepareDelegation(persisted)
}

export function classifyOrchestrationStatusResponse(
    httpStatus: number,
    data: unknown,
    operationId: string,
): OrchestrationStatusResponse {
    const value = data as { accepted?: unknown, state?: unknown, operationId?: unknown } | null
    if (httpStatus >= 200 && httpStatus < 300
        && value?.accepted === true && value.operationId === operationId) return 'accepted'
    if (httpStatus === 404
        && value?.state === 'missing' && value.operationId === operationId) return 'missing'
    if (httpStatus === 404) return 'legacy-unknown'
    return 'ambiguous'
}

interface StartReconciliationOptions {
    start: (signal: AbortSignal) => Promise<OrchestrationStartAttempt>
    status: (signal: AbortSignal) => Promise<OrchestrationStartStatus>
    isCurrent: () => boolean
    deadlineAt: number
    now?: () => number
    wait?: (ms: number) => Promise<void>
    initialDelayMs?: number
    maxDelayMs?: number
    attemptTimeoutMs?: number
}

function withTimeout<T>(task: (signal: AbortSignal) => Promise<T>, timeoutMs: number): Promise<T> {
    return new Promise<T>((resolve, reject) => {
        const controller = new AbortController()
        const timer = setTimeout(() => {
            controller.abort()
            reject(new Error('orchestration start reconciliation timeout'))
        }, timeoutMs)
        let promise: Promise<T>
        try { promise = task(controller.signal) }
        catch (error) { clearTimeout(timer); reject(error); return }
        promise.then(
            (value) => { clearTimeout(timer); resolve(value) },
            (error) => { clearTimeout(timer); reject(error) },
        )
    })
}

// A failed POST response is ambiguous: the server may already be spending tokens. Never turn that
// ambiguity into a client fallback. Query the exact operation first; retry the same id only after
// the server definitively says it is missing. Server-side active/finished tombstones make that POST
// idempotent even when the original response was the only thing lost.
export async function reconcileOrchestrationStart(
    options: StartReconciliationOptions,
): Promise<OrchestrationStartResolution> {
    const now = options.now || Date.now
    const wait = options.wait || ((ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms)))
    let delayMs = Math.max(1, options.initialDelayMs || 1000)
    const maxDelayMs = Math.max(delayMs, options.maxDelayMs || 4000)
    const attemptTimeoutMs = Math.max(1, options.attemptTimeoutMs || 10000)
    let shouldStart = true

    while (options.isCurrent() && now() < options.deadlineAt) {
        if (shouldStart) {
            try {
                const outcome = await withTimeout(options.start, attemptTimeoutMs)
                return outcome === 'accepted' ? 'accepted' : 'rejected'
            } catch {
                shouldStart = false
            }
        } else {
            try {
                const outcome = await withTimeout(options.status, attemptTimeoutMs)
                if (outcome === 'accepted') return 'accepted'
                shouldStart = true
            } catch {
                // Network is still ambiguous. Keep status-checking; do not pay for a fallback.
            }
        }

        if (!options.isCurrent() || now() >= options.deadlineAt) break
        await wait(delayMs)
        delayMs = Math.min(maxDelayMs, delayMs + 500)
    }
    return 'abandoned'
}

