        expect(order).toEqual(['save', 'prepare'])
    })

    test('the exact persisted value is passed into delegation preparation', async () => {
        const canonical = { id: 'chat-1', source: 'server' }
        const prepared = await persistBeforeOrchestrationStart(
            async () => canonical,
            (persisted) => ({ ...persisted, prepared: true }),
        )
        expect(prepared).toEqual({ id: 'chat-1', source: 'server', prepared: true })
    })

    test('base save failure prevents delegation preparation', async () => {
        const prepare = vi.fn()
        await expect(persistBeforeOrchestrationStart(
            async () => { throw new Error('save failed') },
            prepare,
        )).rejects.toThrow('save failed')
        expect(prepare).not.toHaveBeenCalled()
    })

    test('a cancelled or timed-out base save never prepares delegation', async () => {
        const cancelledPrepare = vi.fn()
        const controller = new AbortController()
        const cancelled = persistBeforeOrchestrationStart(
            () => new Promise<void>(() => {}),
            cancelledPrepare,
            { signal: controller.signal, timeoutMs: 1_000 },
        )
        controller.abort()
        await expect(cancelled).rejects.toMatchObject({ name: 'AbortError' })
        expect(cancelledPrepare).not.toHaveBeenCalled()

        const timedOutPrepare = vi.fn()
        await expect(persistBeforeOrchestrationStart(
            () => new Promise<void>(() => {}),
            timedOutPrepare,
            { timeoutMs: 5 },
        )).rejects.toThrow('timed out')
        expect(timedOutPrepare).not.toHaveBeenCalled()
    })

    test('base save retries until the delegated revision was stable across a commit', async () => {
        let revision = 'one'
        let saves = 0
        await persistStableOrchestrationBase(
            () => revision,
            async () => {
                saves++
                if (saves === 1) revision = 'two'
            },
        )
        expect(saves).toBe(2)

        let changing = 0
        await expect(persistStableOrchestrationBase(
            () => String(changing),
            async () => { changing++ },
            2,
        )).rejects.toThrow('changed while saving')
    })

    test('delegation uses the canonical persisted chat and retries a mutation during its read', async () => {
        let revision = 'one'
        let saves = 0
        let reads = 0
        const canonical = await persistCanonicalOrchestrationBase(
            () => revision,
            async () => { saves++ },
            async () => {
                reads++
                if (reads === 1) revision = 'two'
                return { source: 'server', read: reads }
            },
        )
        expect(canonical).toEqual({ source: 'server', read: 2 })
        expect(saves).toBe(2)
        expect(reads).toBe(2)

        let changing = 0
        await expect(persistCanonicalOrchestrationBase(
            () => String(changing),
            async () => {},
            async () => { changing++; return { source: 'server' } },
            2,
        )).rejects.toThrow('changed while saving or reading')
    })

    test('only an exact M8 missing response permits a POST retry', () => {
        expect(classifyOrchestrationStatusResponse(404, {
            accepted: false, state: 'missing', operationId: 'op-1',
        }, 'op-1')).toBe('missing')
        expect(classifyOrchestrationStatusResponse(404, null, 'op-1')).toBe('legacy-unknown')
        expect(classifyOrchestrationStatusResponse(404, {
            accepted: false, state: 'missing', operationId: 'op-other',
        }, 'op-1')).toBe('legacy-unknown')
    })

    test('a lost POST response is accepted by exact operation status without fallback', async () => {
        const start = vi.fn(async () => { throw new Error('response lost') })
        const status = vi.fn(async () => 'accepted' as const)
        expect(await reconcileOrchestrationStart({
            start, status, isCurrent: () => true, deadlineAt: 10, now: () => 0, wait: noWait,
        })).toBe('accepted')
        expect(start).toHaveBeenCalledTimes(1)
        expect(status).toHaveBeenCalledTimes(1)
    })

    test('a permanently pending POST is timed out into status reconciliation', async () => {
        let timedOutSignal: AbortSignal | null = null
        const start = vi.fn((signal: AbortSignal) => {
            timedOutSignal = signal
            return new Promise<'accepted'>(() => {})
        })
        const status = vi.fn(async () => 'accepted' as const)
        expect(await reconcileOrchestrationStart({
            start, status, isCurrent: () => true, deadlineAt: 100,
            now: () => 0, wait: noWait, attemptTimeoutMs: 5,
        })).toBe('accepted')
        expect(status).toHaveBeenCalledTimes(1)
        expect(timedOutSignal?.aborted).toBe(true)
    })

    test('a definitively missing operation retries the same start id', async () => {
        let starts = 0
        const start = vi.fn(async () => {
            starts++
            if (starts === 1) throw new Error('request never arrived')
            return 'accepted' as const
        })
        const status = vi.fn(async () => 'missing' as const)
        expect(await reconcileOrchestrationStart({
            start, status, isCurrent: () => true, deadlineAt: 10, now: () => 0, wait: noWait,
        })).toBe('accepted')
        expect(start).toHaveBeenCalledTimes(2)
        expect(status).toHaveBeenCalledTimes(1)
    })

    test('an explicit server rejection is the only start outcome that permits fallback', async () => {
        const status = vi.fn(async () => 'accepted' as const)
        expect(await reconcileOrchestrationStart({
            start: async () => 'rejected', status, isCurrent: () => true,
            deadlineAt: 10, now: () => 0, wait: noWait,
        })).toBe('rejected')
        expect(status).not.toHaveBeenCalled()
    })

    test('persistent status ambiguity abandons when the watch is no longer current', async () => {
        let current = true
        const status = vi.fn(async () => {
            current = false
            throw new Error('offline')
        })
        expect(await reconcileOrchestrationStart({
            start: async () => { throw new Error('lost') },
            status,
            isCurrent: () => current,
            deadlineAt: 10,
            now: () => 0,
            wait: noWait,
        })).toBe('abandoned')
    })

    test('deadline ambiguity never becomes a rejected/fallback result', async () => {
        let now = 0
        expect(await reconcileOrchestrationStart({
            start: async () => { throw new Error('lost') },
            status: async () => { throw new Error('offline') },
            isCurrent: () => true,
            deadlineAt: 2,
            now: () => now,
            wait: async () => { now++ },
            initialDelayMs: 1,
        })).toBe('abandoned')
    })
})

