import { createRequire } from 'node:module'
import { describe, expect, test } from 'vitest'

const require = createRequire(import.meta.url)
const { createOrchestrationRunRegistry } = require('../../server/node/bgOrchestrationRunRegistry.cjs') as {
    createOrchestrationRunRegistry: (options?: Record<string, unknown>) => {
        start: (id: string, meta?: Record<string, unknown>) => { started: boolean, reason: string, run: any }
        cancel: (id: string) => { cancelled: boolean, reason: string, run: any }
        discard: (id: string, run: any) => boolean
        finish: (id: string, run: any, terminalState?: string) => boolean
        markDelivered: (id: string) => boolean
        nextPublishSequence: (id: string, run: any) => number | null
        get: (id: string) => any
        status: (id: string) => string
        size: () => number
    }
}

describe('server orchestration run registry', () => {
    test('cancel aborts the exact active operation and is idempotent', () => {
        const registry = createOrchestrationRunRegistry()
        const started = registry.start('operation-1', { charId: 'char-1', chatId: 'chat-1' })

        expect(started.started).toBe(true)
        expect(started.run.controller.signal.aborted).toBe(false)
        expect(registry.cancel('operation-1').reason).toBe('cancelled')
        expect(started.run.cancelled).toBe(true)
        expect(started.run.controller.signal.aborted).toBe(true)
        expect(registry.cancel('operation-1').reason).toBe('already-cancelled')
        expect(registry.size()).toBe(1)
    })

    test('an unknown operation is never reported as cancelled', () => {
        const registry = createOrchestrationRunRegistry()
        expect(registry.cancel('missing')).toMatchObject({ cancelled: false, reason: 'not-active' })
    })

    test('duplicate start reuses the active record instead of launching another run', () => {
        const registry = createOrchestrationRunRegistry()
        const first = registry.start('operation-1')
        const duplicate = registry.start('operation-1')

        expect(duplicate).toMatchObject({ started: false, reason: 'already-active' })
        expect(duplicate.run).toBe(first.run)
        expect(registry.size()).toBe(1)
    })

    test('caller metadata cannot override operation lifecycle invariants', () => {
        const registry = createOrchestrationRunRegistry()
        const started = registry.start('operation-1', {
            operationId: 'operation-other',
            state: 'finished',
            publishSeq: 99,
            cancelled: true,
            charId: 'char-1',
        })

        expect(started.run).toMatchObject({
            operationId: 'operation-1',
            state: 'running',
            publishSeq: 0,
            cancelled: false,
            charId: 'char-1',
        })
        expect(registry.status('operation-1')).toBe('running')
    })

    test('a finished tombstone prevents a response-loss retry from launching again', () => {
        const registry = createOrchestrationRunRegistry()
        const run = registry.start('operation-1').run
        expect(registry.finish('operation-1', run)).toBe(true)
        expect(registry.start('operation-1')).toMatchObject({
            started: false,
            reason: 'already-finished',
            run,
        })
        expect(registry.status('operation-1')).toBe('finished')
    })

    test('a pre-provider start can be discarded when durable acceptance fails', () => {
        const registry = createOrchestrationRunRegistry()
        const run = registry.start('operation-1').run
        expect(registry.discard('operation-1', run)).toBe(true)
        expect(registry.status('operation-1')).toBe('missing')
    })

    test('delivery failure and delivered are distinct terminal states', () => {
        const registry = createOrchestrationRunRegistry()
        const run = registry.start('operation-1').run
        expect(registry.finish('operation-1', run, 'delivery-failed')).toBe(true)
        expect(registry.status('operation-1')).toBe('delivery-failed')
        expect(registry.markDelivered('operation-1')).toBe(true)
        expect(registry.status('operation-1')).toBe('delivered')
    })

    test('terminal tombstones stay bounded under continuous completed operations', () => {
        const registry = createOrchestrationRunRegistry({ maxRetained: 2 })
        const first = registry.start('operation-1').run
        registry.finish('operation-1', first)
        const second = registry.start('operation-2').run
        registry.finish('operation-2', second)
        const third = registry.start('operation-3').run

        expect(registry.size()).toBe(2)
        expect(registry.get('operation-1')).toBeNull()
        expect(registry.get('operation-2')).not.toBeNull()
        expect(registry.get('operation-3')).toBe(third)
    })

    test('all-running capacity is a hard bound and rejects a new operation', () => {
        const registry = createOrchestrationRunRegistry({ maxRetained: 2 })
        registry.start('operation-1')
        registry.start('operation-2')

        expect(registry.start('operation-3')).toMatchObject({
            started: false,
            reason: 'capacity',
            run: null,
        })
        expect(registry.size()).toBe(2)
        expect(registry.get('operation-3')).toBeNull()
    })

    test('a duplicate terminal id is checked before capacity eviction', () => {
        const registry = createOrchestrationRunRegistry({ maxRetained: 2 })
        const first = registry.start('operation-1').run
        registry.finish('operation-1', first)
        registry.start('operation-2')

        expect(registry.start('operation-1')).toMatchObject({
            started: false,
            reason: 'already-finished',
            run: first,
        })
        expect(registry.size()).toBe(2)
    })

    test('an old finally cannot finish a newer record after tombstone expiry', () => {
        let now = 0
        const registry = createOrchestrationRunRegistry({ now: () => now, retainMs: 100 })
        const oldRun = registry.start('operation-1').run
        registry.finish('operation-1', oldRun)
        now = 101
        const newRun = registry.start('operation-1').run

        expect(registry.finish('operation-1', oldRun)).toBe(false)

        expect(registry.get('operation-1')).toBe(newRun)
        registry.finish('operation-1', newRun)
        expect(registry.status('operation-1')).toBe('finished')
    })

    test('publish sequence is monotonic and bound to the exact active run', () => {
        const registry = createOrchestrationRunRegistry()
        const oldRun = registry.start('operation-1').run

        expect(registry.nextPublishSequence('operation-1', oldRun)).toBe(1)
        expect(registry.nextPublishSequence('operation-1', oldRun)).toBe(2)
        registry.finish('operation-1', oldRun)
        const newRun = registry.start('operation-2').run

        expect(registry.nextPublishSequence('operation-1', oldRun)).toBeNull()
        expect(registry.nextPublishSequence('operation-2', newRun)).toBe(1)
    })
})

export type OrchestrationAckState = 'acked' | 'superseded' | 'unconfirmed' | 'legacy'

export const ORCHESTRATION_CHAT_DELIVERY_FIELD = 'bgOrchestrationDelivery'
export const ORCHESTRATION_ROOT_DELIVERY_FIELD = 'bgOrchestrationDeliveries'
export const MAX_DURABLE_ORCHESTRATION_DELIVERIES = 128

export interface DurableOrchestrationDelivery {
    operationId: string
    resultId: string
    publishSeq: number
    deliveryChatId: string
    expectedChatRevision: string
    conflict: boolean
}

interface OrderedDeliveryIdentity {
    operationId?: unknown
    resultId?: unknown
    publishSeq?: unknown
}

function deliveryIdentity(value: OrderedDeliveryIdentity | null | undefined): {
    operationId: string
    resultId: string
    publishSeq: number
} | null {
    if (typeof value?.operationId !== 'string' || !value.operationId) return null
    if (typeof value.resultId !== 'string' || !value.resultId) return null
    if (!Number.isSafeInteger(value.publishSeq) || (value.publishSeq as number) <= 0) return null
    return {
        operationId: value.operationId,
        resultId: value.resultId,
        publishSeq: value.publishSeq as number,
    }
}

function validDelivery(value: unknown): value is DurableOrchestrationDelivery {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false
    const entry = value as Record<string, unknown>
    return !!deliveryIdentity(entry)
        && typeof entry.deliveryChatId === 'string' && !!entry.deliveryChatId
        && typeof entry.expectedChatRevision === 'string'
        && typeof entry.conflict === 'boolean'
}

function rootDeliveries(db: Record<string, unknown>): DurableOrchestrationDelivery[] {
    const value = db[ORCHESTRATION_ROOT_DELIVERY_FIELD]
    return (Array.isArray(value) ? value : []).filter(validDelivery)
        .slice(-MAX_DURABLE_ORCHESTRATION_DELIVERIES)
}

export function findChatDelivery(
    chats: Array<Record<string, unknown>>,
    operationId: string,
    resultId?: string,
): DurableOrchestrationDelivery | null {
    let newest: DurableOrchestrationDelivery | null = null
    for (const chat of chats) {
        if (!chat || typeof chat !== 'object') continue
        const raw = chat[ORCHESTRATION_CHAT_DELIVERY_FIELD]
        if (!raw || typeof raw !== 'object' || Array.isArray(raw)) continue
        const marker = raw as Record<string, unknown>
        const candidate = {
            ...marker,
            deliveryChatId: typeof chat.id === 'string' ? chat.id : marker.deliveryChatId,
            conflict: marker.conflict === true,
        }
        if (!validDelivery(candidate) || candidate.operationId !== operationId) continue
        if (resultId && candidate.resultId !== resultId) continue
        if (!newest || candidate.publishSeq > newest.publishSeq) newest = candidate
    }
    return newest
}

export function markChatDelivery(
    chat: Record<string, unknown>,
    data: OrderedDeliveryIdentity,
    expectedChatRevision: string,
    conflict: boolean,
): DurableOrchestrationDelivery | null {
    const identity = deliveryIdentity(data)
    if (!identity || typeof chat.id !== 'string' || !chat.id) return null
    const record: DurableOrchestrationDelivery = {
        ...identity,
        deliveryChatId: chat.id,
        expectedChatRevision,
        conflict,
    }
    chat[ORCHESTRATION_CHAT_DELIVERY_FIELD] = { ...record }
    return record
}

export function readRootDelivery(
    db: Record<string, unknown>,
    operationId: string,
): DurableOrchestrationDelivery | null {
    return rootDeliveries(db).findLast((entry) => entry.operationId === operationId) ?? null
}

export function recordRootDelivery(
    db: Record<string, unknown>,
    delivery: DurableOrchestrationDelivery,
): void {
    const entries = rootDeliveries(db).filter((entry) => entry.operationId !== delivery.operationId)
    entries.push({ ...delivery })
    db[ORCHESTRATION_ROOT_DELIVERY_FIELD] = entries.slice(-MAX_DURABLE_ORCHESTRATION_DELIVERIES)
}

// Chat bodies are persisted before database.bin. Matching evidence in both places proves the
// cross-store durable save completed. Chat-only evidence means the first half committed and the
// next attempt must finish root/global/statics persistence without overwriting that chat.
export function readFullyCommittedDelivery(
    db: Record<string, unknown>,
    chats: Array<Record<string, unknown>>,
    operationId: string,
): DurableOrchestrationDelivery | null {
    const root = readRootDelivery(db, operationId)
    if (!root) return null
    const chat = findChatDelivery(chats, operationId, root.resultId)
    if (!chat || chat.publishSeq !== root.publishSeq || chat.deliveryChatId !== root.deliveryChatId) return null
    return root
}

export interface OrchestrationDeliveryOutcome {
    durable: boolean
    acknowledgement: OrchestrationAckState | 'not-attempted'
    error?: unknown
}

export function isConfirmedOrchestrationAcknowledgement(
    state: OrchestrationAckState | 'not-attempted',
): boolean {
    return state === 'acked' || state === 'legacy'
}

interface ResultRevision {
    resultId?: unknown
}

// Persistence is the commit point. The server result may only be ACKed after the merged DB state
// has durably saved. ACK failure does not undo that commit: an exact-revision retry is idempotent,
// and an unconfirmed terminal ACK may safely age out on the server without losing the saved reply.
export async function persistBeforeResultAck(
    data: ResultRevision | null | undefined,
    persist: () => Promise<void> | void,
    acknowledge: (resultId: string) => Promise<Exclude<OrchestrationAckState, 'legacy'>>,
): Promise<OrchestrationDeliveryOutcome> {
    try {
        await persist()
    } catch (error) {
        return { durable: false, acknowledgement: 'not-attempted', error }
    }

    const resultId = typeof data?.resultId === 'string' && data.resultId.length > 0
        ? data.resultId
        : null
    if (!resultId) return { durable: true, acknowledgement: 'legacy' }

    try {
        return { durable: true, acknowledgement: await acknowledge(resultId) }
    } catch (error) {
        return { durable: true, acknowledgement: 'unconfirmed', error }
    }
}

