    acknowledgeResult: (get: (key: string) => string | null, del: (key: string) => void, key: string, resultId: string) => any
    inheritDeliveryClaim: (get: (key: string) => string | null, key: string, record: Record<string, unknown>) => any
}

describe('cross-store orchestration delivery evidence', () => {
    const result = { operationId: 'operation-123', resultId: 'result-123', publishSeq: 2 }

    test('chat delivery metadata does not change the user-content revision', () => {
        const chat: Record<string, unknown> = { id: 'chat-1', message: [{ role: 'char', data: 'saved' }] }
        const before = orchestrationChatRevision(chat)
        expect(markChatDelivery(chat, result, before, false)).not.toBeNull()
        expect(orchestrationChatRevision(chat)).toBe(before)
    })

    test('chat-only evidence is partial until matching root evidence commits', () => {
        const chat: Record<string, unknown> = { id: 'chat-1', message: [] }
        const revision = orchestrationChatRevision(chat)
        const delivery = markChatDelivery(chat, result, revision, false)!
        const db: Record<string, unknown> = {}
        expect(findChatDelivery([chat], result.operationId, result.resultId)).toEqual(delivery)
        expect(readFullyCommittedDelivery(db, [chat], result.operationId)).toBeNull()
        recordRootDelivery(db, delivery)
        expect(readFullyCommittedDelivery(db, [chat], result.operationId)).toEqual(delivery)
    })

    test('deleted or mismatched chat evidence is not fully committed', () => {
        const chat: Record<string, unknown> = { id: 'chat-1', message: [] }
        const delivery = markChatDelivery(chat, result, orchestrationChatRevision(chat), false)!
        const db: Record<string, unknown> = {}
        recordRootDelivery(db, delivery)
        expect(readFullyCommittedDelivery(db, [], result.operationId)).toBeNull()
        const other: Record<string, unknown> = { id: 'chat-1', message: [] }
        markChatDelivery(
            other,
            { ...result, resultId: 'result-new', publishSeq: 3 },
            orchestrationChatRevision(other),
            false,
        )
        expect(readFullyCommittedDelivery(db, [other], result.operationId)).toBeNull()
    })
})

function routeHarness(
    record: Record<string, unknown>,
    options: {
        kvSet?: (key: string, value: string) => void
        kvDel?: (key: string) => void
        orchestrationRuns?: any
    } = {},
) {
    const routes = new Map<string, Function>()
    const values = new Map([['bg-orch-result:char-1::chat-1', JSON.stringify(record)]])
    const app = {
        post: (path: string, ...handlers: Function[]) => routes.set(`POST ${path}`, handlers.at(-1)!),
        get: (path: string, ...handlers: Function[]) => routes.set(`GET ${path}`, handlers.at(-1)!),
        delete: (path: string, ...handlers: Function[]) => routes.set(`DELETE ${path}`, handlers.at(-1)!),
    }
    registerBgOrchestrator(app, {
        sessionAuthMiddleware: (_req: unknown, _res: unknown, next: Function) => next(),
        kvGet: (key: string) => values.get(key) ?? null,
        kvSet: options.kvSet || ((key: string, value: string) => { values.set(key, value) }),
        kvDel: options.kvDel || ((key: string) => { values.delete(key) }),
        orchestrationRuns: options.orchestrationRuns,
    })
    return { routes, values }
}

function responseCapture() {
    const state: { status: number, body: any } = { status: 200, body: null }
    const res = {
        status(code: number) { state.status = code; return res },
        json(body: any) { state.body = body; return res },
    }
    return { state, res }
}

function memoryKv(initial?: Record<string, string>) {
    const values = new Map(Object.entries(initial || {}))
    return {
        values,
        get: (key: string) => values.get(key) ?? null,
        del: (key: string) => { values.delete(key) },
    }
}

describe('server orchestration result delivery', () => {
    test('a pre-M8 client is rejected before detached server work can start', async () => {
        const harness = routeHarness({})
