describe('client save-before-ACK sequencing', () => {
    test('only an exact ACK or rolling legacy consume is terminally confirmed', () => {
        expect(isConfirmedOrchestrationAcknowledgement('acked')).toBe(true)
        expect(isConfirmedOrchestrationAcknowledgement('legacy')).toBe(true)
        expect(isConfirmedOrchestrationAcknowledgement('superseded')).toBe(false)
        expect(isConfirmedOrchestrationAcknowledgement('unconfirmed')).toBe(false)
    })

    test('ACK starts only after durable persistence resolves', async () => {
        const order: string[] = []
        const outcome = await persistBeforeResultAck(
            { resultId: 'result-1' },
            async () => { order.push('save') },
            async () => { order.push('ack'); return 'acked' },
        )
        expect(order).toEqual(['save', 'ack'])
        expect(outcome).toEqual({ durable: true, acknowledgement: 'acked' })
    })

    test('save failure retains the server result by never ACKing', async () => {
        const ack = vi.fn(async () => 'acked' as const)
        const outcome = await persistBeforeResultAck(
            { resultId: 'result-1' },
            async () => { throw new Error('disk failed') },
            ack,
        )
        expect(outcome.durable).toBe(false)
        expect(outcome.acknowledgement).toBe('not-attempted')
        expect(ack).not.toHaveBeenCalled()
    })

    test('lost ACK response remains a durable, retryable delivery', async () => {
        const outcome = await persistBeforeResultAck(
            { resultId: 'result-1' },
            async () => {},
            async () => { throw new Error('network lost') },
        )
        expect(outcome.durable).toBe(true)
        expect(outcome.acknowledgement).toBe('unconfirmed')
    })

    test('an old server result is saved without attempting an unavailable ACK', async () => {
        const ack = vi.fn(async () => 'acked' as const)
        expect(await persistBeforeResultAck({}, async () => {}, ack)).toEqual({
            durable: true,
            acknowledgement: 'legacy',
        })
        expect(ack).not.toHaveBeenCalled()
    })
})

export interface AppliedOrchestrationRevision {
    publishSeq: number
    resultId: string
}

export type OrchestrationOrderDecision = 'apply' | 'legacy' | 'duplicate' | 'stale' | 'conflict'

export function createOrchestrationPollGate() {
    let activeEpoch: number | null = null
    return {
        tryEnter(epoch: number): boolean {
            if (activeEpoch === epoch) return false
            activeEpoch = epoch
            return true
        },
        leave(epoch: number): void {
            if (activeEpoch === epoch) activeEpoch = null
        },
    }
}

interface OrderedResult {
    operationId?: unknown
    publishSeq?: unknown
    resultId?: unknown
}

function orderedIdentity(data: OrderedResult | null | undefined): {
    operationId: string
    publishSeq: number
    resultId: string
} | null {
    if (typeof data?.operationId !== 'string' || data.operationId.length === 0) return null
    if (!Number.isSafeInteger(data.publishSeq) || (data.publishSeq as number) <= 0) return null
    if (typeof data.resultId !== 'string' || data.resultId.length === 0) return null
    return {
        operationId: data.operationId,
        publishSeq: data.publishSeq as number,
        resultId: data.resultId,
    }
}

// Sequence order is committed only after durable persistence succeeds. Until then the same
// revision remains retryable. A lower sequence can never replace a newer durable result, while an
// exact duplicate needs only another exact ACK attempt after a lost ACK response.
export function classifyOrchestrationResultOrder(
    data: OrderedResult | null | undefined,
    applied: Map<string, AppliedOrchestrationRevision>,
): OrchestrationOrderDecision {
    const incoming = orderedIdentity(data)
    if (!incoming) {
        // Absence is a rolling pre-M7 record. Presence with an invalid/incomplete ordered identity
        // is protocol corruption and must not silently regain legacy apply semantics.
        return data?.publishSeq === undefined ? 'legacy' : 'conflict'
    }
    const current = applied.get(incoming.operationId)
    if (!current || incoming.publishSeq > current.publishSeq) return 'apply'
    if (incoming.publishSeq < current.publishSeq) return 'stale'
    return incoming.resultId === current.resultId ? 'duplicate' : 'conflict'
}

export function commitOrchestrationResultOrder(
    data: OrderedResult | null | undefined,
    applied: Map<string, AppliedOrchestrationRevision>,
): boolean {
    const incoming = orderedIdentity(data)
    if (!incoming) return false
    const current = applied.get(incoming.operationId)
    if (current && incoming.publishSeq < current.publishSeq) return false
    if (current && incoming.publishSeq === current.publishSeq && incoming.resultId !== current.resultId) return false
    applied.set(incoming.operationId, {
        publishSeq: incoming.publishSeq,
        resultId: incoming.resultId,
    })
    return true
}

import { describe, expect, test } from 'vitest'
import {
    classifyOrchestrationResultOrder,
    commitOrchestrationResultOrder,
    createOrchestrationPollGate,
    type AppliedOrchestrationRevision,
} from './bgOrchestrationOrdering'

describe('orchestration result ordering', () => {
    test('single-flight blocks overlap in one epoch but not a new operation behind a hung old poll', () => {
        const gate = createOrchestrationPollGate()
        expect(gate.tryEnter(1)).toBe(true)
        expect(gate.tryEnter(1)).toBe(false)
        expect(gate.tryEnter(2)).toBe(true)
        gate.leave(1)
        expect(gate.tryEnter(2)).toBe(false)
        gate.leave(2)
        expect(gate.tryEnter(2)).toBe(true)
    })

    test('terminal-first delivery makes a delayed intermediate stale', () => {
        const applied = new Map<string, AppliedOrchestrationRevision>()
        const terminal = { operationId: 'op-1', publishSeq: 2, resultId: 'terminal-2' }
        const intermediate = { operationId: 'op-1', publishSeq: 1, resultId: 'intermediate-1' }

        expect(classifyOrchestrationResultOrder(terminal, applied)).toBe('apply')
        expect(commitOrchestrationResultOrder(terminal, applied)).toBe(true)
        expect(classifyOrchestrationResultOrder(intermediate, applied)).toBe('stale')
    })

    test('the same durable revision is an ACK-only duplicate', () => {
        const applied = new Map<string, AppliedOrchestrationRevision>()
        const result = { operationId: 'op-1', publishSeq: 1, resultId: 'result-1' }
        commitOrchestrationResultOrder(result, applied)
        expect(classifyOrchestrationResultOrder(result, applied)).toBe('duplicate')
    })

    test('equal sequence with a different revision is retained as a protocol conflict', () => {
        const applied = new Map<string, AppliedOrchestrationRevision>([
            ['op-1', { publishSeq: 1, resultId: 'result-1' }],
        ])
        expect(classifyOrchestrationResultOrder(
            { operationId: 'op-1', publishSeq: 1, resultId: 'result-other' },
            applied,
        )).toBe('conflict')
    })

    test('failed persistence stays retryable because order was not committed', () => {
        const applied = new Map<string, AppliedOrchestrationRevision>()
        const result = { operationId: 'op-1', publishSeq: 1, resultId: 'result-1' }
        expect(classifyOrchestrationResultOrder(result, applied)).toBe('apply')
        expect(classifyOrchestrationResultOrder(result, applied)).toBe('apply')
    })

    test('rolling records without a full ordered identity retain legacy behavior', () => {
        const applied = new Map<string, AppliedOrchestrationRevision>()
        expect(classifyOrchestrationResultOrder({ operationId: 'op-1', resultId: 'result-1' }, applied)).toBe('legacy')
        expect(classifyOrchestrationResultOrder({ resultId: 'result-1' }, applied)).toBe('legacy')
    })

    test('a present but malformed sequence cannot bypass ordering as legacy', () => {
        const applied = new Map<string, AppliedOrchestrationRevision>()
        expect(classifyOrchestrationResultOrder(
            { operationId: 'op-1', publishSeq: 0, resultId: 'result-1' },
            applied,
        )).toBe('conflict')
        expect(classifyOrchestrationResultOrder(
            { operationId: 'op-1', publishSeq: 1, resultId: '' },
            applied,
        )).toBe('conflict')
    })
})

import { isTerminalOrchestrationResult } from './bgOrchestrationResult'

interface OrchestrationStatsResult {
    operationId?: unknown
    staticsMessagesDelta?: unknown
    kind?: unknown
    final?: unknown
    error?: unknown
}

interface DurableStaticsLedger {
    bgOrchestrationApplied?: unknown
}

// Keep idempotency evidence for every operation the server can concurrently retain. The entries
// are tiny and only operations that changed the statics counter are recorded.
export const MAX_DURABLE_OPERATION_LEDGER = 128

function durableLedgerEntries(statics: DurableStaticsLedger): Array<{ operationId: string, cumulative: number }> {
    const value = statics.bgOrchestrationApplied
    const candidates = Array.isArray(value) ? value : (value && typeof value === 'object' ? [value] : [])
    return candidates.flatMap((entry) => {
        const candidate = entry as { operationId?: unknown, cumulative?: unknown }
        const cumulative = normalizedCumulativeDelta(candidate.cumulative)
        return typeof candidate.operationId === 'string' && candidate.operationId && cumulative > 0
            ? [{ operationId: candidate.operationId, cumulative }]
            : []
    }).slice(-MAX_DURABLE_OPERATION_LEDGER)
}

function normalizedCumulativeDelta(value: unknown): number {
    if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return 0
    return Math.floor(value)
}

// Server publishes a cumulative delta from the operation's delegation baseline in both the
// intermediate and terminal records. Return only the not-yet-applied suffix for that operation:
//   intermediate=1, terminal=1 -> 1 then 0
//   intermediate=1, terminal=2 -> 1 then 1
// A final that arrives before an older intermediate is also safe because cumulative values only
// advance. The caller owns the map so a cold-boot marker can seed it before polling resumes.
export function takeUnappliedMessagesDelta(
    data: OrchestrationStatsResult | null | undefined,
    appliedByOperation: Map<string, number>,
): number {
    if (!data) return 0
    const cumulative = normalizedCumulativeDelta(data.staticsMessagesDelta)
    if (cumulative === 0) return 0

    const operationId = typeof data.operationId === 'string' && data.operationId.length > 0
        ? data.operationId
        : null

    // Rolling compatibility with a pre-M5 server: defer its cumulative intermediate delta and
    // apply the terminal cumulative value once. The old endpoint is destructive, so that terminal
    // cannot be consumed twice by the same client.
    if (!operationId) return isTerminalOrchestrationResult(data) ? cumulative : 0

    const previous = appliedByOperation.get(operationId) || 0
    if (cumulative <= previous) return 0
    appliedByOperation.set(operationId, cumulative)
    return cumulative - previous
}

export function seedAppliedMessagesDelta(
    appliedByOperation: Map<string, number>,
    operationId: string | null | undefined,
    cumulative: unknown,
): void {
    if (!operationId) return
    const normalized = normalizedCumulativeDelta(cumulative)
    if (normalized > (appliedByOperation.get(operationId) || 0)) {
        appliedByOperation.set(operationId, normalized)
    }
}

export function recordAppliedMessagesDelta(
    statics: DurableStaticsLedger | null | undefined,
    operationId: string | null | undefined,
    cumulative: unknown,
): void {
    if (!statics || !operationId) return
    const normalized = normalizedCumulativeDelta(cumulative)
    if (normalized <= 0) return
    const entries = durableLedgerEntries(statics).filter((entry) => entry.operationId !== operationId)
    entries.push({ operationId, cumulative: normalized })
    statics.bgOrchestrationApplied = entries.slice(-MAX_DURABLE_OPERATION_LEDGER)
}

// The counter increment and this ledger are written in the same Risu DB save. If the page dies
// after that save but before HTTP ACK/localStorage cleanup, cold boot can prove the cumulative
// delta was already committed and safely redeliver the chat without incrementing it again.
export function seedAppliedMessagesDeltaFromStatics(
    appliedByOperation: Map<string, number>,
    statics: DurableStaticsLedger | null | undefined,
    operationId: string | null | undefined,
): void {
    if (!statics || !operationId) return
    const ledger = durableLedgerEntries(statics).find((entry) => entry.operationId === operationId)
    if (!ledger) return
    seedAppliedMessagesDelta(appliedByOperation, operationId, ledger.cumulative)
}

import { describe, expect, test } from 'vitest'
import {
    MAX_DURABLE_OPERATION_LEDGER,
    recordAppliedMessagesDelta,
    seedAppliedMessagesDelta,
    seedAppliedMessagesDeltaFromStatics,
    takeUnappliedMessagesDelta,
} from './bgOrchestrationStats'

describe('orchestration message statistics', () => {
    test('equal intermediate and terminal cumulative deltas apply once', () => {
        const applied = new Map<string, number>()
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'intermediate', staticsMessagesDelta: 1 }, applied)).toBe(1)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: 1 }, applied)).toBe(0)
    })

    test('a larger terminal cumulative delta applies only its suffix', () => {
        const applied = new Map<string, number>()
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'intermediate', staticsMessagesDelta: 1 }, applied)).toBe(1)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: 3 }, applied)).toBe(2)
    })

    test('final before stale intermediate never rolls the counter back or double-adds', () => {
        const applied = new Map<string, number>()
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: 2 }, applied)).toBe(2)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'intermediate', staticsMessagesDelta: 1 }, applied)).toBe(0)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: 2 }, applied)).toBe(0)
    })

    test('cold-boot seed preserves the already applied cumulative amount', () => {
        const applied = new Map<string, number>()
        seedAppliedMessagesDelta(applied, 'op-1', 1)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: 2 }, applied)).toBe(1)
    })

    test('the durable DB ledger seeds cold boot atomically with the saved counter', () => {
        const statics: any = { messages: 12 }
        recordAppliedMessagesDelta(statics, 'op-1', 2)
        const applied = new Map<string, number>()
        seedAppliedMessagesDeltaFromStatics(applied, statics, 'op-1')

        expect(statics.bgOrchestrationApplied).toEqual([{ operationId: 'op-1', cumulative: 2 }])
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: 2 }, applied)).toBe(0)
    })

    test('a DB ledger from another operation cannot suppress the current delta', () => {
        const applied = new Map<string, number>()
        seedAppliedMessagesDeltaFromStatics(applied, {
            bgOrchestrationApplied: { operationId: 'op-old', cumulative: 9 },
        }, 'op-new')
        expect(takeUnappliedMessagesDelta({ operationId: 'op-new', kind: 'terminal-success', staticsMessagesDelta: 1 }, applied)).toBe(1)
    })

    test('different operations remain independent', () => {
        const applied = new Map<string, number>()
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'intermediate', staticsMessagesDelta: 1 }, applied)).toBe(1)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-2', kind: 'terminal-success', staticsMessagesDelta: 1 }, applied)).toBe(1)
    })

    test('the durable ledger retains multiple operations and stays bounded', () => {
        const statics: any = {}
        for (let i = 0; i < MAX_DURABLE_OPERATION_LEDGER + 2; i++) {
            recordAppliedMessagesDelta(statics, `op-${i}`, i + 1)
        }
        expect(statics.bgOrchestrationApplied).toHaveLength(MAX_DURABLE_OPERATION_LEDGER)
        expect(statics.bgOrchestrationApplied[0]).toEqual({ operationId: 'op-2', cumulative: 3 })
        const applied = new Map<string, number>()
        const lastOperation = `op-${MAX_DURABLE_OPERATION_LEDGER + 1}`
        seedAppliedMessagesDeltaFromStatics(applied, statics, lastOperation)
        expect(applied.get(lastOperation)).toBe(MAX_DURABLE_OPERATION_LEDGER + 2)
    })

    test('recording one operation preserves and upgrades the legacy single-entry schema', () => {
        const statics: any = { bgOrchestrationApplied: { operationId: 'op-old', cumulative: 4 } }
        recordAppliedMessagesDelta(statics, 'op-new', 1)
        expect(statics.bgOrchestrationApplied).toEqual([
            { operationId: 'op-old', cumulative: 4 },
            { operationId: 'op-new', cumulative: 1 },
        ])
    })

    test('legacy intermediate defers and legacy terminal applies the cumulative value once', () => {
        const applied = new Map<string, number>()
        expect(takeUnappliedMessagesDelta({ kind: 'intermediate', final: false, staticsMessagesDelta: 2 }, applied)).toBe(0)
        expect(takeUnappliedMessagesDelta({ kind: 'terminal-success', final: true, staticsMessagesDelta: 2 }, applied)).toBe(2)
    })

    test('invalid and non-positive deltas are ignored', () => {
        const applied = new Map<string, number>()
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: -1 }, applied)).toBe(0)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: Number.NaN }, applied)).toBe(0)
        expect(takeUnappliedMessagesDelta({ operationId: 'op-1', kind: 'terminal-success', staticsMessagesDelta: '1' }, applied)).toBe(0)
    })
})

export type OrchestrationResultKind =
    | 'intermediate'
    | 'terminal-success'
    | 'terminal-partial'
    | 'terminal-error'

interface OrchestrationResultState {
    kind?: unknown
    final?: unknown
    error?: unknown
}

const TERMINAL_KINDS = new Set<OrchestrationResultKind>([
    'terminal-success',
    'terminal-partial',
    'terminal-error',
])

// `kind` is the durable protocol. The final/error fallback keeps rolling upgrades safe:
// a newly built client can consume the old server's `final:false + error` post-failure
// record as terminal instead of polling it for 15 minutes until the watch deadline.
export function isTerminalOrchestrationResult(data: OrchestrationResultState | null | undefined): boolean {
    if (!data) return false
    if (data.kind === 'intermediate') return false
    if (TERMINAL_KINDS.has(data.kind as OrchestrationResultKind)) return true
    return data.final === true || (typeof data.error === 'string' && data.error.length > 0)
}

export function isPartialOrchestrationResult(data: OrchestrationResultState | null | undefined): boolean {
    if (!data) return false
    return data.kind === 'terminal-partial'
        || (data.kind == null && typeof data.error === 'string' && data.error.length > 0)
}

import { describe, expect, test } from 'vitest'
