describe('orchestration result lifecycle', () => {
    test.each(['terminal-success', 'terminal-partial', 'terminal-error'])('%s is terminal', (kind) => {
        expect(isTerminalOrchestrationResult({ kind })).toBe(true)
    })

    test('an intermediate main snapshot keeps polling', () => {
        expect(isTerminalOrchestrationResult({ kind: 'intermediate', final: false })).toBe(false)
    })

    test('legacy final success is terminal', () => {
