const MAX_ASSET_UPLOAD_ATTEMPTS = 3
const ASSET_UPLOAD_RETRY_DELAYS_MS = [300, 900] as const

class RetryLane {
    private available: number
    private waiting: Array<() => void> = []

    constructor(private readonly max: number) {
        this.available = max
    }

    async acquire(): Promise<void> {
        if (this.available > 0) {
            this.available -= 1
            return
        }
        await new Promise<void>((resolve) => this.waiting.push(resolve))
    }

    release(): void {
        const next = this.waiting.shift()
        if (next) {
            next()
            return
        }
        if (this.available < this.max) this.available += 1
    }
}

function sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms))
}

// Normal uploads keep their existing caller-controlled concurrency. Only requests that already
// failed enter this narrower lane, preventing an iOS connection reset from immediately replaying
// the whole failed wave at once.
const assetUploadRetryLane = new RetryLane(3)

function retryableStatus(status: number): boolean {
    return status === 408 || status === 425 || status === 429 || status >= 500
}

function errorMessage(error: unknown): string {
    return error instanceof Error ? error.message : String(error)
}

export async function retryAssetUpload(
    upload: () => Promise<Response>,
    wait: (ms: number) => Promise<void> = sleep,
): Promise<Response> {
    let lastNetworkError: unknown = null

    try {
        const response = await upload()
        if (!retryableStatus(response.status)) return response
    } catch (error) {
        lastNetworkError = error
    }

    await assetUploadRetryLane.acquire()
    try {
        for (let attempt = 2; attempt <= MAX_ASSET_UPLOAD_ATTEMPTS; attempt += 1) {
            await wait(ASSET_UPLOAD_RETRY_DELAYS_MS[attempt - 2])
            try {
                const response = await upload()
                lastNetworkError = null
                if (!retryableStatus(response.status) || attempt === MAX_ASSET_UPLOAD_ATTEMPTS) {
                    return response
                }
            } catch (error) {
                lastNetworkError = error
                if (attempt === MAX_ASSET_UPLOAD_ATTEMPTS) {
                    throw new Error(
                        `Asset upload failed after ${MAX_ASSET_UPLOAD_ATTEMPTS} attempts: ${errorMessage(error)}`,
                        { cause: error },
                    )
                }
            }
        }
    } finally {
        assetUploadRetryLane.release()
    }

    throw new Error(
        `Asset upload failed after ${MAX_ASSET_UPLOAD_ATTEMPTS} attempts: ${errorMessage(lastNetworkError)}`,
        { cause: lastNetworkError },
    )
}

import { describe, expect, it, vi } from 'vitest'
import { retryAssetUpload } from './assetUploadRetry'

describe('retryAssetUpload', () => {
    it('keeps the fast path at one attempt with no delay', async () => {
        const response = new Response(null, { status: 200 })
        const upload = vi.fn().mockResolvedValue(response)
        const wait = vi.fn().mockResolvedValue(undefined)

        await expect(retryAssetUpload(upload, wait)).resolves.toBe(response)
        expect(upload).toHaveBeenCalledTimes(1)
        expect(wait).not.toHaveBeenCalled()
    })

    it('retries a transient network failure and succeeds', async () => {
        const response = new Response(null, { status: 200 })
        const upload = vi.fn()
            .mockRejectedValueOnce(new TypeError('Load failed'))
            .mockResolvedValueOnce(response)
        const wait = vi.fn().mockResolvedValue(undefined)

        await expect(retryAssetUpload(upload, wait)).resolves.toBe(response)
        expect(upload).toHaveBeenCalledTimes(2)
        expect(wait).toHaveBeenCalledWith(300)
    })

    it('retries transient HTTP responses but not a deactivated session', async () => {
        const retryable = vi.fn()
            .mockResolvedValueOnce(new Response(null, { status: 502 }))
            .mockResolvedValueOnce(new Response(null, { status: 200 }))
        const wait = vi.fn().mockResolvedValue(undefined)

        await expect(retryAssetUpload(retryable, wait)).resolves.toMatchObject({ status: 200 })
        expect(wait).toHaveBeenCalledWith(300)

        const locked = new Response(null, { status: 423 })
        const rejected = vi.fn().mockResolvedValue(locked)
        await expect(retryAssetUpload(rejected, wait)).resolves.toBe(locked)
        expect(rejected).toHaveBeenCalledTimes(1)
    })

    it('reports the final network cause after bounded retries', async () => {
        const upload = vi.fn().mockRejectedValue(new TypeError('Load failed'))
        const wait = vi.fn().mockResolvedValue(undefined)

        await expect(retryAssetUpload(upload, wait)).rejects.toThrow(
            'Asset upload failed after 3 attempts: Load failed',
        )
        expect(upload).toHaveBeenCalledTimes(3)
        expect(wait.mock.calls).toEqual([[300], [900]])
    })

    it('keeps all first attempts concurrent but caps only the retry lane at three', async () => {
        let firstAttempts = 0
        let activeRetries = 0
        let maxActiveRetries = 0
        let releaseRetries!: () => void
        const retryBlocker = new Promise<void>((resolve) => { releaseRetries = resolve })

        const uploads = Array.from({ length: 8 }, () => {
            let attempt = 0
            return retryAssetUpload(async () => {
                attempt += 1
                if (attempt === 1) {
                    firstAttempts += 1
                    throw new TypeError('Load failed')
                }
                activeRetries += 1
                maxActiveRetries = Math.max(maxActiveRetries, activeRetries)
                await retryBlocker
                activeRetries -= 1
                return new Response(null, { status: 200 })
            }, async () => {})
        })

        await vi.waitFor(() => {
            expect(firstAttempts).toBe(8)
            expect(activeRetries).toBe(3)
        })

        const fastResponse = new Response(null, { status: 200 })
        await expect(retryAssetUpload(
            vi.fn().mockResolvedValue(fastResponse),
            async () => {},
        )).resolves.toBe(fastResponse)

        releaseRetries()
        await Promise.all(uploads)

        expect(maxActiveRetries).toBe(3)
    })
})

'use strict'

const { consumeNodeReadable } = require('./bgStreamReader.cjs')

// BG-PRESERVE (Stage B) — external-API gemini job (stream OR non-stream).
//
// The server keeps receiving the gemini response even after a mobile client
// backgrounds/disconnects, then persists the body text so the client can recover it.
//
// Handles BOTH shapes:
//   - SSE stream (streamGenerateContent?alt=sse): "data: {json}\n" lines
//   - non-stream (generateContent): a single JSON body
// cache keeper's provider currently uses the non-stream form, which is why the user
// sees a spinner (no streaming text) and the answer is lost on background.
//
// Reuses server.cjs proxy-stream-job infra (job Map + WS replay) via injected deps,
// and persists to the shared `bg-stream-draft:` kv used by the client capture +
// bgDraftRoutes + BgRestoreBanner. Only body text is preserved (thoughts/tools dropped).

function shouldPersistSubResult(job, consumedIds) {
    return !!job && !job.bgCancelledByClient
        && !job.bgResultConsumed && !(consumedIds && consumedIds.has(job.id))
}

function captureBoundedRaw(job, value, maxBytes) {
    if (!job || !value || !Number.isFinite(maxBytes) || maxBytes <= 0) return 0
    if (!Array.isArray(job.bgRaw)) job.bgRaw = []
    const chunk = Buffer.from(value)
    const used = Number.isFinite(job.bgRawBytes) ? job.bgRawBytes : 0
    const remaining = Math.max(0, maxBytes - used)
    if (chunk.length > remaining) job.bgRawOverflow = true
    if (remaining === 0) return 0
    const captured = chunk.length <= remaining ? chunk : Buffer.from(chunk.subarray(0, remaining))
    job.bgRaw.push(captured)
    job.bgRawBytes = used + captured.length
    return captured.length
}

function rememberConsumedResult(consumedIds, jobId, now = Date.now()) {
    if (!consumedIds || !jobId) return
    consumedIds.delete(jobId)
    consumedIds.set(jobId, now)
    while (consumedIds.size > 512) {
        const oldest = consumedIds.keys().next().value
        if (oldest === undefined) break
        consumedIds.delete(oldest)
    }
}

function clearCancelledRecoveryArtifacts(job, deps) {
    if (!job || !deps || typeof deps.kvDel !== 'function') return
    const { kvGet, kvDel, draftKey, subResultKey, consumedSubResults } = deps
    if (consumedSubResults && job.id) rememberConsumedResult(consumedSubResults, job.id)
    if (job.id) {
        try { kvDel(subResultKey(job.id)) } catch { /* bounded TTL fallback */ }
    }
    const meta = job.bgMeta
    if (!meta?.charId || !meta?.chatId || !meta?.generationId || typeof kvGet !== 'function') return
    const key = draftKey(meta.charId, meta.chatId)
    try {
        const raw = kvGet(key)
        const record = raw ? JSON.parse(raw) : null
        // Draft slots are chat-scoped, so only remove the exact cancelled generation. A newer tab/run
        // may already have replaced this slot and must remain untouched.
        if (record && record.generationId === String(meta.generationId)) kvDel(key)
    } catch { /* invalid/missing draft or transient KV failure: TTL/manual recovery remains safe */ }
}

function registerBgStreamJob(app, deps) {
    const {
        proxyStreamJobs, createProxyStreamJob, pushJobEvent, markJobDone,
        requestLocalTargetStream, sessionAuthMiddleware, kvSet, kvGet, kvDel, kvList, kvGetUpdatedAt,
    } = deps || {}
    if (!app || !proxyStreamJobs || !createProxyStreamJob || !pushJobEvent || !markJobDone
        || !requestLocalTargetStream || !sessionAuthMiddleware || !kvSet || !kvGet || !kvDel) {
        console.error('[bg-preserve-job] registerBgStreamJob: missing dependencies, skipping')
        return
    }

    const DRAFT_PREFIX = 'bg-stream-draft:' // shared with bgDraftRoutes / client capture
    const MAX_ACCUM_BYTES = 12 * 1024 * 1024
    const draftKey = (charId, chatId) => DRAFT_PREFIX + String(charId) + '::' + String(chatId)

    // BG-PRESERVE 2a step-3: sub-model (FOLD/hypa) raw-response kv fallback.
    // A done sub job is GC'd 30s after completion (PROXY_STREAM_DONE_GRACE_MS, server.cjs); a long
    // background (>30s) makes the reconnect land on a gone job → without this the sub await rejects
    // ("Load failed") and the whole generation dies (the index-39 re-emergence). We persist the
    // sub's RAW response here so the client can rebuild the Response and continue WITHOUT re-calling
    // the model (no API cost). One-shot consume on read + a periodic TTL purge bound kv growth.
    const SUB_RESULT_PREFIX = 'bg-sub-result:'
    const SUB_RESULT_TTL_MS = 30 * 60 * 1000
    const subResultKey = (jobId) => SUB_RESULT_PREFIX + String(jobId)
    // ACK can arrive after a done/error WebSocket has closed and the shared job registry already
    // dropped that job object, but before this module's setImmediate persistence runs. Retain the
    // exact ACK independently until persist observes it; late ACKs expire with the result TTL.
    const consumedSubResults = new Map()

    const recoveryIdentity = (job) => ({
        charId: job?.bgMeta?.charId ? String(job.bgMeta.charId) : undefined,
        chatId: job?.bgMeta?.chatId ? String(job.bgMeta.chatId) : undefined,
        generationId: job?.bgMeta?.generationId ? String(job.bgMeta.generationId) : undefined,
    })

    // The shared host DELETE route can outlive the 30-second in-memory job grace. Retain recovery
    // identity inside the exact raw KV record and expose an ID-only cleanup callback on the shared
    // job registry, so a late explicit cancel still removes both raw and matching chat draft.
    proxyStreamJobs.bgCancelCleanupById = (jobId) => {
        if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(jobId || ''))) return
        let meta = null
        try {
            const raw = kvGet(subResultKey(jobId))
            const parsed = raw ? JSON.parse(raw) : null
            if (parsed && typeof parsed === 'object') {
                meta = {
                    charId: parsed.charId,
                    chatId: parsed.chatId,
                    generationId: parsed.generationId,
                }
            }
        } catch { /* exact raw deletion below is still useful */ }
        clearCancelledRecoveryArtifacts({ id: jobId, bgMeta: meta }, {
            kvGet, kvDel, draftKey, subResultKey, consumedSubResults,
        })
    }

    // SSRF guard (T1-b). This route intentionally drops the proxy-stream-job host allowlist so it can
    // reach external gemini AND user custom/reverse-proxy endpoints AND self-hosted local LLMs — all
    // legitimate, so we do NOT host-restrict (that would break them). We block only the one SSRF target
    // with catastrophic blast radius: the cloud metadata endpoint (169.254.0.0/16; Oracle/AWS/GCP serve
    // instance credentials there). new URL() normalizes integer/hex IPv4 forms → the dotted check holds.
    function isMetadataHost(hostname) {
        const h = String(hostname || '').toLowerCase().replace(/\.$/, '')
        return /^169\.254\./.test(h) || h === 'metadata.google.internal' || h === 'metadata'
    }

    function partsText(parts) {
        let t = ''
        if (Array.isArray(parts)) {
            for (const p of parts) {
                if (p && typeof p.text === 'string' && !p.thought) t += p.text
            }
        }
        return t
    }

    // Extract gemini body text from the full raw response — SSE lines or a single JSON.
    function extractGeminiText(buf) {
        let full = ''
        try { full = Buffer.concat(buf).toString('utf8') } catch { return '' }
        if (!full) return ''
        // SSE form: one or more "data: {...}" lines
        if (/(^|\n)\s*data:/.test(full)) {
            let text = ''
            for (const line of full.split('\n')) {
                const s = line.trim()
                if (!s.startsWith('data:')) continue
                const d = s.slice(5).trim()
                if (!d || d === '[DONE]') continue
                try { text += partsText(JSON.parse(d)?.candidates?.[0]?.content?.parts) } catch { /* skip */ }
            }
            if (text) return text
        }
        // Non-stream form: a single JSON object (or array of them)
        try {
            const j = JSON.parse(full)
            if (Array.isArray(j)) {
                let t = ''
                for (const item of j) t += partsText(item?.candidates?.[0]?.content?.parts)
                return t
            }
            return partsText(j?.candidates?.[0]?.content?.parts)
        } catch { /* not JSON */ }
        return ''
    }

    function persistDraft(job, isFinal) {
        const meta = job.bgMeta
        // Explicit DELETE means the user no longer wants this generation. The shared stream reader
        // settles intentionally after abort, so its next-tick persistence must not resurrect a
        // partially received response as a completed recovery draft.
        if (job.bgCancelledByClient) return
        // BG-PRESERVE 2a: sub-model/helper calls (FOLD/hypa) are consumed inline by the
        // generation flow and never shown as a chat message — skip chat-draft persistence.
        if (meta && meta.isSub) return
        if (!meta || !meta.charId || !meta.chatId) return
        const text = extractGeminiText(job.bgRaw || [])
        if (!text) return
        const record = {
            key: String(meta.charId) + '::' + String(meta.chatId),
            charId: String(meta.charId),
            chatId: String(meta.chatId),
            charName: meta.charName ? String(meta.charName) : undefined,
            generationId: meta.generationId ? String(meta.generationId) : undefined,
            model: job.bgModel,
            // token meta (from client setBgGenContext → POST meta) → restored generationInfo.
            inputTokens: meta.inputTokens,
            outputTokens: meta.outputTokens,
            maxContext: meta.maxContext,
            data: text,
            time: Date.now(),
            // final = server received the response to completion (done). Partial/error
            // persists with final:false so the client auto-recovers only completed drafts.
            final: !!isFinal && !job.bgRawOverflow,
        }
        try { kvSet(draftKey(meta.charId, meta.chatId), JSON.stringify(record)) }
        catch (e) { console.error('[bg-preserve-job] persist failed:', e && e.message) }
    }

    // 2a step-3: persist a sub call's RAW response bytes (not a chat draft) so a reconnect that
    // lands on a GC'd job can rebuild the Response and continue without re-calling the model.
    function persistSubResult(job, isFinal) {
        const meta = job.bgMeta
        // Persist raw bytes for ANY background-preserve job (sub OR main): a reconnect that lands on a
        // GC'd job rebuilds the Response from kv without re-calling the model. Main carries no isSub flag
        // but has the chat's generationId, so include it too (2a step-4).
        if (!meta || (!meta.isSub && !meta.generationId)) return
        // Foreground/reconnected consumers ACK only after they have drained the Response body.
        // The ACK and this setImmediate callback share one event loop, so both race orders are safe:
        // ACK first makes this write a no-op; persist first is followed by exact-key deletion.
        if (!shouldPersistSubResult(job, consumedSubResults)) {
            consumedSubResults.delete(job.id)
            console.log(`[bg-sub] skip consumed ${job.id}`)
            return
        }
        if (job.bgRawOverflow) {
            try {
                kvSet(subResultKey(job.id), JSON.stringify({
                    rawBase64: '', status: 507, final: false, time: Date.now(),
                    ...recoveryIdentity(job),
                }))
                console.warn(`[bg-sub] recovery buffer exceeded ${MAX_ACCUM_BYTES}B ${job.id}`)
            } catch (e) { console.error('[bg-sub] persist failed:', e && e.message) }
            return
        }
        let raw
        try { raw = Buffer.concat(job.bgRaw || []) } catch { return }
        // [A] raw=0(upstream 받기 전 에러/abort = 생성 실패)이어도 "빈 종결마커"를 저장한다. 안 하면
        // 클라 폴링이 "아직 진행 중"과 "끝났는데 결과 없음"을 구분 못 해 무한 폴링(deadline까지)함.
        // 빈 rawBase64를 받은 클라는 즉시 실패로 종료한다.
        if (!raw || raw.length === 0) {
            try {
                kvSet(subResultKey(job.id), JSON.stringify({
                    rawBase64: '',
                    status: job.bgStatus || 504,
                    final: !!isFinal,
                    time: Date.now(),
                    ...recoveryIdentity(job),
                }))
                console.log(`[bg-sub] persisted ${job.id} (EMPTY, final=${!!isFinal}, status=${job.bgStatus || 504})`)
            } catch (e) { console.error('[bg-sub] persist failed:', e && e.message) }
            return
        }
        try {
            kvSet(subResultKey(job.id), JSON.stringify({
                rawBase64: raw.toString('base64'),
                status: job.bgStatus || 200,
                contentType: job.bgContentType || undefined,
                final: !!isFinal,
                time: Date.now(),
                ...recoveryIdentity(job),
            }))
            console.log(`[bg-sub] persisted ${job.id} (${raw.length}B, final=${!!isFinal}, status=${job.bgStatus || 200})`)
        } catch (e) { console.error('[bg-sub] persist failed:', e && e.message) }
    }

    async function runBgStreamJob(job, arg) {
        // model id from gemini URL (.../models/<model>:generateContent) for recovery meta
        const m = String(arg.targetUrl || '').match(/\/models\/([^:/?]+)/)
        job.bgModel = m ? m[1] : undefined
        try {
            const upstream = await requestLocalTargetStream(arg.targetUrl, {
                method: arg.method,
                headers: arg.headers,
                bodyBuffer: arg.bodyBuffer,
                timeoutMs: job.timeoutMs,
                signal: job.abortController.signal,
            })
            const filtered = {}
            for (const [k, v] of Object.entries(upstream.headers || {})) {
                if (k === 'content-security-policy' || k === 'content-security-policy-report-only' || k === 'clear-site-data') continue
                filtered[k] = v
            }
            // 2a step-3: remember status + content-type so a kv-recovered sub Response is rebuilt faithfully.
            job.bgStatus = upstream.status
            job.bgContentType = filtered['content-type'] || filtered['Content-Type']
            pushJobEvent(job, { type: 'upstream_headers', status: upstream.status, headers: filtered })

            if (upstream.body) {
                await consumeNodeReadable(upstream.body, (value) => {
                    if (job.abortController.signal.aborted) return
                    if (value && value.length > 0) {
                        const chunk = Buffer.from(value)
                        const offset = Number.isSafeInteger(job.bgRawTotalBytes) ? job.bgRawTotalBytes : 0
                        job.bgRawTotalBytes = offset + chunk.length
                        // Offset lets a reconnecting client detect a WebSocket handoff gap. The
                        // authoritative full raw bytes remain in KV; the client never guesses.
                        pushJobEvent(job, { type: 'chunk', dataBase64: chunk.toString('base64'), offset })
                        captureBoundedRaw(job, chunk, MAX_ACCUM_BYTES)
                    }
                }, { signal: job.abortController.signal })
            }
            pushJobEvent(job, {
                type: 'done',
                totalBytes: Number.isSafeInteger(job.bgRawTotalBytes) ? job.bgRawTotalBytes : 0,
            })
            // T1-a: persist(extractGeminiText 전체 concat + base64 + 동기 kvSet)를 다음 틱으로 분리해
            // done 직후 이벤트 루프를 큰 응답에서 막지 않음. persist 뒤 bgRaw(최대 12MB)를 즉시 해제해
            // grace(30s) 동안 메모리를 안 들고 있음. raw kv 자체는 유지(tool/thinking 복구).
            markJobDone(job)
            setImmediate(() => {
                try { persistDraft(job, true); persistSubResult(job, true) }
                catch (e) { console.error('[bg-preserve-job] persist(done) failed:', e && e.message) }
                finally { job.bgRaw = null }
            })
        } catch (error) {
            const message = error && error.name === 'AbortError' ? 'bg stream job aborted' : `${error}`
            pushJobEvent(job, { type: 'error', status: 504, message })
            markJobDone(job)
            setImmediate(() => {
                try { persistDraft(job, false); persistSubResult(job, false) } catch { /* ignore */ }
                finally { job.bgRaw = null }
            })
        }
    }

    app.post('/api/bg-stream-job', sessionAuthMiddleware, (req, res) => {
        try {
            const b = req.body || {}
            const url = typeof b.url === 'string' ? b.url : ''
            let parsed = null
            try { parsed = new URL(url) } catch { parsed = null }
            if (!parsed || (parsed.protocol !== 'http:' && parsed.protocol !== 'https:')) {
                return res.status(400).json({ error: 'Invalid target URL' })
            }
            if (isMetadataHost(parsed.hostname)) {
                return res.status(403).json({ error: 'Target host not allowed' })
            }
            if (proxyStreamJobs.size >= 64) {
                return res.status(429).json({ error: 'Too many active stream jobs. Retry shortly.' })
            }
            const method = typeof b.method === 'string' ? b.method.toUpperCase() : 'POST'
            const headers = (b.headers && typeof b.headers === 'object' && !Array.isArray(b.headers)) ? b.headers : {}
            const bodyBuffer = (typeof b.bodyBase64 === 'string' && b.bodyBase64) ? Buffer.from(b.bodyBase64, 'base64') : undefined
            const meta = (b.meta && typeof b.meta === 'object') ? b.meta : {}

            // Client fetchNative names this requestTimeoutMs. Accept timeoutMs too for rolling/manual
            // callers, but do not silently discard the actual client field and fall back to default.
            const requestedTimeoutMs = b.requestTimeoutMs ?? b.timeoutMs
            const job = createProxyStreamJob({ heartbeatSec: b.heartbeatSec, timeoutMs: requestedTimeoutMs })
            job.bgMeta = {
                charId: meta.charId != null ? String(meta.charId) : undefined,
                chatId: meta.chatId != null ? String(meta.chatId) : undefined,
                generationId: meta.generationId != null ? String(meta.generationId) : undefined,
                charName: meta.charName != null ? String(meta.charName) : undefined,
                inputTokens: meta.inputTokens != null ? Number(meta.inputTokens) : undefined,
                outputTokens: meta.outputTokens != null ? Number(meta.outputTokens) : undefined,
                maxContext: meta.maxContext != null ? Number(meta.maxContext) : undefined,
                isSub: !!meta.isSub,
                subKey: meta.subKey != null ? String(meta.subKey) : undefined,
            }
            job.bgRaw = []
            job.bgRawTotalBytes = 0
            job.bgCancelCleanup = () => clearCancelledRecoveryArtifacts(job, {
                kvGet, kvDel, draftKey, subResultKey, consumedSubResults,
            })

            void runBgStreamJob(job, { targetUrl: parsed.toString(), method, headers, bodyBuffer })

            // T3-b observability: a delegation reached the server (the "걸림" positive signal).
            // Metadata only — no prompt/body. Pairs with the client-side anti-signal below so a
            // silent "0 delegations" can be told apart from "no request at all".
            const _kind = job.bgMeta.isSub ? 'sub' : (job.bgMeta.generationId ? 'main' : 'main?')
            console.log(`[bg-preserve] delegate recv ${job.id} kind=${_kind} gen=${job.bgMeta.generationId || '-'} sub=${job.bgMeta.subKey || '-'}`)

            res.json({ jobId: job.id, heartbeatSec: job.heartbeatSec })
        } catch (e) {
            res.status(500).json({ error: String((e && e.message) || e) })
        }
    })

    // T3-b observability: client fire-and-forget signal for a gemini request that did NOT delegate
    // (impl-null / usePlainFetch / gate-miss / fallback-throw). Non-delegated requests never reach
    // the server's job route, so the client is the only place that sees them. Logged as a warning so
    // a silent delegation regression (e.g. upstream interceptor/URL rename → T3-c drift) surfaces in
    // the server log instead of needing a temp probe. Metadata only (reason + short detail), capped.
    app.post('/api/bg-preserve-signal', sessionAuthMiddleware, (req, res) => {
        try {
            const b = req.body || {}
            const reason = typeof b.reason === 'string' ? b.reason.slice(0, 40).replace(/[\r\n\t]+/g, ' ') : '?'
            const detail = typeof b.detail === 'string' ? b.detail.slice(0, 200).replace(/[\r\n\t]+/g, ' ') : ''
            console.warn(`[bg-preserve] client signal reason=${reason}${detail ? ' ' + detail : ''}`)
        } catch { /* best-effort */ }
        res.json({ ok: true })
    })

    // 2a step-3: reconnect-to-gone-job fallback. GET is non-destructive: a page can be killed after
    // receiving this JSON but before its rebuilt Response is drained. The exact ACK below is the
    // commit point; abandoned records remain bounded by the TTL purge.
    app.get('/api/bg-sub-result/:jobId', sessionAuthMiddleware, (req, res) => {
        try {
            const key = subResultKey(req.params.jobId)
            const val = kvGet(key)
            if (!val) {
                console.log(`[bg-sub] kv recover MISS ${req.params.jobId}`)
                return res.json({ found: false })
            }
            let parsed = null
            try { parsed = JSON.parse(val) } catch { parsed = null }
            if (!parsed) return res.json({ found: false })
            console.log(`[bg-sub] kv recover HIT ${req.params.jobId} (final=${parsed.final})`)
            res.json({ found: true, rawBase64: parsed.rawBase64, status: parsed.status, contentType: parsed.contentType, final: parsed.final })
        } catch (e) {
            res.status(500).json({ error: String((e && e.message) || e) })
        }
    })

    // A live client no longer needs the recovery copy after it has consumed the complete raw
    // Response. Exact job acknowledgement avoids the old 30-minute foreground kv residue without
    // weakening background recovery. `job` remains in the grace Map long enough to close the
    // ACK-before-persist race; ACK-after-persist deletes the already-written exact key.
    app.post('/api/bg-sub-result/:jobId/ack', sessionAuthMiddleware, (req, res) => {
        try {
            const jobId = String(req.params.jobId || '')
            if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(jobId)) {
                return res.status(400).json({ error: 'Invalid job id' })
            }
            const job = proxyStreamJobs.get(jobId)
            if (job) job.bgResultConsumed = true
            rememberConsumedResult(consumedSubResults, jobId)
            try { kvDel(subResultKey(jobId)) } catch { /* retry remains bounded by TTL */ }
            res.json({ acknowledged: true })
        } catch (e) {
            res.status(500).json({ error: String((e && e.message) || e) })
        }
    })

    // Bound kv growth: purge abandoned sub-result slots (user never returned) older than the TTL.
    if (typeof kvList === 'function' && typeof kvGetUpdatedAt === 'function') {
        setInterval(() => {
            try {
                const now = Date.now()
                for (const key of kvList(SUB_RESULT_PREFIX)) {
                    const at = kvGetUpdatedAt(key)
                    if (at != null && now - at > SUB_RESULT_TTL_MS) kvDel(key)
                }
                for (const [jobId, at] of consumedSubResults) {
                    if (now - at > SUB_RESULT_TTL_MS) consumedSubResults.delete(jobId)
                }
            } catch { /* best-effort */ }
        }, 10 * 60 * 1000)
    }
}

module.exports = registerBgStreamJob
module.exports.shouldPersistSubResult = shouldPersistSubResult
module.exports.captureBoundedRaw = captureBoundedRaw
module.exports.clearCancelledRecoveryArtifacts = clearCancelledRecoveryArtifacts
module.exports.rememberConsumedResult = rememberConsumedResult

'use strict'

const { Readable } = require('stream')
const { pipeline } = require('stream/promises')

function prematureCloseError() {
  const error = new Error('Premature close')
  error.code = 'ERR_STREAM_PREMATURE_CLOSE'
  return error
}

// IncomingMessage async iteration installs end-of-stream cleanup that can itself reject after an
// early close. Explicit listeners keep that error in this one Promise and make abort cleanup
// deterministic for both the host proxy-stream job and the owned external bg job.
function consumeNodeReadable(readable, onChunk, options) {
  if (!readable) return Promise.resolve()
  const signal = options && options.signal
  return new Promise((resolve, reject) => {
    let ended = false
    let settled = false

    const cleanup = () => {
      readable.removeListener('data', handleData)
      readable.removeListener('end', handleEnd)
      readable.removeListener('error', handleError)
      readable.removeListener('aborted', handleAborted)
      readable.removeListener('close', handleClose)
      if (signal) signal.removeEventListener('abort', handleSignalAbort)
    }
    const finish = (error) => {
      if (settled) return
      settled = true
      cleanup()
      if (error) reject(error)
      else resolve()
    }
    const handleData = (chunk) => {
      if (settled) return
      try { onChunk(chunk) }
      catch (error) {
        // Reject through this Promise. destroy(error) emits `error` on a later tick; removing our
        // listener immediately afterwards would turn that delayed event into an uncaught error.
        try { readable.destroy() } catch { /* ignore */ }
        finish(error)
      }
    }
    const handleEnd = () => { ended = true; finish() }
    const handleError = (error) => finish(error)
    const handleAborted = () => finish(prematureCloseError())
    const handleClose = () => { if (!ended) finish(prematureCloseError()) }
    const handleSignalAbort = () => {
      try { readable.destroy() } catch { /* ignore */ }
      finish()
    }

    readable.on('data', handleData)
    readable.once('end', handleEnd)
    readable.once('error', handleError)
    readable.once('aborted', handleAborted)
    readable.once('close', handleClose)
    if (signal) {
      if (signal.aborted) { handleSignalAbort(); return }
      signal.addEventListener('abort', handleSignalAbort, { once: true })
    }
    try { readable.resume() } catch (error) { finish(error) }
  })
}

// stream.pipeline destroys every participant after either side fails. Looking only at
// res.destroyed/res.closed in the catch block therefore cannot tell a harmless client disconnect
// from a real upstream truncation: both are already closed by then. Record which side failed first
// while the events still retain that information, and carry it on the original pipeline error.
async function pipelineProxyResponse(readable, response) {
  const source = readable && typeof readable.getReader === 'function'
    ? Readable.fromWeb(readable)
    : readable
  let failureOrigin = ''
  let sourceEnded = false

  const markUpstream = () => { if (!failureOrigin) failureOrigin = 'upstream' }
  const markDownstream = () => {
    if (!failureOrigin && !response.writableEnded) failureOrigin = 'downstream'
  }
  const markSourceEnd = () => { sourceEnded = true }
  const markSourceClose = () => { if (!sourceEnded) markUpstream() }

  source.once('end', markSourceEnd)
  source.once('error', markUpstream)
  source.once('aborted', markUpstream)
  source.once('close', markSourceClose)
  response.once('error', markDownstream)
  response.once('close', markDownstream)

  try {
    await pipeline(source, response)
  } catch (error) {
    if (error && typeof error === 'object') {
      try { error.proxyStreamFailureOrigin = failureOrigin || 'unknown' } catch { /* immutable error */ }
    }
    throw error
  } finally {
    source.removeListener('end', markSourceEnd)
    source.removeListener('error', markUpstream)
    source.removeListener('aborted', markUpstream)
    source.removeListener('close', markSourceClose)
    response.removeListener('error', markDownstream)
    response.removeListener('close', markDownstream)
  }
}

function isExpectedProxyClientClose(error, state) {
  return !!error && error.code === 'ERR_STREAM_PREMATURE_CLOSE'
    && error.proxyStreamFailureOrigin !== 'upstream'
    && !!state && !!(state.requestAborted || error.proxyStreamFailureOrigin === 'downstream')
}

module.exports = { consumeNodeReadable, pipelineProxyResponse, isExpectedProxyClientClose }

'use strict'

const RUNTIME_PREFIX = 'bg-orch-runtime:'
const STATE_STORAGE_KEY = 'nodeOnlyGeminiCacheState'
const HISTORY_STORAGE_KEY = 'nodeOnlyGeminiCacheHistory'

function parseJson(value, fallback) {
  try { return value ? JSON.parse(value) : fallback } catch { return fallback }
}

function finiteNumber(value) {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined
}

function buildCacheStatus(kvGet, query, now = Date.now()) {
  const presetId = typeof query.presetId === 'string' ? query.presetId : ''
  const chatId = typeof query.chatId === 'string' ? query.chatId : ''
  const rawState = parseJson(kvGet(RUNTIME_PREFIX + STATE_STORAGE_KEY), {})
  const rawHistory = parseJson(kvGet(RUNTIME_PREFIX + HISTORY_STORAGE_KEY), [])
  const history = Array.isArray(rawHistory)
    ? rawHistory.filter((event) => event && typeof event === 'object'
      && (!presetId || event.presetId === presetId)
      && (!chatId || event.chatKey === chatId))
    : []
  const entries = []
  if (rawState && typeof rawState === 'object' && !Array.isArray(rawState)) {
    for (const [cacheKey, entry] of Object.entries(rawState)) {
      if (!entry || typeof entry !== 'object') continue
      if (presetId && !cacheKey.endsWith('::' + presetId)) continue
      if (chatId && !cacheKey.startsWith(chatId + '::')) continue
      const expiresAt = finiteNumber(entry.expiresAt)
      if (!expiresAt || expiresAt <= now) continue
      const related = history.filter((event) => event.cacheKey === cacheKey)
      const create = [...related].reverse().find((event) => event.type === 'create'
        && (!event.cacheName || event.cacheName === entry.cacheName))
      const hits = related.filter((event) => event.type === 'explicit-hit')
      const lastEvent = related.length ? related[related.length - 1] : null
