        modelId: typeof entry.modelId === 'string' ? entry.modelId : '',
        createdAt: finiteNumber(entry.createdAt),
        expiresAt,
        remainingMs: Math.max(0, expiresAt - now),
        cacheTokenCount: finiteNumber(entry.cacheTokenCount)
          ?? finiteNumber(create && create.cacheTokenCount),
        promptTokensAtCreation: finiteNumber(entry.promptTokensAtCreation),
        hitCount: hits.length,
        totalHitTokens: hits.reduce((sum, event) => sum + (finiteNumber(event.requestCachedTokens) || 0), 0),
        lastHitAt: finiteNumber(hits.length ? hits[hits.length - 1].time : undefined),
        lastEvent,
