'use strict'

// BG-PRESERVE — cross-device storage for streaming LLM responses lost when the
// app is backgrounded on mobile. Owned by the BG-PRESERVE patch (not upstream
// PocketRisu); registered from server.cjs via a single hooked line so an upstream
// update only needs `node bg-preserve-install.cjs apply` to re-register it.
//
// Drafts are stored in the kv table under the `bg-stream-draft:` prefix, keyed by
// `<charId>::<chatId>`, value = JSON of the draft. The client POSTs via sendBeacon
// (cookie auth flows automatically), lists via GET, and removes on restore/dismiss.

module.exports = function registerBgDraftRoutes(app, deps) {
    const { kvGet, kvSet, kvList, kvDel, sessionAuthMiddleware } = deps || {}
    if (!app || !kvGet || !kvSet || !kvList || !kvDel || !sessionAuthMiddleware) {
        console.error('[bg-preserve] registerBgDraftRoutes: missing dependencies, skipping')
        return
    }

    const PREFIX = 'bg-stream-draft:'
    const keyOf = (charId, chatId) => PREFIX + String(charId) + '::' + String(chatId)

    // Upsert a draft (sent via sendBeacon as the page backgrounds).
    app.post('/api/bg-stream-draft', sessionAuthMiddleware, (req, res) => {
        try {
            const d = req.body || {}
            if (!d.charId || !d.chatId) {
                return res.status(400).json({ error: 'charId/chatId required' })
            }
            const record = {
                key: String(d.charId) + '::' + String(d.chatId),
                charId: String(d.charId),
                chatId: String(d.chatId),
                charName: typeof d.charName === 'string' ? d.charName : undefined,
                generationId: typeof d.generationId === 'string' ? d.generationId : undefined,
                data: typeof d.data === 'string' ? d.data : '',
                time: typeof d.time === 'number' ? d.time : Date.now(),
            }
            kvSet(keyOf(record.charId, record.chatId), JSON.stringify(record))
            res.json({ ok: true })
        } catch (e) {
            res.status(500).json({ error: String((e && e.message) || e) })
        }
    })

    // List all drafts.
    app.get('/api/bg-stream-draft', sessionAuthMiddleware, (req, res) => {
        try {
            const keys = kvList(PREFIX) || []
            const drafts = []
            for (const k of keys) {
                const v = kvGet(k)
                if (!v) continue
                try { drafts.push(JSON.parse(v)) } catch { /* skip corrupt */ }
            }
            res.json(drafts)
        } catch (e) {
            res.status(500).json({ error: String((e && e.message) || e) })
        }
    })

    // Delete one draft (on restore or dismiss).
    app.post('/api/bg-stream-draft/delete', sessionAuthMiddleware, (req, res) => {
        try {
            const d = req.body || {}
            if (!d.charId || !d.chatId) {
                return res.status(400).json({ error: 'charId/chatId required' })
            }
            kvDel(keyOf(d.charId, d.chatId))
            res.json({ ok: true })
        } catch (e) {
            res.status(500).json({ error: String((e && e.message) || e) })
        }
    })
    // NOTE: no TTL purge for `bg-stream-draft:` — the key is charId::chatId (one slot per chat,
    // overwritten each stream), so it's bounded by chat count and drained by the client's
    // restore/dismiss (kvDel). Measured n=0 (T3-a 2026-06-06, re-confirmed 2026-07-03). Adding a
    // purge would be dead code (통찰 주제4). The transient bg-sub-result/bg-orch-result prefixes DO
    // purge because they're keyed per-jobId (unbounded) and may be abandoned mid-flight.
}

