const ROOT = path.resolve(__dirname, '../..')
const BUNDLE = path.join(__dirname, 'bgOrchBundle.mjs')

// S4 round-trip result kv (separate prefix from bg-stream-draft/bg-sub-result → no collision).
const ORCH_RESULT_PREFIX = 'bg-orch-result:'
