const ORCH_RESULT_CLAIM_TTL_MS = 2 * 60 * 1000
const ORCH_RESULT_CLAIM_REFRESH_MS = 15 * 1000
const orchResultKey = (charId, chatId) => ORCH_RESULT_PREFIX + String(charId) + '::' + String(chatId)
