// diagnostics → chatProcessStage 0..4), read by the matching poll only.
const _orchStage = {}
// Live request-status snapshot per in-flight orchestration (charId::chatId → RelayedStatusSnapshot[]),
// relayed to the client so the "요청 상태 표시" toast works while the generation runs server-side
// (the status publishers run in the server bundle, so the client's own store would stay empty).
const _orchStatus = {}
const stageKey = (charId, chatId) => String(charId) + '::' + String(chatId)
