// client toastId ping-pong → svelte-sonner desync. We prefer the bundle's isTerminalPhase(), but
// fall back to this hardcoded set so a bundle that drops/renames the export can't silently fail-open
// (forward terminals). Mirrors requestStatus.ts isTerminalPhase().
const TERMINAL_PHASES = new Set(['done', 'failed', 'aborted'])
const orchestrationAbortContext = createOrchestrationAbortContext()

// Park a full-orchestration result for the client to consume one-shot on return (S4b).
// `kind` is authoritative: only intermediate keeps polling; every terminal outcome closes the
// watch. `final` remains as a compatibility field for clients from before the typed lifecycle.
// Module-scope (not a closure over deps) so runServerPreview can call it directly for the
// mid-publish; kvSet is passed explicitly.
const ORCH_RESULT_KINDS = new Set(['intermediate', 'terminal-success', 'terminal-partial', 'terminal-error'])
