  const baselineMsgs = chatMessageCount(baselineChat)
  const resultMsgs = chatMessageCount(result && result.chat)
  const hasMainReply = baselineMsgs >= 0 && resultMsgs > baselineMsgs
  if (result && result.threw) return hasMainReply ? 'terminal-partial' : 'terminal-error'
  return hasMainReply ? 'terminal-success' : 'terminal-error'
}
