    found: true, resultId: record.resultId, operationId: record.operationId,
    publishSeq: record.publishSeq, kind: record.kind, outcome: record.outcome,
    final: record.final, chat: record.chat,
    staticsMessagesDelta: record.staticsMessagesDelta || 0,
    globalChatVariables: record.globalChatVariables || {},
    globalChatVariablesDeleted: record.globalChatVariablesDeleted || [],
    globalChatVariablesExpected: record.globalChatVariablesExpected || {},
