  if (typeof kvSet !== 'function' || !result) {
    return { persisted: false, error: new Error('result store unavailable'), record: null }
  }
  const requestedKind = opts && opts.kind
  const kind = ORCH_RESULT_KINDS.has(requestedKind)
    ? requestedKind
    : ((opts && opts.final === false) ? 'intermediate' : (result.threw ? 'terminal-error' : 'terminal-success'))
  const final = kind !== 'intermediate'
  const outcome = kind === 'terminal-success' ? 'success'
    : kind === 'terminal-partial' ? 'partial'
      : kind === 'terminal-error' ? 'error' : undefined
