    charId: String(charId), chatId: String(chatId),
    resultId: nodeCrypto.randomUUID(),
    operationId: opts && typeof opts.operationId === 'string' ? opts.operationId : undefined,
    publishSeq: opts && Number.isSafeInteger(opts.publishSeq) && opts.publishSeq > 0 ? opts.publishSeq : undefined,
    chat: result.chat, statics: result.statics,
    staticsMessagesDelta: result.staticsMessagesDelta || 0,
    globalChatVariables: result.globalChatVariables || {},
    globalChatVariablesDeleted: result.globalChatVariablesDeleted || [],
    globalChatVariablesExpected: result.globalChatVariablesExpected || {},
    kind, outcome, final,
    error: result.threw || undefined,
    postError: kind === 'terminal-partial' ? (result.threw || undefined) : undefined,
    time: Date.now(),
  }
  const operationKeyed = opts && opts.resultKeyVersion === 1 && validOperationId(record.operationId)
  const key = operationKeyed ? operationResultKey(record.operationId) : orchResultKey(charId, chatId)
  try {
    if (operationKeyed) record = inheritDeliveryClaim(opts && opts.kvGet, key, record)
    kvSet(key, JSON.stringify(record))
    return { persisted: true, error: null, record }
  } catch (e) {
    console.error('[bg-orch] result persist failed:', e && e.message)
    return { persisted: false, error: e, record }
  }
