// ── lazy bundle load ────────────────────────────────────────────────────────
// M2 guard: bgOrchBundle.mjs is a BUILD ARTIFACT (bgOrchBundle.build.cjs), not in install.cjs's
// payload. A manual `pnpm build` rebuilds the client dist but NOT this bundle, so server
// orchestration can silently run STALE source (the S7 editoutput bug). bgupdate rebuilds both, but a
// manual build won't — so warn (once, at first load) if any sendChat-path source is newer than the
// bundle. Not a hard gate: the fix (regenerate the bundle) is out-of-band, and a false stall would be
// worse than a stale warning. Curated source list = the realistic edit surface (bundle-executed path).
let _staleChecked = false
function checkBundleStale() {
  if (_staleChecked) return
  _staleChecked = true
  try {
    const bundleMtime = fs.statSync(BUNDLE).mtimeMs
    const srcs = [
      'src/ts/process/index.svelte.ts', 'src/ts/process/scripts.ts',
      'src/ts/process/request/request.ts',
      'src/ts/storage/database.svelte.ts', 'src/ts/status/requestStatus.ts',
      'src/ts/translator/translator.ts', 'src/ts/stores.svelte.ts', 'src/ts/bgOrchestrate.ts',
    ]
    let newest = 0, newestFile = ''
    for (const rel of srcs) {
      try { const mt = fs.statSync(path.join(ROOT, rel)).mtimeMs; if (mt > newest) { newest = mt; newestFile = rel } } catch { /* ignore */ }
    }
    if (newest > bundleMtime) {
      console.warn(`[bg-orch] WARNING: bgOrchBundle.mjs looks STALE — ${newestFile} is newer than the bundle. ` +
        'Server orchestration may run old source. Rebuild: node server/node/bgOrchBundle.build.cjs (bgupdate does this automatically).')
    }
  } catch { /* best-effort */ }
}

let _bundlePromise = null
function loadBundle() {
  if (_bundlePromise) return _bundlePromise
  checkBundleStale()
  _bundlePromise = (async () => {
    const { pathToFileURL } = require('url')
    // Preload the node-only side packages BEFORE the bundle's banner sets window/document
    // stubs, so they take their node build path (not browser). See §18 S2 measurements.
    //  - transformers: gemma tokenizer (browser-vs-node picked at module load via `self`)
    //  - wasmoon: Lua engine (browser-vs-node picked via document/location)
    await import(pathToFileURL(path.join(ROOT, 'node_modules/@huggingface/transformers/dist/transformers.node.mjs')).href)
    require(path.join(ROOT, 'node_modules/wasmoon'))
    patchFetch()
    await import(pathToFileURL(BUNDLE).href) // sets globalThis.__bgOrch + window/document stubs
    const bg = globalThis.__bgOrch
    if (!bg || !bg.idx || typeof bg.idx.sendChat !== 'function') throw new Error('bundle loaded but sendChat missing')
    return bg
  })().catch((e) => { _bundlePromise = null; throw e }) // allow retry on failure
  return _bundlePromise
}

// MARKER: wrap a gemini LLM fetch so we log which model took how long (non-stream → fetch resolve
// ≈ that LLM's generation time). NOTE: the MAIN Vertex call bypasses globalThis.fetch (goes
// aiplatform direct), so this only catches LLM calls that go through globalThis.fetch (/proxy2 +
// classic absolute). The stage markers in runServerPreview are the reliable per-stage timing.
function llmMark(url, p) {
  const model = (String(url).match(/\/models\/([^:/?]+)/) || [])[1] || '?'
  const t0 = Date.now()
  return Promise.resolve(p).then(
    (res) => { console.log(`[bg-orch] LLM ${model} ${Date.now() - t0}ms`); return res },
    (e) => { console.log(`[bg-orch] LLM ${model} FAIL ${Date.now() - t0}ms`); throw e }
  )
}

// The bundle's tokenizer loads tokenizer json via relative URLs (/token/*.json); node's
// fetch can't parse those, so serve them from dist/ directly. Other fetches pass through.
function patchFetch() {
  if (globalThis.__bgOrchFetchPatched) return
  const realFetch = globalThis.fetch
  globalThis.fetch = function (u, ...a) {
    // Direct fetches inside Hypa, trigger scripts, OAuth and provider adapters do not all receive
    // sendChat's signal as an explicit argument. AsyncLocalStorage identifies only descendants of
    // the active orchestration, so adding its signal here cannot abort an unrelated server request.
    const inheritedInit = orchestrationAbortContext.withSignal(a[0])
    if (inheritedInit !== a[0]) a = [inheritedInit, ...a.slice(1)]
    if (typeof u === 'string') {
      // Tokenizer json (/token/*.json): node fetch can't parse the relative URL; serve from dist.
      if (u.startsWith('/token/')) {
        const p = path.join(ROOT, 'dist', u)
        const buf = fs.readFileSync(p, 'utf8')
        return Promise.resolve({ ok: true, json: async () => JSON.parse(buf), text: async () => buf })
      }
      // Lua module files (/lua/*.lua): makeLuaFactory mounts json.lua via fetch('/lua/json.lua').
      // In node that relative URL fails → the catch swallows it → an EMPTY file is mounted →
      // `require 'json'` returns boolean true → user Lua triggers crash ("index a boolean value
      // (global 'json')") → the trigger's own LLM call (e.g. a custom summarizer = the 보조 model)
      // never fires server-side. Serve from dist so the Lua env matches the browser. Same fix
      // pattern as /token/ above.
      if (u.startsWith('/lua/')) {
        try {
          const buf = fs.readFileSync(path.join(ROOT, 'dist', u), 'utf8')
          return Promise.resolve({ ok: true, status: 200, json: async () => JSON.parse(buf), text: async () => buf })
        } catch (e) {
