      // the proxy2 `risu-auth` header. We handle /proxy2 directly below (no server auth check),
      // so the token value is irrelevant — return a stub so createAuth resolves instead of
      // throwing on the relative URL (the original blocker: "Failed to parse URL").
      if (u === '/api/token/refresh') {
