// metadata, server already holds it) with the client's unsaved currentChat injected into
// the selected slot — the rest of the chats stay stubs (sendChat only reads the selected
// char/chat). Mirrors the S1 db-input shape; no full 1.4GB decode.
async function runServerPreview(deps, selectedCharId, selectedChatId, currentChat, mode, control) {
  const prev = _previewLock
  let release
  _previewLock = new Promise((r) => { release = r })
  await prev
  // S3: cap the LLM call with a timeout/abort so a stalled gemini response can't hold
  // _previewLock forever. M4 also forwards the operation controller into this same signal;
  // the async fetch context carries it to helper requests that omit an explicit signal.
  // 600s cap: Gemini 3.1 Pro reasoning replies measured ~136s, so the timeout must clear a
  // normal long reply by a wide margin and only fire on a genuine stall (the lock is per-server
  // and single-user, so a long ceiling is fine).
  const llmAbort = (mode === 'llm' || mode === 'full') ? new AbortController() : null
  const llmTimer = llmAbort ? setTimeout(() => llmAbort.abort(), 600000) : null
  const externalSignal = control && control.signal
  const forwardExternalAbort = () => {
    if (!llmAbort || llmAbort.signal.aborted) return
    try { llmAbort.abort(externalSignal && externalSignal.reason) } catch { llmAbort.abort() }
  }
  if (llmAbort && externalSignal) {
    if (externalSignal.aborted) forwardExternalAbort()
    else externalSignal.addEventListener('abort', forwardExternalAbort, { once: true })
  }
  try {
    if ((externalSignal && externalSignal.aborted)
      || (control && typeof control.isCancelled === 'function' && control.isCancelled())) {
      throw new Error('orchestration cancelled')
    }
    const bg = await loadBundle()
    // The first run after a restart can spend time loading the 8 MB bundle. A cancel delivered
    // during that await must stop before this run installs its cloned DB into bundle singletons.
    if ((externalSignal && externalSignal.aborted)
      || (control && typeof control.isCancelled === 'function' && control.isCancelled())) {
      throw new Error('orchestration cancelled')
    }
    const { idx, stores, dbmod, status } = bg

    const dbCache = typeof deps.getDbCache === 'function' ? deps.getDbCache() : null
    let stripped = dbCache && deps.DB_HEX_KEY ? dbCache[deps.DB_HEX_KEY] : null
    if (!stripped || !Array.isArray(stripped.characters)) {
      // dbCache is lazy (populated on the first /api/db read); right after a restart it can
      // be empty. Fall back to decoding the db blob from disk. (In normal use the user's app
      // has read /api/db, so dbCache is warm and this path is skipped.)
      const dbmodS = require('./db.cjs')
      const utils = require('./utils.cjs')
      const raw = dbmodS.kvGet('database/database.bin')
      if (!raw) throw new Error('no db blob on disk')
      stripped = utils.normalizeJSON(await utils.decodeRisuSave(raw))
    }
    if (!stripped || !Array.isArray(stripped.characters)) throw new Error('db not available')

    const db = JSON.parse(JSON.stringify(stripped)) // clone so we never mutate the live cache
    const charIdx = db.characters.findIndex((c) => c && c.chaId === selectedCharId)
    if (charIdx < 0) throw new Error('char not found in dbCache: ' + selectedCharId)
    const chats = db.characters[charIdx].chats
    if (!Array.isArray(chats)) throw new Error('char has no chats array')
    let chatIdx = chats.findIndex((c) => c && c.id === selectedChatId)
    if (chatIdx < 0) throw new Error('chat not found: ' + selectedChatId)
    chats[chatIdx] = currentChat // inject the client's unsaved live chat (full body)
    db.characters[charIdx].chatPage = chatIdx

    // The selected chat was already injected from the client; global variables need the same
    // freshness guarantee. Otherwise an unsaved client deletion can reappear from the server DB.
    if (mode === 'full' && control && control.globalChatVariablesSnapshotVersion === 1) {
      const snapshot = control.globalChatVariablesSnapshot
      if (!snapshot || typeof snapshot !== 'object' || Array.isArray(snapshot)) {
        throw new Error('invalid global variable snapshot')
      }
      db.globalChatVariables = JSON.parse(JSON.stringify(snapshot))
    }

    dbmod.setDatabase(db)
    stores.selectedCharID.set(charIdx)

    // S4 full: snapshot globals before generation to diff to changed keys + message-count delta.
    const globalVarsBefore = (mode === 'full') ? JSON.stringify((db && db.globalChatVariables) || {}) : '{}'
    const staticsMsgsBefore = (mode === 'full' && db && db.statics) ? (db.statics.messages || 0) : 0

    // wasmoon re-detects browser env (document/location) at createEngine time; the assembly
    // itself doesn't touch them at runtime, so hide them across the preview so Lua takes the
    // node branch. Restore afterwards.
    const sd = globalThis.document, sl = globalThis.location
    // S3: mode 'llm' assembles AND calls the LLM (previewLLM → reply text), returning right
    // before post-processing. mode 'assemble' (S2) stops just before the LLM call (preview →
    // formated). Both run with document/location hidden so wasmoon (trigger Lua) takes its node
    // branch. The LLM call itself needs no document/location: bgStreamFetchImpl is null on the
    // server (initBgStreamPreserve never runs), so fetchNative skips the WS-job delegation and
    // does a direct fetch of the absolute gemini URL — node has no CORS, so it just works.
    // MARKER: log each chatProcessStage transition with elapsed time (aux→main→post boundaries +
    // where the wall-clock goes). Also feeds the client top-bar via _orchStage.
    let unsubStage = null
    let unsubStatus = null
    if (mode === 'full') {
      const sKey = control && control.resultKeyVersion === 1 && validOperationId(control.operationId)
        ? control.operationId
        : stageKey(selectedCharId, selectedChatId)
      // Relay the request-status store (요청 상태 표시 toast) to the client. The status publishers
      // run inside this server bundle's request.ts, so the client's own store stays empty during a
      // server-orchestrated gen. Snapshot only the display fields the toast reads (no prompt text)
      // into _orchStatus[sKey]; the poll ships it and the client ingests it (relayed entries).
      if (status && status.requestStatuses && typeof status.requestStatuses.subscribe === 'function') {
        unsubStatus = status.requestStatuses.subscribe((map) => {
          try {
            const arr = []
            if (map && typeof map.forEach === 'function') {
              map.forEach((e) => {
                if (!e || typeof e.id !== 'string') return
                // Skip terminal (done/failed/aborted) entries. A relayed terminal entry makes the
                // client's RequestStatusToaster schedule a dismiss (→ clearStatus deletes the store
                // entry + shown.delete) while the NEXT poll re-sets it (the server still reports it
                // in its snapshot) → toast.custom re-fires on an id that's mid-dismiss → svelte-sonner's
                // heights/toasts arrays desync → "Cannot read properties of undefined (reading 'toastId')".
                // Relaying only in-flight entries breaks that ping-pong: the client drops each one once
                // it leaves the snapshot (on completion) = a single clean dismiss, no re-issue.
                const isTerminal = (typeof status.isTerminalPhase === 'function')
                  ? status.isTerminalPhase(e.phase)
                  : TERMINAL_PHASES.has(e.phase)
                if (isTerminal) return
                arr.push({
                  id: e.id, chatId: e.chatId, kind: e.kind, label: e.label, phase: e.phase,
                  thinkingTokens: e.thinkingTokens || 0, responseTokens: e.responseTokens || 0,
                  tokPerSec: e.tokPerSec || 0, startedAt: e.startedAt,
                  // Server-clock elapsed so the client can rebase onto its own clock (startedAt is
                  // the server's clock → a client whose clock lags would otherwise show 0.0s).
                  elapsedMs: Math.max(0, Date.now() - (e.startedAt || Date.now())),
                  endedAt: e.endedAt,
                  retryAttempt: e.retryAttempt,
                  badges: Array.isArray(e.badges) ? e.badges.map((b) => ({ key: b.key, text: b.text, tone: b.tone })) : [],
                  error: e.error,
                })
              })
            }
            _orchStatus[sKey] = arr
          } catch { /* best-effort */ }
        })
      }
      let _sp = -1, _st = Date.now()
      // S4 2-stage round-trip (§18.10 handoff item 4): stage 4 = main reply pushed, post-processing
      // (igp/translate/auto-continue/etc) starting. Publish a kind=intermediate snapshot
      // right here so the client shows the main reply immediately instead of waiting out post too —
      // mergeOrchestrationResult merges it and keeps polling. The eventual terminal publish (after
      // this whole function returns) overwrites this kv entry. Once per call (midPublished) —
      // chatProcessStage can re-enter 4 on
      // auto-continue loops; only the FIRST main reply needs the early show.
      let midPublished = false
      // Reset the (module-singleton) stage store to 0 BEFORE subscribing. It is left at 4 by a
      // PRIOR generation, so without this the subscribe's initial emit would be that residual 4 →
      // (a) the client top-bar flashes purple (stage 4) at the START of a new gen (b) a spurious
      // mid-publish of a stale/empty chat fires. sendChat resets it to 0/1 too, but only AFTER this
      // subscribe is attached — too late to stop the first (residual) emit. First gen after a server
      // restart was fine (store starts 0); the 2nd+ gen hit this — surfaced once the flag went
      // always-on and real consecutive use began.
      try { idx.chatProcessStage.set(0) } catch { /* best-effort */ }
      unsubStage = idx.chatProcessStage.subscribe((s) => {
        _orchStage[sKey] = s
        const prevStage = _sp
        if (s !== _sp) { const n = Date.now(); console.log(`[bg-orch] stage ${_sp}→${s} (+${n - _st}ms)`); _sp = s; _st = n }
        // mid-publish only on a REAL 3→4 transition (main reply done → post-processing starts).
        // prevStage===3 guards against a residual stage-4 emit (prevStage -1/0) from a prior gen
        // firing a mid-publish of a stale chat. (s can re-enter 4 on auto-continue; midPublished caps it.)
        if (s === 4 && prevStage === 3 && !midPublished && typeof deps.kvSet === 'function'
          && (!control || control.allowIntermediate === true)
          && !(control && typeof control.isCancelled === 'function' && control.isCancelled())) {
          midPublished = true
          try {
            const cur = dbmod.getDatabase()
            const midChat = cur && cur.characters && cur.characters[charIdx] && Array.isArray(cur.characters[charIdx].chats)
              ? cur.characters[charIdx].chats[chatIdx] : null
            if (midChat) {
              const gvCur = (cur && cur.globalChatVariables) || {}
              let gvBeforeObj = {}; try { gvBeforeObj = JSON.parse(globalVarsBefore) } catch { /* empty */ }
              const gvDiffMid = diffGlobalVariables(gvBeforeObj, gvCur)
              const persisted = persistOrchResult(deps.kvSet, selectedCharId, selectedChatId, {
                chat: midChat,
                statics: (cur && cur.statics) || null,
                staticsMessagesDelta: ((cur && cur.statics ? (cur.statics.messages || 0) : 0) - staticsMsgsBefore),
                globalChatVariables: gvDiffMid.changed,
                globalChatVariablesDeleted: gvDiffMid.deleted,
                globalChatVariablesExpected: gvDiffMid.expected,
                threw: null,
              }, {
                kind: 'intermediate',
                operationId: control && control.operationId,
                resultKeyVersion: control && control.resultKeyVersion,
                kvGet: deps.kvGet,
                publishSeq: control && typeof control.nextPublishSequence === 'function'
                  ? control.nextPublishSequence() : undefined,
              })
              if (control && typeof control.onResultPersist === 'function') {
                control.onResultPersist(persisted, 'intermediate')
              }
              console.log('[bg-orch] mid-publish (main done, post running)')
            }
          } catch (e) { console.error('[bg-orch] mid-publish failed', e && e.message) }
        }
      })
    }
    let fullThrew = null
    const runWithOrchestrationAbort = async (task) => orchestrationAbortContext.run(llmAbort.signal, async () => {
      // requestChatData's higher-level retry/fallback loop also needs to see cancellation. This
      // bundle-only marker supplies the inherited signal when Hypa/trigger callers omit the arg.
      const priorSignal = globalThis.__bgOrchAbortSignal
      globalThis.__bgOrchAbortSignal = llmAbort.signal
      try { return await task() }
      finally {
        if (priorSignal === undefined) delete globalThis.__bgOrchAbortSignal
        else globalThis.__bgOrchAbortSignal = priorSignal
      }
    })
    try {
      delete globalThis.document
      delete globalThis.location
      if (mode === 'full') {
        // Run the WHOLE pipeline like the client (chatProcessIndex -1; char/chat come from the
        // selectedCharID store + chatPage we set, NOT this arg). The bundle's localStorage stub
        // returns null → no re-delegation. Reset doingChat first (-1 early-returns if a prior preview
        // left it true). A throw is caught here; we read the chat back below regardless so an
        // already-pushed main reply isn't lost.
        // `queued` stays the durable state while this run waits behind _previewLock and while the
        // bundle/DB is prepared. Flip to `running` at the last synchronous point before sendChat can
        // reach Hypa/trigger/main providers; a restart before here is therefore safely retryable.
        if (control && typeof control.onProviderStart === 'function') control.onProviderStart()
        idx.doingChat.set(false)
        try { await runWithOrchestrationAbort(() => idx.sendChat(-1, { signal: llmAbort.signal })) }
        catch (e) { fullThrew = e }
      } else {
        if (mode === 'llm') {
          await runWithOrchestrationAbort(() => idx.sendChat(charIdx, { previewLLM: true, signal: llmAbort.signal }))
        } else {
          await idx.sendChat(charIdx, { preview: true })
        }
      }
    } finally {
      if (sd !== undefined) globalThis.document = sd
      if (sl !== undefined) globalThis.location = sl
      const sKey = control && control.resultKeyVersion === 1 && validOperationId(control.operationId)
        ? control.operationId
        : stageKey(selectedCharId, selectedChatId)
      if (unsubStage) { try { unsubStage() } catch { /* ignore */ } delete _orchStage[sKey] }
      if (unsubStatus) { try { unsubStatus() } catch { /* ignore */ } delete _orchStatus[sKey] }
    }
    if (llmAbort && llmAbort.signal.aborted) {
      if ((externalSignal && externalSignal.aborted)
        || (control && typeof control.isCancelled === 'function' && control.isCancelled())) {
        throw new Error('orchestration cancelled')
      }
      throw new Error('llm aborted (600s timeout)')
    }
    if (mode === 'full') {
      const after = dbmod.getDatabase()
      const resultChat = after && after.characters && after.characters[charIdx] && Array.isArray(after.characters[charIdx].chats)
        ? after.characters[charIdx].chats[chatIdx] : null
      const gvAfter = (after && after.globalChatVariables) || {}
      let gvBeforeObj = {}; try { gvBeforeObj = JSON.parse(globalVarsBefore) } catch { /* empty */ }
      const gvDiff = diffGlobalVariables(gvBeforeObj, gvAfter)
      return {
        chat: resultChat,
        statics: (after && after.statics) || null,
        staticsMessagesDelta: ((after && after.statics ? (after.statics.messages || 0) : 0) - staticsMsgsBefore),
        globalChatVariables: gvDiff.changed,
        globalChatVariablesDeleted: gvDiff.deleted,
        globalChatVariablesExpected: gvDiff.expected,
        threw: fullThrew ? String((fullThrew && fullThrew.message) || fullThrew) : null,
      }
    }
    return mode === 'llm' ? idx.previewLLMResult : idx.previewFormated
  } finally {
    if (externalSignal) {
      try { externalSignal.removeEventListener('abort', forwardExternalAbort) } catch { /* ignore */ }
    }
    if (llmTimer) clearTimeout(llmTimer)
    release()
  }
}

// S2-C: byte-compare the client's formated (built by vite) against the server's preview
// (built by esbuild). Same source, different build → must match. Logs position/length of
// the first diff only (not content — avoids logging user prompt text).
function compareFormated(client, server) {
  if (!Array.isArray(client) || !Array.isArray(server)) return 'not-arrays(c=' + typeof client + ',s=' + typeof server + ')'
  const n = Math.min(client.length, server.length)
  for (let i = 0; i < n; i++) {
    const c = client[i] || {}, s = server[i] || {}
    if (c.role !== s.role || c.content !== s.content) {
      const cc = c.content || '', sc = s.content || ''
      let pos = 0
      while (pos < cc.length && pos < sc.length && cc[pos] === sc[pos]) pos++
      return 'DIFF@entry' + i + ' role(c=' + c.role + '/s=' + s.role + ') clen=' + cc.length + ' slen=' + sc.length + ' firstCharDiff@' + pos
    }
  }
  if (client.length !== server.length) return 'CONTENT-MATCH-but-LEN-DIFF c=' + client.length + '/s=' + server.length
  return 'BYTE-MATCH ✓ (' + client.length + ' entries)'
}

module.exports = function registerBgOrchestrator(app, deps) {
  const {
    sessionAuthMiddleware, ensureChatStore, getDbCache, getFullChatStore, DB_HEX_KEY,
    kvSet, kvGet, kvList, kvDel, kvGetUpdatedAt, // from Object.assign(deps, require('./db.cjs'))
  } = deps || {}
  if (!app || !sessionAuthMiddleware) {
    console.error('[bg-orch] registerBgOrchestrator: missing dependencies, skipping')
    return
  }
  const orchestrationRuns = deps && deps.orchestrationRuns
    ? deps.orchestrationRuns
    : createOrchestrationRunRegistry()

  // S1: locate the selected char/chat in the server's own db view (read/compare only).
  async function buildOrchestratorDbContext(chaId, chatId) {
    if (typeof ensureChatStore === 'function') await ensureChatStore()
    const fullChatStore = typeof getFullChatStore === 'function' ? getFullChatStore() : null
    const dbCache = typeof getDbCache === 'function' ? getDbCache() : null
    const charChats = fullChatStore && typeof fullChatStore.get === 'function' ? fullChatStore.get(chaId) : null
    const serverChat = charChats && typeof charChats.get === 'function' ? charChats.get(chatId) : null
    const stripped = dbCache && DB_HEX_KEY ? dbCache[DB_HEX_KEY] : null
    const serverChars = stripped && Array.isArray(stripped.characters) ? stripped.characters : null
    const charMeta = serverChars ? serverChars.find((c) => c && c.chaId === chaId) : null
    return {
      charFound: !!charChats,
      charName: charMeta ? charMeta.name : null,
      serverCharCount: serverChars ? serverChars.length : null,
      serverChatFound: !!serverChat,
      serverChatMsgCount: serverChat && Array.isArray(serverChat.message) ? serverChat.message.length : null,
    }
  }

  app.post('/api/bg-orchestrate', sessionAuthMiddleware, async (req, res) => {
    try {
      const { selectedCharId, selectedChatId, chatProcessIndex, currentChat, clientFormated, runLLM, runFull, detached } = req.body || {}
      // M8 rolling safety: a pre-M8 client cannot reconcile a lost start response and would launch
      // its client fallback while this detached run is already spending tokens. Do not start the
      // server pipeline unless the client advertises exact-operation start reconciliation.
      if (detached && (!req.body || req.body.startAckVersion !== 1)) {
        return res.json({
          handled: false,
          started: false,
          reason: 'start-reconciliation-required',
        })
      }
      const clientMsgCount = currentChat && Array.isArray(currentChat.message) ? currentChat.message.length : -1
      let ctx = null
      try { ctx = await buildOrchestratorDbContext(selectedCharId, selectedChatId) } catch (e) { console.error('[bg-orch] S1 db build error', e) }
      console.log(
        `[bg-orch] S1 db-input char=${selectedCharId} chat=${selectedChatId} processIdx=${chatProcessIndex} ` +
        `serverCharFound=${ctx ? ctx.charFound : '?'} serverChatMsgs=${ctx ? ctx.serverChatMsgCount : '?'} clientMsgs=${clientMsgCount}`
      )

      // S2 (assemble) / S3 (LLM): run server-side sendChat. runLLM ⇒ assemble + call the LLM
      // and report ONLY the reply length (S3 verify; reply text is the user's content, never
      // logged). Otherwise assemble-only + byte-compare (S2). Still { handled:false } so the
      // client keeps its own generation — S4 will flip this to take over the round-trip.
      // S4b real mode: ACK immediately, run the WHOLE pipeline in the background, persist to kv.
      // Client already returned handled:true and is polling. FULLY wrapped — a throw becomes a final
      // error-marked kv record (terminates poll), never an unhandledRejection. kvDel first clears any
      // stale result for this chat so the client's poll can't consume an OLD final result.
      if (detached && selectedCharId && selectedChatId && currentChat) {
        // New clients supply the id so the visible cancel button can target exactly this run.
        // Generate one for an old rolling client so ordinary orchestration stays compatible;
        // that old client simply retains its pre-M4 non-cancellable behavior until it reloads.
        const requestedOperationId = req.body && req.body.operationId
        const operationId = validOperationId(requestedOperationId) ? requestedOperationId : nodeCrypto.randomUUID()
        const resultKeyVersion = req.body && req.body.resultKeyVersion === 1 ? 1 : 0
        const requestedBaseChatRevision = req.body && req.body.baseChatRevision
        const operationMeta = {
          charId: String(selectedCharId),
          chatId: String(selectedChatId),
          ...(typeof requestedBaseChatRevision === 'string'
            && requestedBaseChatRevision.length > 0 && requestedBaseChatRevision.length <= 256
            ? { baseChatRevision: requestedBaseChatRevision }
            : {}),
        }
        const activeExisting = orchestrationRuns.get(operationId)
        if (activeExisting) {
          if (activeExisting.charId !== operationMeta.charId || activeExisting.chatId !== operationMeta.chatId) {
            return res.status(409).json({
              handled: false, started: false, operationId,
              reason: 'operation-coordinate-conflict',
            })
          }
          return res.json({
            handled: true, started: true, operationId, reused: true,
            state: orchestrationRuns.status(operationId),
            resultKeyVersion: activeExisting.resultKeyVersion || 0,
          })
        }
        if (resultKeyVersion === 1) {
          const durable = readOperationState(kvGet, operationId)
          if (durable) {
            if (durable.charId !== operationMeta.charId || durable.chatId !== operationMeta.chatId) {
              return res.status(409).json({
                handled: false, started: false, operationId,
                reason: 'operation-coordinate-conflict',
              })
            }
            // `queued` is the sole restartable state: it was durably recorded before provider work
            // and a process death may have happened before the run began. Every later state is an
            // exact paid-work tombstone and must never launch the same operation again.
            if (durable.state !== 'queued') {
              return res.json({
                handled: true, started: true, operationId, reused: true,
                state: durable.state, resultKeyVersion: 1,
              })
            }
          }
        }
        const started = orchestrationRuns.start(operationId, {
          ...operationMeta, resultKeyVersion,
        })
        if (!started.started) {
          if (started.reason === 'capacity') {
            // A durable `queued` record means provider work has not started yet. Remove it before
            // explicitly rejecting so the client fallback cannot leave a restartable ghost behind.
            if (resultKeyVersion === 1) {
              try { if (typeof kvDel === 'function') kvDel(operationStateKey(operationId)) } catch { /* best-effort */ }
            }
            return res.status(429).json({
              handled: false,
              started: false,
              operationId,
              reason: 'orchestration-capacity',
            })
          }
          if (!started.run
            || started.run.charId !== String(selectedCharId)
            || started.run.chatId !== String(selectedChatId)) {
            return res.status(409).json({
              handled: false,
              started: false,
              operationId,
              reason: 'operation-coordinate-conflict',
            })
          }
          // A repeated POST with the same active id must not launch/cost a second generation.
          return res.json({
            handled: true,
            started: true,
            operationId,
            reused: true,
            state: orchestrationRuns.status(operationId),
            resultKeyVersion: started.run.resultKeyVersion || 0,
          })
        }
        const activeRun = started.run
        const resultKey = resultKeyVersion === 1
          ? operationResultKey(operationId)
          : orchResultKey(selectedCharId, selectedChatId)
        if (resultKeyVersion === 1) {
          const queued = writeOperationState(kvSet, operationId, operationMeta, 'queued')
          if (!queued.written) {
            orchestrationRuns.discard(operationId, activeRun)
            return res.status(503).json({
              handled: false, started: false, operationId,
              reason: 'operation-state-store-unavailable', resultKeyVersion: 1,
            })
          }
        }
        try { if (typeof kvDel === 'function') kvDel(resultKey) } catch { /* best-effort */ }
        void (async () => {
          const t0 = Date.now()
          let terminalState = 'finished'
          try {
            const result = await runServerPreview(
              { getDbCache, DB_HEX_KEY, kvSet, kvGet }, selectedCharId, selectedChatId, currentChat, 'full',
              {
                signal: activeRun.controller.signal,
                isCancelled: () => activeRun.cancelled,
                operationId,
                resultKeyVersion,
                globalChatVariablesSnapshot: req.body && req.body.globalVariablesVersion === 1
                  ? req.body.currentGlobalChatVariables : undefined,
                globalChatVariablesSnapshotVersion: req.body && req.body.globalVariablesVersion === 1 ? 1 : 0,
                onProviderStart: () => {
                  if (resultKeyVersion !== 1) return
                  const running = writeOperationState(kvSet, operationId, operationMeta, 'running')
                  if (!running.written) throw running.error || new Error('operation state store unavailable')
                },
                // A tab running the pre-M7 client ignores publishSeq and can still reverse two
                // different revisions. During rolling deployment, withhold the optional early
                // snapshot unless the start request advertises ordered-result support.
                allowIntermediate: req.body && req.body.resultOrderVersion === 1,
                nextPublishSequence: () => orchestrationRuns.nextPublishSequence(operationId, activeRun),
                onResultPersist: (persisted, kind) => {
                  if (resultKeyVersion === 1 && persisted && persisted.persisted) {
                    writeOperationState(kvSet, operationId, operationMeta,
                      kind === 'intermediate' ? 'running-result-ready' : 'result-ready')
                  }
                },
              },
            )
            if (activeRun.cancelled) {
              console.log(`[bg-orch] S4b cancelled: op=${operationId} TOTAL=${Date.now() - t0}ms (result discarded)`)
              return
            }
            const persisted = persistOrchResult(kvSet, selectedCharId, selectedChatId, result, {
              kind: terminalOrchResultKind(result, currentChat),
              operationId,
              resultKeyVersion,
              kvGet,
              publishSeq: orchestrationRuns.nextPublishSequence(operationId, activeRun),
            })
            terminalState = persisted.persisted ? 'finished' : 'delivery-failed'
            if (resultKeyVersion === 1) {
              writeOperationState(kvSet, operationId, operationMeta,
                persisted.persisted ? 'result-ready' : 'delivery-failed')
            }
            const msgs = result && result.chat && Array.isArray(result.chat.message) ? result.chat.message.length : -1
            console.log(`[bg-orch] S4b detached done: msgs=${msgs} threw=${result ? result.threw : '?'} TOTAL=${Date.now() - t0}ms (${persisted.persisted ? 'kv saved' : 'delivery failed'})`)
          } catch (e) {
            if (activeRun.cancelled) {
              console.log(`[bg-orch] S4b cancelled: op=${operationId} TOTAL=${Date.now() - t0}ms (no fallback/result)`)
            } else {
              const persisted = persistOrchResult(kvSet, selectedCharId, selectedChatId, { chat: null, statics: null, staticsMessagesDelta: 0, globalChatVariables: {}, threw: String((e && e.message) || e) }, {
                kind: 'terminal-error',
                operationId,
                resultKeyVersion,
                kvGet,
                publishSeq: orchestrationRuns.nextPublishSequence(operationId, activeRun),
              })
              terminalState = persisted.persisted ? 'finished' : 'delivery-failed'
              if (resultKeyVersion === 1) {
                writeOperationState(kvSet, operationId, operationMeta,
                  persisted.persisted ? 'result-ready' : 'delivery-failed')
              }
              console.error('[bg-orch] S4b detached error:', (e && e.message) || e)
            }
          } finally {
            orchestrationRuns.finish(operationId, activeRun, terminalState)
          }
        })()
        return res.json({ handled: true, started: true, operationId, resultKeyVersion })
      }

      let s2 = null
      if (selectedCharId && selectedChatId && currentChat) {
        try {
          const t0 = Date.now()
          if (runFull) {
            // S4a verify: run the WHOLE pipeline, read the chat back, park in kv. handled:false →
            // client keeps its own generation. The stage/LLM markers print during the run; this is
            // the TOTAL. Content never logged.
            const result = await runServerPreview({ getDbCache, DB_HEX_KEY, kvSet }, selectedCharId, selectedChatId, currentChat, 'full')
            persistOrchResult(kvSet, selectedCharId, selectedChatId, result, {
              kind: terminalOrchResultKind(result, currentChat),
            })
            const msgs = result && result.chat && Array.isArray(result.chat.message) ? result.chat.message.length : -1
            let bytes = -1; try { bytes = JSON.stringify(result).length } catch { /* ignore */ }
            s2 = { mode: 'full', msgs, threw: result ? result.threw : 'no-result', staticsDelta: result ? result.staticsMessagesDelta : null, bytes, ms: Date.now() - t0 }
            console.log(`[bg-orch] S4a full done: msgs=${msgs} threw=${s2.threw} staticsDelta=${s2.staticsDelta} bytes=${bytes} TOTAL=${s2.ms}ms (kv saved)`)
          } else if (runLLM) {
            const reply = await runServerPreview({ getDbCache, DB_HEX_KEY }, selectedCharId, selectedChatId, currentChat, 'llm')
            const replyLen = typeof reply === 'string' ? reply.length : -1
            s2 = { mode: 'llm', replyLen, ms: Date.now() - t0 }
            console.log(`[bg-orch] S3 LLM reply: len=${replyLen} ms=${s2.ms}`)
          } else {
            const serverFormated = await runServerPreview({ getDbCache, DB_HEX_KEY }, selectedCharId, selectedChatId, currentChat, 'assemble')
            const entries = Array.isArray(serverFormated) ? serverFormated.length : -1
            const totalChars = Array.isArray(serverFormated) ? serverFormated.reduce((a, m) => a + ((m && m.content && m.content.length) || 0), 0) : -1
            s2 = { entries, totalChars, ms: Date.now() - t0 }
            console.log(`[bg-orch] S2 preview: entries=${entries} totalChars=${totalChars} ms=${s2.ms}`)
            // S2-C: if the client sent its own formated (diag marker), byte-compare.
            if (Array.isArray(clientFormated)) {
              s2.compare = compareFormated(clientFormated, serverFormated)
              console.log('[bg-orch] S2C compare: ' + s2.compare)
            }
          }
        } catch (e) {
          s2 = { error: String((e && e.message) || e) }
          console.error('[bg-orch] S2/S3 preview error:', s2.error)
        }
      }

      res.json({ handled: false, s1: Object.assign({ clientMsgCount }, ctx || {}), s2 })
    } catch (e) {
      console.error('[bg-orch] handler error', e)
      res.json({ handled: false, error: String((e && e.message) || e) })
    }
  })

  // M8: reconcile a lost detached-start response by exact operation identity. Active/finished
  // registry records cover this process; a parked result covers a restart after completion. 404 is
  // the only state that permits the client to retry the same POST id.
  app.get('/api/bg-orchestrate-status/:operationId', sessionAuthMiddleware, (req, res) => {
    const operationId = req.params.operationId
    const charId = req.query && typeof req.query.charId === 'string' ? req.query.charId : ''
    const chatId = req.query && typeof req.query.chatId === 'string' ? req.query.chatId : ''
    if (!validOperationId(operationId) || !charId || !chatId) {
      return res.status(400).json({ accepted: false, state: 'invalid-request' })
    }
    const run = orchestrationRuns.get(operationId)
    if (run && run.charId === charId && run.chatId === chatId) {
      const state = run.state === 'running' && run.cancelled ? 'cancelled' : run.state
      return res.json({ accepted: true, operationId, state, resultKeyVersion: run.resultKeyVersion || 0 })
    }
    if (typeof kvGet === 'function') {
      const parked = peekResult(kvGet, operationResultKey(operationId))
      if (parked.state === 'found' && parked.record.operationId === operationId) {
        if (parked.record.charId !== charId || parked.record.chatId !== chatId) {
          return res.status(409).json({ accepted: false, operationId, state: 'coordinate-conflict' })
        }
        return res.json({ accepted: true, operationId, state: 'result-ready', resultKeyVersion: 1 })
      }
      // Rolling M8 result parked under the old char/chat key.
      const legacyParked = peekResult(kvGet, orchResultKey(charId, chatId))
      if (legacyParked.state === 'found' && legacyParked.record.operationId === operationId) {
        return res.json({ accepted: true, operationId, state: 'result-ready', resultKeyVersion: 0 })
      }
      const durable = readOperationState(kvGet, operationId)
      if (durable) {
        if (durable.charId !== charId || durable.chatId !== chatId) {
          return res.status(409).json({ accepted: false, operationId, state: 'coordinate-conflict' })
        }
        // The start handler can safely resume this exact state. Return the protocol's exact
        // `missing` shape so reconciliation retries the same operation id instead of waiting on a
        // run that never began.
        if (durable.state === 'queued') {
          return res.status(404).json({ accepted: false, operationId, state: 'missing' })
        }
        return res.json({
          accepted: true, operationId, state: orphanedOperationState(durable), resultKeyVersion: 1,
        })
      }
    }
    return res.status(404).json({ accepted: false, operationId, state: 'missing' })
  })

  // M4: whole-pipeline cancellation. Authentication matches the start/result routes. The ACK
  // means the server has synchronously delivered abort to the exact active controller. Do not
  // delete the chat-scoped result key here: another tab may have a different operation for the
  // same chat. The cancelling client invalidates its in-flight poll on ACK, and the detached
  // finally suppresses every later terminal persist/fallback from this exact run.
  app.delete('/api/bg-orchestrate/:operationId', sessionAuthMiddleware, (req, res) => {
    const operationId = req.params.operationId
    if (!validOperationId(operationId)) return res.status(400).json({ cancelled: false, reason: 'invalid-operation-id' })
    const outcome = orchestrationRuns.cancel(operationId)
    if (!outcome.cancelled || !outcome.run) {
      const charId = req.query && typeof req.query.charId === 'string' ? req.query.charId : ''
      const chatId = req.query && typeof req.query.chatId === 'string' ? req.query.chatId : ''
      if (!charId || !chatId || typeof kvGet !== 'function' || typeof kvSet !== 'function') {
        return res.status(409).json({ cancelled: false, reason: 'not-active' })
      }
      const durable = readOperationState(kvGet, operationId)
      if (durable && (durable.charId !== charId || durable.chatId !== chatId)) {
        return res.status(409).json({ cancelled: false, reason: 'operation-coordinate-conflict' })
      }
      if (durable && (durable.state === 'delivered' || durable.state === 'result-ready')) {
        return res.status(409).json({ cancelled: false, reason: 'already-finished' })
      }
      // DELETE can beat the start POST while that handler awaits DB context. Persist the exact
      // cancellation first; the later POST sees this tombstone and never reaches provider work.
      const cancelled = writeOperationState(kvSet, operationId, durable || { charId, chatId }, 'cancelled')
      if (!cancelled.written) {
        return res.status(503).json({ cancelled: false, reason: 'operation-state-store-unavailable' })
      }
      try { if (typeof kvDel === 'function') kvDel(operationResultKey(operationId)) } catch { /* TTL fallback */ }
      console.log(`[bg-orch] cancel tombstone: op=${operationId} state=not-active`)
      return res.json({ cancelled: true, operationId, state: 'cancelled-before-or-after-restart' })
    }
    if (outcome.run.resultKeyVersion === 1) {
      const durable = writeOperationState(kvSet, operationId, outcome.run, 'cancelled')
      // Operation-keyed payloads cannot belong to another tab. Drop any already-published
      // intermediate revision so a stale recovery marker cannot resurrect it after cancellation.
      let resultRemoved = false
      try {
        if (typeof kvDel === 'function') {
          kvDel(operationResultKey(operationId))
          resultRemoved = true
        }
      } catch { /* the durable tombstone still suppresses delivery */ }
      // Abort has reached the in-memory run. Confirm it to the client only when either the durable
      // tombstone or exact result deletion also survives a process restart.
      if (!durable.written && !resultRemoved) {
        return res.status(503).json({
          cancelled: false, operationId, reason: 'cancellation-cleanup-unconfirmed',
        })
      }
    }
    console.log(`[bg-orch] cancel ACK: op=${operationId} state=${outcome.reason}`)
    res.json({ cancelled: true, operationId, state: outcome.reason })
  })

  // M10: operation-keyed delivery. A short server-side claim makes the first live PWA the sole
  // consumer of a parked revision; if that page dies before durable save, another page may claim
  // it after the lease expires. The result itself remains non-destructive until exact ACK.
  app.get('/api/bg-orchestrate-result/:operationId', sessionAuthMiddleware, (req, res) => {
    try {
      const operationId = req.params.operationId
      const consumerId = req.query && req.query.consumerId
      const charId = req.query && typeof req.query.charId === 'string' ? req.query.charId : ''
      const chatId = req.query && typeof req.query.chatId === 'string' ? req.query.chatId : ''
      if (!validOperationId(operationId) || !validOperationId(consumerId) || !charId || !chatId) {
        return res.status(400).json({ found: false, error: 'invalid-operation-delivery-request' })
      }
      if (typeof kvGet !== 'function') {
        return res.status(503).json({ found: false, error: 'result-store-unavailable' })
      }
      const state = readOperationState(kvGet, operationId)
      const run = orchestrationRuns.get(operationId)
      if (state && (state.charId !== charId || state.chatId !== chatId)) {
        return res.status(409).json({ found: false, error: 'operation-coordinate-conflict' })
      }
      const cancelled = (state && state.state === 'cancelled')
        || (run && (run.cancelled || run.state === 'cancelled'))
      if (cancelled || (state && state.state === 'delivered')) {
        return res.json({
          found: false,
          operationId,
          operationState: cancelled ? 'cancelled' : 'delivered',
          stage: 0,
          status: [],
        })
      }
      const key = operationResultKey(operationId)
      const delivery = peekResult(kvGet, key)
      if (delivery.state === 'missing') {
        const operationState = run
          ? (run.state === 'running' && run.cancelled ? 'cancelled' : run.state)
          : orphanedOperationState(state)
        return res.json({
          found: false, operationId, operationState,
          stage: _orchStage[operationId] ?? 0,
          status: _orchStatus[operationId] || [],
        })
      }
      if (delivery.state !== 'found') {
        return res.status(500).json({ found: false, error: 'invalid-result-record' })
      }
      let parsed = delivery.record
      if (parsed.operationId !== operationId || parsed.charId !== charId || parsed.chatId !== chatId) {
        return res.status(409).json({ found: false, error: 'operation-coordinate-conflict' })
      }
      const now = Date.now()
      const claim = parsed.deliveryClaim
      if (claim && claim.consumerId !== consumerId && now - claim.claimedAt < ORCH_RESULT_CLAIM_TTL_MS) {
        return res.status(409).json({
          found: false, error: 'result-claimed',
          retryAfterMs: ORCH_RESULT_CLAIM_TTL_MS - (now - claim.claimedAt),
        })
      }
      // Refresh an active consumer's lease at a bounded cadence. The client sends a lightweight
      // heartbeat while IndexedDB/root persistence is in progress; without this refresh, a slow
      // save could cross the two-minute TTL and let a second PWA consume the same revision.
      if (!claim || claim.consumerId !== consumerId || now - claim.claimedAt >= ORCH_RESULT_CLAIM_REFRESH_MS) {
        if (typeof kvSet !== 'function') {
          return res.status(503).json({ found: false, error: 'result-store-unavailable' })
        }
        parsed = { ...parsed, deliveryClaim: { consumerId, claimedAt: now } }
        kvSet(key, JSON.stringify(parsed))
      }
      if (req.query && req.query.heartbeat === '1') {
        return res.json({
          found: true, operationId, resultId: parsed.resultId,
          publishSeq: parsed.publishSeq, resultKeyVersion: 1,
        })
      }
      console.log(
        `[bg-orch] result peeked ${chatId} op=${operationId} seq=${parsed.publishSeq || '-'} ` +
        `rev=${parsed.resultId || '-'} kind=${parsed.kind || '-'} final=${parsed.final}`
      )
      return res.json({ ...orchResultResponse(parsed), resultKeyVersion: 1 })
    } catch (e) {
      return res.status(500).json({ found: false, error: String((e && e.message) || e) })
    }
  })

  app.delete('/api/bg-orchestrate-result/:operationId/:resultId', sessionAuthMiddleware, (req, res) => {
    try {
      const { operationId, resultId } = req.params
      const consumerId = req.query && req.query.consumerId
      if (!validOperationId(operationId) || !validOperationId(resultId) || !validOperationId(consumerId)) {
        return res.status(400).json({ acked: false, reason: 'invalid-operation-delivery-request' })
      }
      if (typeof kvGet !== 'function' || typeof kvSet !== 'function' || typeof kvDel !== 'function') {
        return res.status(503).json({ acked: false, reason: 'result-store-unavailable' })
      }
      const key = operationResultKey(operationId)
      const delivery = peekResult(kvGet, key)
      if (delivery.state === 'invalid') {
        return res.status(409).json({ acked: false, reason: 'invalid' })
      }
      if (delivery.state === 'found') {
        const record = delivery.record
        if (record.operationId !== operationId || record.resultId !== resultId) {
          return res.status(409).json({ acked: false, reason: 'superseded' })
        }
        if (record.deliveryClaim && record.deliveryClaim.consumerId !== consumerId) {
          return res.status(409).json({ acked: false, reason: 'claimed' })
        }
      }
      const run = orchestrationRuns.get(operationId)
      // The result record itself carries exact operation coordinates. It remains a valid ACK
      // authority if the smaller lifecycle-state write failed or expired before a very slow save.
      const stateMeta = run || readOperationState(kvGet, operationId)
        || (delivery.state === 'found' ? delivery.record : null)
      if (!stateMeta) return res.status(409).json({ acked: false, reason: 'missing-operation' })
      const isTerminalRevision = delivery.state === 'found'
        ? delivery.record.final !== false && delivery.record.kind !== 'intermediate'
        : stateMeta.state === 'delivered'
      // An intermediate ACK commits only that revision. Marking the whole operation delivered here
      // creates a gap where the client stops before the server publishes its terminal post-result.
      if (delivery.state === 'found') {
        const nextState = isTerminalRevision ? 'delivered' : 'running-result-consumed'
        const durable = writeOperationState(kvSet, operationId, stateMeta, nextState)
        if (!durable.written) {
          return res.status(503).json({ acked: false, reason: 'result-store-unavailable' })
        }
      }
      // Persist delivered before deleting the payload. If deletion throws, GET already suppresses
      // redispatch and a repeated ACK can finish cleanup without a duplicate merge.
      kvDel(key)
      if (isTerminalRevision) orchestrationRuns.markDelivered(operationId)
      console.log(`[bg-orch] result ACK op=${operationId} rev=${resultId} state=deleted`)
      return res.json({ acked: true, state: delivery.state === 'missing' ? 'absent' : 'deleted' })
    } catch (e) {
      return res.status(500).json({ acked: false, error: String((e && e.message) || e) })
    }
  })

  // S4b: explicit-ACK clients peek and retain the exact result revision until their merged DB save
  // succeeds. A rolling old client omits delivery=ack-v1 and keeps the former one-shot consume
  // behavior, avoiding repeated intermediate merges while an old tab is paired with this server.
  app.get('/api/bg-orchestrate-result/:charId/:chatId', sessionAuthMiddleware, (req, res) => {
    try {
      if (typeof kvGet !== 'function') return res.json({ found: false })
      const key = orchResultKey(req.params.charId, req.params.chatId)
      const explicitAck = req.query && req.query.delivery === 'ack-v1'
      const delivery = explicitAck
        ? peekResult(kvGet, key)
        : consumeResult(kvGet, kvDel, key)
      if (delivery.state === 'missing') return res.json({
        found: false,
        stage: _orchStage[stageKey(req.params.charId, req.params.chatId)] ?? 0,
        status: _orchStatus[stageKey(req.params.charId, req.params.chatId)] || [],
      })
      if (delivery.state !== 'found') return res.status(500).json({ found: false, error: 'invalid-result-record' })
      let parsed = delivery.record
      // A result parked by the pre-M6 server has no revision id. During a rolling restart the
      // new client already requests explicit ACK delivery, so leaving that record unchanged would
      // make an intermediate snapshot peek/save forever. Upgrade it in place before responding;
      // a write failure returns 500 and leaves the legacy record available for a later retry.
      if (explicitAck && !validOperationId(parsed.resultId)) {
        if (typeof kvSet !== 'function') {
          return res.status(503).json({ found: false, error: 'result-store-unavailable' })
        }
        parsed = { ...parsed, resultId: nodeCrypto.randomUUID() }
        kvSet(key, JSON.stringify(parsed))
      }
      console.log(
        `[bg-orch] result ${explicitAck ? 'peeked' : 'consumed-legacy'} ${req.params.chatId} ` +
        `op=${parsed.operationId || '-'} seq=${parsed.publishSeq || '-'} rev=${parsed.resultId || '-'} ` +
        `kind=${parsed.kind || '-'} final=${parsed.final} chat=${parsed.chat ? 'y' : 'n'} ` +
        `staticsDelta=${parsed.staticsMessagesDelta || 0}`
      )
      res.json(orchResultResponse(parsed))
    } catch (e) {
      res.status(500).json({ error: String((e && e.message) || e) })
    }
  })

  // Delete only the revision the client durably saved. The synchronous compare+delete prevents a
  // late intermediate ACK from deleting a terminal revision that overwrote the same chat key.
  app.delete('/api/bg-orchestrate-result/:charId/:chatId/:resultId', sessionAuthMiddleware, (req, res) => {
    try {
      if (typeof kvGet !== 'function' || typeof kvDel !== 'function') {
        return res.status(503).json({ acked: false, reason: 'result-store-unavailable' })
      }
      if (!validOperationId(req.params.resultId)) {
        return res.status(400).json({ acked: false, reason: 'invalid-result-id' })
      }
      const key = orchResultKey(req.params.charId, req.params.chatId)
      const outcome = acknowledgeResult(kvGet, kvDel, key, req.params.resultId)
      if (!outcome.acked) {
        return res.status(409).json({ acked: false, reason: outcome.state })
      }
      console.log(`[bg-orch] result ACK ${req.params.chatId} rev=${req.params.resultId} state=${outcome.state}`)
      res.json({ acked: true, state: outcome.state })
    } catch (e) {
      res.status(500).json({ acked: false, error: String((e && e.message) || e) })
    }
  })

  // Bound kv growth — purge orchestration results the client never consumed (page closed/reloaded).
  if (typeof kvList === 'function' && typeof kvGetUpdatedAt === 'function' && typeof kvDel === 'function') {
    setInterval(() => {
      try {
        const now = Date.now()
        for (const prefix of [ORCH_RESULT_PREFIX, OPERATION_RESULT_PREFIX, OPERATION_STATE_PREFIX]) {
          for (const key of kvList(prefix)) {
            const at = kvGetUpdatedAt(key)
            if (at != null && now - at > ORCH_RESULT_TTL_MS) kvDel(key)
          }
        }
      } catch { /* best-effort */ }
    }, 10 * 60 * 1000)
  }
}

'use strict'

const { AsyncLocalStorage } = require('async_hooks')

// Carries one orchestration's AbortSignal through every async descendant without
// leaking it into unrelated Express requests that happen to use global fetch at
// the same time. The server's fetch shim reads this context at the network edge.
function createOrchestrationAbortContext() {
  const storage = new AsyncLocalStorage()

  return {
    run(signal, task) {
      return storage.run({ signal }, task)
    },
    getSignal() {
      const store = storage.getStore()
      return store && store.signal ? store.signal : null
    },
    withSignal(init) {
      const signal = this.getSignal()
      if (!signal || (init && init.signal)) return init
      return { ...(init || {}), signal }
    },
  }
}

module.exports = { createOrchestrationAbortContext }

'use strict'

// Active whole-pipeline orchestrations keyed by a client-generated operation id.
// Keeping this lifecycle separate makes cancellation semantics testable without loading
// the 8 MB sendChat bundle or an Express server.
function createOrchestrationRunRegistry(options) {
  const runs = new Map()
  const now = options && typeof options.now === 'function' ? options.now : Date.now
  const retainMs = options && Number.isFinite(options.retainMs) ? Math.max(0, options.retainMs) : 30 * 60 * 1000
  const maxRetained = options && Number.isFinite(options.maxRetained) ? Math.max(1, options.maxRetained) : 128

  function pruneExpired() {
    const cutoff = now() - retainMs
    for (const [id, run] of runs) {
      if (run.state !== 'running' && run.finishedAt <= cutoff) deleteRun(id, run)
    }
  }

  function makeRoom() {
    pruneExpired()
    if (runs.size < maxRetained) return
    for (const [id, run] of runs) {
      if (runs.size < maxRetained) break
      if (run.state !== 'running') deleteRun(id, run)
    }
  }

  function deleteRun(operationId, run) {
    if (runs.get(operationId) !== run) return false
    if (run.retentionTimer) clearTimeout(run.retentionTimer)
    runs.delete(operationId)
    return true
  }

  function start(operationId, meta) {
    if (typeof operationId !== 'string' || operationId.length === 0) {
      return { started: false, reason: 'invalid-operation-id', run: null }
    }
    // Check the exact identity before evicting any terminal tombstone. At capacity, deleting the
    // caller's own finished record first would turn a lost-response retry into a second paid run.
    pruneExpired()
    const existing = runs.get(operationId)
    if (existing) {
      const state = statusOf(existing)
      return { started: false, reason: state === 'running' ? 'already-active' : `already-${state}`, run: existing }
    }
    makeRoom()
    // Terminal records can make room, active provider runs cannot. Enforce a true hard bound rather
    // than silently growing the registry when every retained record is still running.
    if (runs.size >= maxRetained) {
      return { started: false, reason: 'capacity', run: null }
    }

    const run = {
      ...(meta || {}),
      operationId,
      controller: new AbortController(),
      cancelled: false,
      publishSeq: 0,
      state: 'running',
      startedAt: now(),
    }
    runs.set(operationId, run)
    return { started: true, reason: 'started', run }
  }

  function cancel(operationId) {
    const run = get(operationId)
    if (!run || run.state !== 'running') return { cancelled: false, reason: 'not-active', run: run || null }
    if (!run.cancelled) {
      run.cancelled = true
      try { run.controller.abort(new Error('orchestration cancelled')) } catch { run.controller.abort() }
      return { cancelled: true, reason: 'cancelled', run }
    }
    return { cancelled: true, reason: 'already-cancelled', run }
  }

  function statusOf(run) {
    if (!run) return 'missing'
